/// TASK-218: shared implementation backing both `aida queue rework SPEC`
/// and the top-level `aida rework SPEC` alias. Encapsulates the three-
/// command rework sequence (status flip + queue add + optional session
/// launch) so the implementer → reviewer → fixup loop is one verb.
/// trace:TASK-218 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_queue_rework(
    storage: &Storage,
    id: &str,
    work: bool,
    for_role: Option<&str>,
    status_override: Option<&str>,
    reason: Option<&str>,
    resume: bool,
    force: bool,
    steal: bool,
    permission_mode: Option<&str>,
    no_pull: bool,
    user: Option<&str>,
) -> Result<()> {
    // `--resume` chains through to `aida queue work --resume` (TASK-112,
    // shipped). It implies `--work` — there is nothing to resume without
    // launching a session. trace:BUG-236 | ai:claude
    let work = work || resume;

    let user_id = current_user_id(user);
    let store = storage.load()?;

    // Resolve the requirement (UUID first, then SPEC-ID).
    let req = if let Ok(uuid) = uuid::Uuid::parse_str(id) {
        store.requirements.iter().find(|r| r.id == uuid)
    } else {
        store.get_requirement_by_spec_id(id)
    }
    .ok_or_else(|| not_found::requirement_not_found(id, Some(storage.path())))?;

    let req_id = req.id;
    let spec_id = req.spec_id.clone().unwrap_or_else(|| "???".to_string());
    let display_id = req
        .agreed_id
        .clone()
        .or_else(|| req.spec_id.clone())
        .unwrap_or_else(|| "???".to_string());
    let title = req.title.clone();
    let current_status = req.status.clone();

    // Smart target-status resolution. `--status` always wins; otherwise
    // pick per the table in TASK-218's spec. See `rework_smart_target`.
    let smart_target = rework_smart_target(&current_status);
    let target_status: Option<RequirementStatus> = match status_override {
        Some(s) => Some(parse_status(s)?),
        None => smart_target,
    };

    // Guards. Terminal status (Completed/Rejected) + already-InProgress
    // both require --force. We surface the spec id in the error so the
    // user can copy the exact `--force` invocation.
    if matches!(
        current_status,
        RequirementStatus::Completed | RequirementStatus::Rejected
    ) && !force
    {
        // BUG-671: override flag on the FIRST line so agent mode (first-line
        // error summary only) surfaces it. trace:BUG-671 | ai:claude
        anyhow::bail!(
            "{} is {} — re-opening closed work is usually a mistake; pass --force to \
             override.\n  Otherwise, file a new requirement that supersedes {}.",
            display_id,
            current_status,
            display_id
        );
    }
    if matches!(current_status, RequirementStatus::InProgress) && !force {
        eprintln!(
            "  {} {} is already In Progress — re-queueing without status \
             flip. Pass `--force` to silence this warning.",
            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
            display_id
        );
    }

    // Status flip (if any). update_atomically works for both SQLite and
    // git-canonical paths; queue done uses the same approach.
    if let Some(ref new_status) = target_status {
        if new_status != &current_status {
            let new_status = new_status.clone();
            let now = chrono::Utc::now();
            storage.update_atomically(|s| {
                if let Some(r) = s.requirements.iter_mut().find(|r| r.id == req_id) {
                    r.set_status_from_str(&format!("{:?}", new_status));
                    r.modified_at = now;
                }
            })?;
            record_role_activity(&spec_id, "rework");
            update_manifest_for_status(&spec_id, &format!("{:?}", new_status));
            println!(
                "{} {} status: {} → {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                display_id.bold(),
                current_status.to_string().dimmed(),
                new_status.to_string().cyan(),
            );
        }
    }

    // Optional audit comment. Mirrors `aida comment add` path so the
    // entry shows up in `aida show <spec>` history.
    if let Some(reason_text) = reason {
        let author = get_default_author();
        let comment = aida_core::Comment::new(author, reason_text.to_string());
        storage.update_atomically(|s| {
            if let Some(r) = s.requirements.iter_mut().find(|r| r.id == req_id) {
                r.add_comment(comment);
            }
        })?;
        println!(
            "  {} reason captured as comment ({} chars)",
            "·".dimmed(),
            reason_text.chars().count()
        );
    }

    // Route resolution: --for wins, else the active role, else error if
    // queueing requires a role (we let the queue_add path stay unrouted
    // — that's a legitimate state too, matching `aida queue add` default
    // when no role is active).
    let for_role_resolved: Option<String> = match for_role {
        Some("any") => None,
        Some(role) => Some(role.to_string()),
        None => std::env::var("AIDA_SESSION_ROLE")
            .ok()
            .filter(|s| !s.is_empty()),
    };

    // Queue add. queue_add upserts by requirement_id (replaces same-spec
    // entries), so re-running rework is idempotent on the queue side.
    let entry = aida_core::QueueEntry {
        user_id: user_id.clone(),
        requirement_id: req_id,
        position: i64::MAX, // backend resolves to existing_max + 1000
        added_by: user_id.clone(),
        note: reason.map(|r| r.to_string()),
        added_at: chrono::Utc::now(),
        for_role: for_role_resolved.clone(),
        for_scope: None,
        for_session: None,
        added_by_machine: None,
    };
    storage.queue_add(entry)?;
    record_role_activity(&spec_id, "queue-add");
    let routing = match &for_role_resolved {
        Some(r) => format!(" [for:{}]", r).cyan().to_string(),
        None => String::new(),
    };
    println!(
        "{} Queued {} ({}){}",
        crate::glyph(crate::glyphs::Glyph::Check).green(),
        display_id.bold(),
        title,
        routing
    );

    // Optional --work chain. We don't run this in a sub-process — call
    // `handle_queue_work` directly with the same storage handle so any
    // failure surfaces here. trace:TASK-218 | ai:claude
    if work {
        handle_queue_work(
            storage,
            &user_id,
            Some(&spec_id),
            permission_mode,
            /* sandbox */ false,
            /* no_launch */ false,
            for_role_resolved.as_deref(),
            no_pull,
            /* type_filter */ None,
            /* branch_override */ None,
            /* path_override */ None,
            /* stack */ false,
            /* base */ None,
            /* force_base */ false,
            steal,
            /* force_claim */ false,
            // Bare `--resume` → resume the scope's most recent recorded
            // claude session (`resolve_queue_work_launch` fails clean when
            // there is none). trace:BUG-236 | ai:claude
            if resume { Some("") } else { None },
            /* fresh */ false,
            /* list_sessions */ false,
            /* session_id */ None,
            // STORY-761: the convenience chain honors the uniform
            // `[agents] vendor` knob instead of hard-coding claude.
            &find_project_root()
                .ok()
                .and_then(|root| aida_core::agents_config::resolve_default_vendor(&root))
                .unwrap_or_else(|| "claude".to_string()),
            /* no_human */ false,
            // TASK-1060: the `queue add --work` convenience chain has no `--zen`.
            /* autonomy */
            AutonomyMode::Default,
            /* batch_name */ None,
            /* quiet */ false,
            /* allow_stale_base */ false,
            /* allow_intermediate_only */ false,
            /* complexity */ None,
            /* assist_est */ None,
            /* effort */ None,
            /* strict */ false,
            /* plan_only */ false,
            /* guided */ false,
            /* dry_run */ false,
        )?;
    } else {
        println!(
            "  ({})",
            format!(
                "run `aida queue work {}` to start a session for this spec",
                display_id
            )
            .dimmed()
        );
    }

    Ok(())
}

/// STORY-42: resolved pickup plan — which queue entries we're working,
/// in which mode, against which scope/branch, with which skill.
/// trace:STORY-42 | ai:claude
#[derive(Debug, Clone)]
struct QueueWorkPlan {
    /// "head" (no arg), "item" (single queued entry), or "cluster"
    /// (parent scope draining children).
    mode: QueueWorkMode,
    /// Pre-resolved view of each queued entry we're picking up, in
    /// queue order. Carries the display SPEC-ID and current status
    /// at plan time so manifest writing doesn't need a second store
    /// load (the second load races against `aida db sync --pull` /
    /// concurrent edits and can return a different requirements set
    /// from a sibling worktree's perspective).
    entries: Vec<QueueWorkEntry>,
    /// Resolved scope string for `--owns` (e.g. "EPIC-20", "PR-11",
    /// "BUG-82"). Always non-empty.
    scope: String,
    /// Forge + PR number when scope is a PR-N / MR-N. Lets the caller
    /// route to the review session flow without re-parsing.
    review_target: Option<(ReviewForge, u64)>,
    /// Display SPEC-ID of the "anchor" requirement (the first entry
    /// for head/item modes; the parent for cluster mode). Surfaced in
    /// human output so the user can confirm we resolved the right thing.
    anchor_display: String,
    /// Title of the anchor requirement (e.g., "Review PR-11: …" or the
    /// real spec title). Used to detect Review-PR shape for skill
    /// routing without re-querying.
    anchor_title: String,
}

/// STORY-42: per-entry resolved view used by manifest writing and role
/// tally. trace:STORY-42 | ai:claude
#[derive(Debug, Clone)]
struct QueueWorkEntry {
    /// The underlying queue entry (carries position, for_role,
    /// for_scope so the role tally and ordering work).
    queue: aida_core::QueueEntry,
    /// Display SPEC-ID for the manifest (agreed_id → spec_id → "?").
    spec_id: String,
    /// Status at plan time, formatted as the manifest field expects
    /// ("Approved", "In Progress", …).
    status_at_plan: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum QueueWorkMode {
    Head,
    Item,
    Cluster,
}

/// STORY-42: resolve the user's queue-work argument into a concrete plan.
///
///   - `arg = None`            → head-pickup mode: top item from the
///     active role's queue (with the same
///     role + scope filters `queue next` uses).
///   - `arg` matches a queued  → item-pickup mode: just that entry.
///     entry's spec_id/agreed_id/uuid
///   - `arg` resolves to a req → cluster-pickup mode: every queued entry
///     that isn't queued but   whose for_scope == <id> OR whose req's
///     has queued children    derived parent EPIC == <id>.
///
/// `type_filter` only applies in cluster mode (filters drained children
/// by req type, case-insensitive). trace:STORY-42 | ai:claude
/// TASK-560: `--auto-complete` and `--resume` are mutually exclusive
/// (auto-complete drives a FRESH implementer→CI→reviewer→merge pipeline;
/// --resume continues an EXISTING session — the two can't both own the run).
/// Returns the helpful rejection message when both are set, else `None`.
/// Pure so the message (the WHY + both recovery paths) is unit-testable
/// without running the launcher. trace:TASK-560 | ai:claude
fn resume_autocomplete_conflict_message(resume: bool, auto_complete: bool) -> Option<String> {
    if resume && auto_complete {
        Some(
            "--auto-complete cannot be used with --resume.\n\
             auto-complete drives a FRESH implementer→CI→reviewer→merge→pull→build \
             pipeline; --resume continues an EXISTING session — the two can't both \
             own the run.\n\n  \
             To continue the existing session:    re-run with --resume alone.\n  \
             To start a fresh orchestrator drain:  end the existing session first \
             (`aida session end <id>`), then re-run with --auto-complete."
                .to_string(),
        )
    } else {
        None
    }
}

fn resolve_queue_work_plan(
    storage: &Storage,
    user_id: &str,
    arg: Option<&str>,
    type_filter: Option<&str>,
    strict: bool,
    // TASK-1053: under a dry-run, the convenience auto-queue of an explicit
    // Approved-but-unqueued spec must NOT persist — we synthesize the queue
    // entry in-memory so the plan resolves identically to a real pickup while
    // mutating nothing. trace:TASK-1053 | ai:claude
    dry_run: bool,
) -> Result<QueueWorkPlan> {
    let mut entries = storage.queue_list(user_id, /* include_completed */ false)?;
    let store = storage.load()?;

    if let Some(arg_str) = arg {
        if let Some(req) = store.requirements.iter().find(|r| spec_matches(r, arg_str)) {
            let is_queued = entries.iter().any(|e| e.requirement_id == req.id);
            if !is_queued && req.status == RequirementStatus::Approved && !strict {
                let role = std::env::var("AIDA_SESSION_ROLE")
                    .unwrap_or_else(|_| "implementer".to_string());
                let entry = aida_core::QueueEntry {
                    user_id: user_id.to_string(),
                    requirement_id: req.id,
                    position: i64::MAX,
                    added_by: user_id.to_string(),
                    note: None,
                    added_at: chrono::Utc::now(),
                    for_role: Some(role.clone()),
                    for_scope: None,
                    for_session: None,
                    added_by_machine: None,
                };
                if dry_run {
                    // TASK-1053: preview only — push the synthesized entry so the
                    // Item-pickup match below resolves the same plan a real pickup
                    // would, but persist nothing (no queue_add, no role-activity,
                    // no "queued …" line). trace:TASK-1053 | ai:claude
                    entries.push(entry);
                } else {
                    storage.queue_add(entry)?;
                    let display_id = req
                        .agreed_id
                        .as_deref()
                        .or(req.spec_id.as_deref())
                        .unwrap_or(arg_str);
                    record_role_activity(display_id, "queue-add");
                    println!("queued {} for role:{}", display_id, role);
                    // Reload entries to include the auto-queued entry.
                    // trace:TASK-547 | ai:antigravity
                    entries = storage.queue_list(user_id, /* include_completed */ false)?;
                }
            }
        }
    }

    // Head-pickup: pick the top item for the active role, honoring the
    // same filters as `queue next` (role routing + active-role scope +
    // terminal-status skip). We don't re-implement that whole filter
    // chain here; queue work is best-effort and the user can pass an
    // explicit id when the head heuristic picks the wrong thing.
    if arg.is_none() {
        let role_filter: Option<String> = std::env::var("AIDA_SESSION_ROLE")
            .ok()
            .filter(|s| !s.is_empty());
        // STORY-333: collect un-pickable specs (blocked-by / human-only)
        // skipped during head resolution so the kickoff banner can name
        // them. Silent skipping looks like "queue is empty" — we surface
        // the reason instead. trace:STORY-333 | ai:claude
        let mut skipped_unpickable: Vec<(String, String)> = Vec::new();
        let head = entries
            .iter()
            .filter(|e| match &role_filter {
                Some(r) => e.for_role.as_deref() == Some(r.as_str()),
                None => true,
            })
            .filter(|e| {
                let Some(req) = store.requirements.iter().find(|r| r.id == e.requirement_id) else {
                    return true;
                };
                !is_terminal_status(&req.status)
            })
            .filter(|e| {
                // STORY-333: pre-pickup gate. Skip un-pickable specs so the
                // orchestrator never spawns a doomed phase-1 implementer on
                // them. Reasons are recorded for the banner.
                let Some(req) = store.requirements.iter().find(|r| r.id == e.requirement_id) else {
                    return true;
                };
                match aida_core::pickability::pickability(req, &store) {
                    aida_core::pickability::Pickability::Pickable => true,
                    aida_core::pickability::Pickability::Blocked(reason) => {
                        let display = req
                            .agreed_id
                            .clone()
                            .or_else(|| req.spec_id.clone())
                            .unwrap_or_else(|| "?".to_string());
                        skipped_unpickable.push((
                            display,
                            aida_core::pickability::pickability_reason_label(&reason),
                        ));
                        false
                    }
                }
            })
            .min_by_key(|e| e.position)
            .cloned()
            .ok_or_else(|| {
                let suffix = if skipped_unpickable.is_empty() {
                    String::new()
                } else {
                    let listed = skipped_unpickable
                        .iter()
                        .map(|(s, r)| format!("{} ({})", s, r))
                        .collect::<Vec<_>>()
                        .join(", ");
                    format!(
                        "\n  Skipped {} un-pickable spec(s): {}\n  \
                         (Run `aida queue list` to see the Blocked section.)",
                        skipped_unpickable.len(),
                        listed
                    )
                };
                // BUG-465: on a FRESH project (no real, non-META specs yet) the
                // queue is legitimately empty — guide the new user's first
                // action instead of dead-ending with a bare error. EPIC-37:
                // fresh init -> first `queue work` must be boring and correct.
                // trace:BUG-465 | ai:claude
                let has_real_specs = store
                    .requirements
                    .iter()
                    .any(|r| !matches!(r.req_type, aida_core::RequirementType::Meta));
                // STORY-737 (delight #5): an empty queue on day one is the
                // EXPECTED state, not a failure. On the HUMAN path, render a
                // soft, forward-pointing signpost (info glyph — NOT a red
                // `Error:`) and return the `SoftSignpostShown` sentinel so the
                // top-level handler suppresses the error render (exit still
                // non-zero so scripts keep gating). Agent mode keeps the
                // structured error it parses. trace:STORY-737 | ai:claude
                if !agent_output_mode() {
                    if !has_real_specs && skipped_unpickable.is_empty() {
                        eprintln!(
                            "{} Your queue is empty — looks like a fresh project. Get started:\n  \
                             1. File a spec:  aida add --title \"<what you're building>\" --type task --status approved\n  \
                             2. Queue it:     aida queue add <SPEC-ID>   (the id printed by step 1)\n  \
                             3. Work it:      aida queue work\n  \
                             Browse anytime with `aida list`.",
                            crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan()
                        );
                    } else {
                        eprintln!(
                            "{} Nothing queued yet — that's the expected day-one state. \
                             Approve a draft and queue it in one step: \
                             `aida add \"<what you're building>\" --queue`, \
                             or queue an existing spec: `aida queue add <id>`.{}",
                            crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                            suffix
                        );
                    }
                    return anyhow::Error::new(SoftSignpostShown);
                }
                if !has_real_specs && skipped_unpickable.is_empty() {
                    anyhow::anyhow!(
                        "Your queue is empty — looks like a fresh project. Get started:\n  \
                         1. File a spec:  aida add --title \"<what you're building>\" --type task --status approved\n  \
                         2. Queue it:     aida queue add <SPEC-ID>   (the id printed by step 1)\n  \
                         3. Work it:      aida queue work\n  \
                         Browse anytime with `aida list`."
                    )
                } else {
                    anyhow::anyhow!(
                        "queue is empty for {}; pass an id explicitly or run `aida queue list`{}",
                        role_filter.as_deref().unwrap_or("any role"),
                        suffix
                    )
                }
            })?;
        if !skipped_unpickable.is_empty() {
            let listed = skipped_unpickable
                .iter()
                .map(|(s, r)| format!("{} ({})", s, r))
                .collect::<Vec<_>>()
                .join(", ");
            eprintln!(
                "  {} skipped {} un-pickable spec(s) ahead of head: {}",
                crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                skipped_unpickable.len(),
                listed
            );
        }
        let req = store
            .requirements
            .iter()
            .find(|r| r.id == head.requirement_id)
            .ok_or_else(|| anyhow::anyhow!("queue head's requirement is missing from the store"))?;
        let (scope, review_target) = derive_scope_from_entry(&head, req);
        let anchor_display = req
            .agreed_id
            .clone()
            .or_else(|| req.spec_id.clone())
            .unwrap_or_else(|| "?".to_string());
        let resolved = build_resolved_entry(head, req);
        return Ok(QueueWorkPlan {
            mode: QueueWorkMode::Head,
            entries: vec![resolved],
            scope,
            review_target,
            anchor_display,
            anchor_title: req.title.clone(),
        });
    }

    let arg = arg.unwrap();

    // Item-pickup: look for a queue entry whose req matches the arg by
    // uuid / spec_id / agreed_id (case-insensitive).
    let matched_item: Option<aida_core::QueueEntry> = entries
        .iter()
        .find(|e| {
            let Some(req) = store.requirements.iter().find(|r| r.id == e.requirement_id) else {
                return false;
            };
            spec_matches(req, arg)
        })
        .cloned();

    if let Some(entry) = matched_item {
        let req = store
            .requirements
            .iter()
            .find(|r| r.id == entry.requirement_id)
            .unwrap();
        let (scope, review_target) = derive_scope_from_entry(&entry, req);
        let anchor_display = req
            .agreed_id
            .clone()
            .or_else(|| req.spec_id.clone())
            .unwrap_or_else(|| arg.to_string());
        let resolved = build_resolved_entry(entry, req);
        return Ok(QueueWorkPlan {
            mode: QueueWorkMode::Item,
            entries: vec![resolved],
            scope,
            review_target,
            anchor_display,
            anchor_title: req.title.clone(),
        });
    }

    // TASK-85: PR-N / MR-N pickup by review-story title. The auto-queued
    // review stories live in the queue with titles like "Review PR-14:
    // ...", but their spec_id (e.g., STORY-103) isn't memorable. Let
    // `aida queue work PR-14` find the corresponding queue entry by
    // title prefix so the user doesn't have to look up the story id.
    // Composes with STORY-66/STORY-90 (auto-queue at PR-create) which
    // produce these stories. trace:TASK-85 | ai:claude
    if let Some((forge, n)) = parse_review_scope(arg) {
        let matches: Vec<aida_core::QueueEntry> = entries
            .iter()
            .filter(|e| {
                let Some(req) = store.requirements.iter().find(|r| r.id == e.requirement_id) else {
                    return false;
                };
                if is_terminal_status(&req.status) {
                    return false;
                }
                review_title_matches(&req.title, forge, n)
            })
            .cloned()
            .collect();
        match matches.len() {
            0 => {
                let label = format_review_label(forge, n);
                anyhow::bail!(
                    "no queued review story for {} — check `gh pr view {}` (or `glab mr view {}`) and run `aida pr auto-queue-review --branch <branch>` if needed",
                    label,
                    n,
                    n
                );
            }
            1 => {
                let entry = matches.into_iter().next().unwrap();
                let req = store
                    .requirements
                    .iter()
                    .find(|r| r.id == entry.requirement_id)
                    .unwrap();
                // PR review pickup: scope + review_target come straight from
                // the (forge, n) parse_review_scope just gave us. We don't
                // delegate to derive_scope_from_entry because its title-based
                // path is case-sensitive on `strip_prefix("Review ")` while
                // review_title_matches is case-insensitive — a lowercase
                // "review pr-14: …" title would pass the matcher but fall
                // through to the spec_id fallback, losing the PR scope and
                // the --pr N reviewer-skill route. trace:TASK-85 | ai:claude
                let scope = format_review_label(forge, n);
                let review_target = Some((forge, n));
                let anchor_display = req
                    .agreed_id
                    .clone()
                    .or_else(|| req.spec_id.clone())
                    .unwrap_or_else(|| arg.to_string());
                let resolved = build_resolved_entry(entry, req);
                return Ok(QueueWorkPlan {
                    mode: QueueWorkMode::Item,
                    entries: vec![resolved],
                    scope,
                    review_target,
                    anchor_display,
                    anchor_title: req.title.clone(),
                });
            }
            _ => {
                let label = format_review_label(forge, n);
                let mut msg = format!(
                    "{} matches {} queued review stories — pass the specific spec_id instead:",
                    label,
                    matches.len()
                );
                for e in &matches {
                    if let Some(req) = store.requirements.iter().find(|r| r.id == e.requirement_id)
                    {
                        let id = req
                            .agreed_id
                            .as_deref()
                            .or(req.spec_id.as_deref())
                            .unwrap_or("?");
                        msg.push_str(&format!("\n  · {} — {}", id, req.title));
                    }
                }
                anyhow::bail!(msg);
            }
        }
    }

    // Cluster-pickup: arg names a req that isn't queued itself but has
    // queued children. Find them via for_scope match OR derived parent
    // EPIC match. The arg must resolve to a req in the store.
    let anchor_req = store
        .requirements
        .iter()
        .find(|r| spec_matches(r, arg))
        .ok_or_else(|| {
            anyhow::anyhow!(
                "`{}` doesn't match any queued entry or known requirement",
                arg
            )
        })?;
    let anchor_id_upper = anchor_req
        .agreed_id
        .as_deref()
        .or(anchor_req.spec_id.as_deref())
        .map(|s| s.to_uppercase())
        .unwrap_or_default();
    let type_filter_lower = type_filter.map(|s| s.to_ascii_lowercase());

    let cluster: Vec<aida_core::QueueEntry> = entries
        .iter()
        .filter(|e| {
            let Some(req) = store.requirements.iter().find(|r| r.id == e.requirement_id) else {
                return false;
            };
            // Skip terminal-status reqs (they shouldn't ever be in the
            // queue but defensive).
            if is_terminal_status(&req.status) {
                return false;
            }
            // STORY-333: cluster drains must skip un-pickable members so
            // the orchestrator never spawns phase 1 on a blocked-by /
            // human-only spec. Same gate as head pickup + batch drain.
            // trace:STORY-333 | ai:claude
            match aida_core::pickability::pickability(req, &store) {
                aida_core::pickability::Pickability::Pickable => {}
                aida_core::pickability::Pickability::Blocked(reason) => {
                    eprintln!(
                        "  {} cluster {} — skipping un-pickable {} ({})",
                        crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                        anchor_id_upper,
                        req.display_id(),
                        aida_core::pickability::pickability_reason_label(&reason),
                    );
                    return false;
                }
            }
            // Match by explicit for_scope.
            let scope_match = e
                .for_scope
                .as_deref()
                .map(|s| s.eq_ignore_ascii_case(&anchor_id_upper))
                .unwrap_or(false);
            // Match by derived parent EPIC (when anchor is itself an
            // EPIC; otherwise the function returns None so this branch
            // is harmless).
            let parent_match = derive_parent_epic_label(req, &store)
                .map(|p| p.eq_ignore_ascii_case(&anchor_id_upper))
                .unwrap_or(false);
            if !(scope_match || parent_match) {
                return false;
            }
            // Type filter (cluster only).
            if let Some(want) = &type_filter_lower {
                let actual = format!("{:?}", req.req_type).to_ascii_lowercase();
                if actual != *want {
                    return false;
                }
            }
            true
        })
        .cloned()
        .collect();

    if cluster.is_empty() {
        // TASK-217: status-aware recovery hint. The user typed an id that
        // resolves to a known spec but isn't queued (and has no queued
        // children). Branch on the anchor's current status to suggest the
        // recovery the user most likely wants — re-queueing after a
        // Done→rework cycle, promoting Planned to Approved, etc. — instead
        // of the previous opaque "no queued children match" hint.
        // trace:TASK-217 | ai:claude
        let role = std::env::var("AIDA_SESSION_ROLE")
            .ok()
            .filter(|s| !s.is_empty());
        let display_id = anchor_req
            .agreed_id
            .as_deref()
            .or(anchor_req.spec_id.as_deref())
            .unwrap_or(&anchor_id_upper);
        anyhow::bail!(format_queue_work_not_queued_error(
            display_id,
            anchor_req,
            role.as_deref(),
        ));
    }

    // Sort cluster by queue position so the manifest reflects intent.
    let mut cluster_sorted = cluster;
    cluster_sorted.sort_by_key(|e| e.position);

    // Pre-resolve each entry's display id + status so manifest writing
    // doesn't need a second store load.
    let resolved_entries: Vec<QueueWorkEntry> = cluster_sorted
        .into_iter()
        .filter_map(|entry| {
            let req = store
                .requirements
                .iter()
                .find(|r| r.id == entry.requirement_id)?;
            Some(build_resolved_entry(entry, req))
        })
        .collect();

    let scope = anchor_id_upper.clone();
    let review_target = parse_review_scope(&scope);
    Ok(QueueWorkPlan {
        mode: QueueWorkMode::Cluster,
        entries: resolved_entries,
        scope,
        review_target,
        anchor_display: anchor_id_upper,
        anchor_title: anchor_req.title.clone(),
    })
}

/// STORY-42: zip a queue entry with its current requirement state so
/// later steps (role tally, manifest write) don't need to re-look-up
/// against a potentially-different Storage handle.
/// trace:STORY-42 | ai:claude
fn build_resolved_entry(
    queue: aida_core::QueueEntry,
    req: &aida_core::Requirement,
) -> QueueWorkEntry {
    let spec_id = req
        .agreed_id
        .clone()
        .or_else(|| req.spec_id.clone())
        .unwrap_or_else(|| "?".to_string());
    let status_at_plan = format!("{}", req.status);
    QueueWorkEntry {
        queue,
        spec_id,
        status_at_plan,
    }
}

/// TASK-217: build a status-aware recovery hint when `aida queue work <id>`
/// resolves a spec but finds no queue entry. The current status of the
/// resolved spec tells us which recovery path the user most likely wants.
/// trace:TASK-217 | ai:claude
fn format_queue_work_not_queued_error(
    display_id: &str,
    anchor_req: &aida_core::Requirement,
    role: Option<&str>,
) -> String {
    use RequirementType::*;
    let role_display = role.unwrap_or("<role>");
    let is_container = matches!(anchor_req.req_type, Epic | Folder | Sprint);
    if is_container {
        return format!(
            "`{display_id}` has no queued children. (Status: {status})\n  \
             Inspect the cluster: `aida queue list --tree` or `aida list --parent {display_id}`\n  \
             To queue more work under {display_id}: `aida queue add <child-id> --for {role_display}`",
            status = anchor_req.status,
        );
    }
    match anchor_req.status {
        RequirementStatus::Draft | RequirementStatus::Approved => format!(
            "`{display_id}` isn't queued. Status is {status}.\n  \
             To queue and start: `aida queue add {display_id} --for {role_display}` then `aida queue work {display_id}`",
            status = anchor_req.status,
        ),
        RequirementStatus::Planned => format!(
            "`{display_id}` isn't queued. Status is Planned (still in planning).\n  \
             To work it: `aida edit {display_id} --status approved` then `aida queue add {display_id} --for {role_display}`"
        ),
        RequirementStatus::InProgress => format!(
            "`{display_id}` isn't queued, but status is In Progress.\n  \
             The lease may have been lost. Inspect with `aida queue list --all`.\n  \
             To re-queue: `aida queue add {display_id} --for {role_display}`"
        ),
        // The suggested command must run verbatim for *any* Done spec —
        // including one with no recorded claude session — so it stays
        // `--work` (a fresh session), not `--work --resume` (which needs a
        // prior session and bounces when there isn't one). trace:BUG-236
        // TASK-240: a Done spec usually means "PR open, awaiting merge". If the
        // user authored that PR they may want to merge it NOW rather than wait —
        // point them at the merge path. We can't name the PR number here (no gh
        // lookup in this pure builder), so route via `aida show` which prints the
        // PR linkage, keeping every suggested command honest/runnable.
        // No --delete-branch in the merge suggestion — a worktree may still
        // hold the branch — and `;` so the auto-bump pull cannot be dropped.
        // trace:TASK-240 trace:BUG-758 | ai:claude
        RequirementStatus::Done => format!(
            "`{display_id}` isn't queued. Status is Done (work finished on a branch).\n  \
             If review found issues and more commits are needed: `aida queue rework {display_id} --work`\n  \
             If the PR is yours and you want to merge now (CI green): find it with `aida show {display_id}`, then `gh pr merge <PR> --squash; aida pull`.\n  \
             Otherwise nothing to do — auto-bump fires when the PR merges."
        ),
        RequirementStatus::Completed => format!(
            "`{display_id}` is Completed (already shipped). Nothing to work on.\n  \
             To re-open: `aida edit {display_id} --status in-progress --force`"
        ),
        RequirementStatus::Rejected => format!(
            "`{display_id}` is Rejected. Pick a different spec, or re-open with `aida edit {display_id} --status approved --force`."
        ),
        // STORY-332: a punted spec is paused awaiting triage — it should be
        // resolved by a human/advisor, not silently re-queued.
        RequirementStatus::NeedsAttention => format!(
            "`{display_id}` is paused (Needs Attention) — an agent punted a design-fork it couldn't resolve.\n  \
             Review the reason with `aida show {display_id}`, then triage:\n  \
             resume with `aida edit {display_id} --status in-progress`, or drop it with `--status rejected`."
        ),
    }
}

/// TASK-630: the held-state re-entry decision, isolated so it is unit-testable
/// without a Storage handle, a worktree, or a launcher.
///
/// A deliberate *push-branch, hold-PR* finish (BUG-250) leaves the spec **Done**
/// + dequeued with a persisted hold marker at `.aida/pr-holds/<spec>.json`. The
///   plain `aida queue work <spec>` recovery hints (rework / wait-for-merge) don't
///   fit that state — the operator is neither reworking nor waiting for a merge;
///   they're re-entering the dormant implementer worktree to run the manual gate
///   and *then* open the deferred PR. `--resume` against such a spec should flow
///   through the verb's normal lease/pull/worktree bookkeeping instead of bailing.
///
/// The decision is deliberately narrow: re-entry is allowed **only** when the
/// operator explicitly asked to resume (`resume == true`), the spec is in the
/// Done state (the state a deliberate hold parks it in), AND a hold marker is
/// present. A queued / Completed / NeedsAttention spec, or a Done spec with no
/// hold marker, is left to the existing recovery hints — a held re-entry is a
/// distinct state, not a blanket "resume any Done spec". trace:TASK-630 | ai:claude
fn held_resume_reentry_allowed(
    resume: bool,
    status: &RequirementStatus,
    hold_marker_present: bool,
) -> bool {
    resume && hold_marker_present && *status == RequirementStatus::Done
}

/// TASK-630: build the Item-mode plan for a held-spec `--resume` re-entry.
///
/// A held spec is Done + dequeued, so there is no real `QueueEntry` to anchor
/// the plan on. We synthesise one (scoped to the spec's own id, matching the
/// implementer worktree the held session lives in) so the rest of
/// `handle_queue_work` — lease bookkeeping, worktree resolution, the
/// `QueueWorkLaunch::Resume` re-entry — runs unchanged. trace:TASK-630 | ai:claude
fn held_resume_plan(req: &aida_core::Requirement, user_id: &str) -> QueueWorkPlan {
    let synthetic = aida_core::QueueEntry {
        user_id: user_id.to_string(),
        requirement_id: req.id,
        position: 0,
        added_by: user_id.to_string(),
        note: None,
        added_at: chrono::Utc::now(),
        for_role: Some("implementer".to_string()),
        for_scope: None,
        for_session: None,
        added_by_machine: None,
    };
    let (scope, review_target) = derive_scope_from_entry(&synthetic, req);
    let anchor_display = req
        .agreed_id
        .clone()
        .or_else(|| req.spec_id.clone())
        .unwrap_or_else(|| scope.clone());
    let resolved = build_resolved_entry(synthetic, req);
    QueueWorkPlan {
        mode: QueueWorkMode::Item,
        entries: vec![resolved],
        scope,
        review_target,
        anchor_display,
        anchor_title: req.title.clone(),
    }
}

/// STORY-42: case-insensitive match against a requirement's uuid,
/// spec_id, or agreed_id. trace:STORY-42 | ai:claude
fn spec_matches(req: &aida_core::Requirement, query: &str) -> bool {
    if let Ok(uuid) = uuid::Uuid::parse_str(query) {
        return req.id == uuid;
    }
    let q = query.to_ascii_uppercase();
    if let Some(s) = &req.spec_id {
        if s.to_ascii_uppercase() == q {
            return true;
        }
    }
    if let Some(a) = &req.agreed_id {
        if a.to_ascii_uppercase() == q {
            return true;
        }
    }
    false
}

/// STORY-42: pick the scope string for a single queued entry.
/// Preference order:
///   1. PR-N / MR-N parsed from "Review PR-N: …" title → "PR-N"
///   2. entry.for_scope (explicit STORY-57 tag)
///   3. fall back to the req's own display id
///      Also returns the parsed review target (if any) so the caller can
///      thread it into session_start without re-parsing.
///      trace:STORY-42 | ai:claude
// BUG-431 #1: a child story no longer inherits its parent epic's scope (the
// removed step 3). Session scope is derived purely from the entry's
// `for_scope`, the review-title shape, and the req's own id — so same-epic
// siblings drained together each get an independent scope / worktree / branch
// instead of contending for one epic scope. The store param is gone with the
// parent lookup. trace:BUG-431
fn derive_scope_from_entry(
    entry: &aida_core::QueueEntry,
    req: &aida_core::Requirement,
) -> (String, Option<(ReviewForge, u64)>) {
    // Review-PR shape — title carries the PR ref; e.g. "Review PR-11: …".
    if let Some(rest) = req.title.strip_prefix("Review ") {
        let pr_token = rest.split([':', ' ']).next().unwrap_or("");
        if let Some(target) = parse_review_scope(pr_token) {
            return (pr_token.to_uppercase(), Some(target));
        }
    }
    if let Some(s) = &entry.for_scope {
        // BUG-739: `harness-worktree` is a generic Claude harness lease, not a
        // work scope. Older queue entries may have been auto-stamped with it;
        // ignore that legacy value so `queue work` falls back to the spec id
        // instead of trying to start inside the shared harness checkout.
        // trace:BUG-739 | ai:codex
        if s.eq_ignore_ascii_case(worktree_lease::HARNESS_WORKTREE_SCOPE) {
            return derive_scope_from_req_id(req);
        }
        let target = parse_review_scope(s);
        return (s.to_uppercase(), target);
    }
    derive_scope_from_req_id(req)
}

fn derive_scope_from_req_id(req: &aida_core::Requirement) -> (String, Option<(ReviewForge, u64)>) {
    // BUG-431 #1: a child story's session scopes to the STORY'S OWN id, not
    // its parent epic. Previously this fell back to `derive_parent_epic_label`,
    // so every same-epic story under one drain (`aida queue work next N`) tried
    // to own the SAME epic scope — the worktree (`proj-epic-11`) and branch
    // (`epic-11`) collided, the first story's lease blocked all siblings at
    // phase 1 ("scope EPIC-11 is owned by lease …"), and the epic-leading PR
    // title backed two specs (epic + child), breaking the headless reviewer.
    // Scoping to the story gives each sibling its own scope / worktree / branch
    // so they drain without contention. An operator who genuinely wants an
    // epic-wide session still gets it via an explicit `for_scope` (above) or
    // `aida queue work EPIC-N`. The parent-epic label is still used for
    // *display* clustering elsewhere (planned-cluster manifest, queue
    // grouping) — that is separate from the lease scope and unaffected.
    // trace:BUG-431 | ai:claude
    let fallback = req
        .agreed_id
        .clone()
        .or_else(|| req.spec_id.clone())
        .unwrap_or_else(|| "scope".to_string());
    let target = parse_review_scope(&fallback);
    (fallback, target)
}

fn queue_add_for_scope_routing(
    no_scope: bool,
    explicit_scope: Option<&str>,
    for_session: Option<&str>,
    active_lease: Option<&SessionLease>,
) -> Option<String> {
    if no_scope {
        None
    } else if let Some(s) = explicit_scope {
        Some(s.to_string())
    } else if for_session.is_some() {
        // --for-session is the more specific axis; don't also auto-add a scope
        // filter unless the user asked for it.
        None
    } else {
        // BUG-739: the generic harness-worktree lease only means "this shell is
        // in a shared Claude harness checkout"; it must not become queue
        // routing state. Explicit `--scope harness-worktree` remains honored by
        // the explicit_scope branch above.
        // trace:BUG-739 | ai:codex
        active_lease
            .filter(|l| {
                !l.scope
                    .eq_ignore_ascii_case(worktree_lease::HARNESS_WORKTREE_SCOPE)
            })
            .map(|l| l.scope.clone())
    }
}

/// STORY-42: pick the role for a resolved queue-work plan.
/// trace:STORY-42 | ai:claude
fn infer_queue_work_role(
    plan: &QueueWorkPlan,
    override_role: Option<&str>,
) -> (String, &'static str, Option<Vec<String>>) {
    if let Some(r) = override_role {
        return (r.to_string(), "--role flag", None);
    }
    // Tally for_role across entries. None counts as "unrouted".
    let mut tally: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for e in &plan.entries {
        if let Some(r) = &e.queue.for_role {
            *tally.entry(r.to_ascii_lowercase()).or_default() += 1;
        }
    }
    let total_routed: usize = tally.values().sum();
    let mut warnings: Vec<String> = Vec::new();
    let chosen = if let Some((best, count)) = tally
        .iter()
        .max_by_key(|(_, c)| **c)
        .map(|(k, c)| (k.clone(), *c))
    {
        if count < total_routed {
            warnings.push(format!(
                "cluster has {} item{} routed to other role(s); using majority `{}` ({}/{})",
                total_routed - count,
                if total_routed - count == 1 { "" } else { "s" },
                best,
                count,
                total_routed
            ));
        }
        (best, "cluster-derived")
    } else {
        // No entry has for_role set — fall through to scope default
        // (PR-N → reviewer; else implementer) then env.
        let scope_default = if plan.review_target.is_some() {
            "reviewer"
        } else {
            "implementer"
        };
        let env_role = std::env::var("AIDA_SESSION_ROLE")
            .ok()
            .filter(|s| !s.is_empty());
        match env_role {
            Some(r) if !r.eq_ignore_ascii_case(scope_default) => {
                warnings.push(format!(
                    "no for_role on queued items; scope default `{}` overrides shell role `{}` (pass --role {} to keep shell role)",
                    scope_default, r, r
                ));
                (scope_default.to_string(), "scope-default")
            }
            _ => (scope_default.to_string(), "scope-default"),
        }
    };
    let warns = if warnings.is_empty() {
        None
    } else {
        Some(warnings)
    };
    (chosen.0, chosen.1, warns)
}

/// STORY-42: build the initial-prompt string fed to `claude <prompt>`.
/// Routes by role:
///   - reviewer → `/aida-review --pr N` (when scope parses as PR-N/MR-N)
///     else `/aida-review`
///   - implementer / other → `/aida-pickup [<ITEM-ID> | --auto-first]`
///     Both forms skip the skill's Step 2 confirm — the
///     argument IS the consent signal. Item mode focuses a
///     single id (the operator typed it, so the SPEC-ID is
///     the commitment — TASK-548 generalised TASK-86's
///     argument-as-consent rule to cover this case).
///     Cluster / head mode passes `--auto-first` to ride the
///     queue-work pre-flight summary as its consent point.
///     Only a bare `/aida-pickup` from the conversation (no
///     argument) still pauses to confirm.
///     trace:TASK-86 trace:TASK-548 | ai:claude
///     trace:STORY-42 | ai:claude
fn derive_queue_work_prompt(
    plan: &QueueWorkPlan,
    role: &str,
    plan_only: bool,
    guided: bool,
) -> String {
    let role_lower = role.to_ascii_lowercase();
    if role_lower == "reviewer" {
        if let Some((_, n)) = plan.review_target {
            return format!("/aida-review --pr {}", n);
        }
        return "/aida-review".to_string();
    }
    // STORY-735: guided keystone mode runs the structured decision-dialog
    // skill instead of pickup. It is interactive-only and conflicts with the
    // autonomous drain at the CLI; the spec id is the anchor it dialogs over.
    // trace:STORY-735 | ai:claude
    if guided {
        return format!("/aida-guided-implement {}", plan.anchor_display);
    }
    // STORY-265: plan-only mode runs the planning skill instead of pickup —
    // produce a docs/plans/ file, no code. (Reviewer handled above; plan-only
    // is an implementer-side mode.)
    if plan_only {
        if plan.mode == QueueWorkMode::Item {
            return format!("/aida-plan {}", plan.anchor_display);
        }
        return "/aida-plan".to_string();
    }
    // Implementer (and unknown roles): /aida-pickup with optional focus.
    if plan.mode == QueueWorkMode::Item {
        return format!("/aida-pickup {}", plan.anchor_display);
    }
    // Cluster / Head: drain-intent already confirmed by the queue work
    // pre-flight; pass --auto-first so the skill skips its own confirm.
    "/aida-pickup --auto-first".to_string()
}

/// BUG-225: render the copy-pasteable `claude` command line for a
/// headless launch deferred by `--no-launch`. Built from
/// `session::claude_headless_args` — the exact argv `exec_claude_headless`
/// feeds to `claude` — so the printed hint can never drift from the real
/// launch (correct flag order, `--session-id` included, prompt last).
/// STORY-278: prefix `AIDA_HEADLESS=1` so the copy-paste hint also sets
/// the env var `exec_claude_headless` puts on the child via `.env(...)`.
/// trace:BUG-225 | ai:claude
fn headless_launch_hint(prompt: &str, session_id: &str, contained: bool) -> String {
    let argv = session::claude_headless_args_with_posture(prompt, session_id, contained);
    format!("AIDA_HEADLESS=1 claude {}", shell_join_display(&argv))
}

fn claude_posture_display(permission_mode: Option<&str>, contained: bool) -> String {
    if contained {
        "contained sandbox".to_string()
    } else {
        permission_mode
            .map(|m| format!("permission-mode {}", m))
            .unwrap_or_else(|| "native permission posture".to_string())
    }
}

/// STORY-42: the orchestrator. Resolves the plan, optionally pulls,
/// runs session_start in non-launch mode (so we can write the manifest
/// from the freshly minted lease), then either prints next-steps or
/// chdirs + execs claude with the skill prompt.
/// trace:STORY-42 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_queue_work(
    storage: &Storage,
    user_id: &str,
    arg: Option<&str>,
    permission_mode: Option<&str>,
    sandbox: bool,
    no_launch: bool,
    role_override: Option<&str>,
    no_pull: bool,
    type_filter: Option<&str>,
    branch_override: Option<&str>,
    path_override: Option<&str>,
    // STORY-248: stacked-branch base resolution. `stack` auto-detects the
    // freshest un-merged in-flight implementer lease; `base` takes an
    // explicit branch name. CLI clap-level enforces they're mutually
    // exclusive. `force_base` opts out of the merged-base safety check.
    // trace:STORY-248 | ai:claude
    stack: bool,
    base: Option<&str>,
    force_base: bool,
    steal: bool,
    force_claim: bool,
    resume: Option<&str>,
    fresh: bool,
    list_sessions: bool,
    session_id: Option<&str>,
    // TASK-895: which vendor CLI hosts the interactive session — `claude`
    // (default) or `codex`. The AIDA TUI passes `codex` to host a Codex tab.
    // Only affects the interactive (non-headless) launch path; the headless
    // drain resolves its own vendor via STORY-683. trace:TASK-895 | ai:claude
    vendor: &str,
    no_human: bool,
    // TASK-1060 / ADR-10: the autonomy mode, resolved ONCE at dispatch and
    // threaded in as a typed value so in-process logic (the pre-flight banner)
    // never re-reads the bare `AIDA_ZEN` env var. trace:TASK-1060 | ai:claude
    autonomy: AutonomyMode,
    // TASK-272: the batch this pickup belongs to, when resolved from
    // `aida queue work --batch NAME`. Recorded on the session manifest so
    // /aida-pickup can detect batch context. `None` for a plain pickup.
    batch_name: Option<&str>,
    // BUG-226: suppress the end-of-command summary for a standalone
    // reviewer run (`--quiet`). Ignored for non-reviewer / orchestrator
    // launches, which never print one.
    quiet: bool,
    // STORY-281: opt out of the reviewer pre-flight stale-base refusal.
    // Only meaningful when scope resolves to a PR + role is reviewer;
    // ignored on every other pickup. trace:STORY-281 | ai:claude
    allow_stale_base: bool,
    // TASK-480: opt out of the reviewer pre-flight intermediate-only
    // refusal. Same scoping as allow_stale_base — only meaningful for a
    // reviewer pickup of a GitHub PR. trace:TASK-480 | ai:claude
    allow_intermediate_only: bool,
    // STORY-439: pickup-time complexity + assistance estimate. Each
    // value writes a slot to `.aida/complexity-calibration/<SPEC>.yaml`
    // AND stamps a `complexity:<level>` / `estimated-assistance:<level>`
    // tag on the spec for tag-based queries. trace:STORY-439 | ai:claude
    complexity: Option<complexity_calibration::ComplexityLevel>,
    assist_est: Option<complexity_calibration::AssistanceLevel>,
    // STORY-451: post-plan/pickup effort estimate. Captured as the plan
    // touchpoint and stamped as `effort:plan:<bucket>`.
    effort: Option<effort_calibration::EffortBucket>,
    // trace:TASK-547 | ai:antigravity
    strict: bool,
    // STORY-265: plan-only mode — run /aida-plan (not /aida-pickup) in `plan`
    // permission mode so the session writes a docs/plans/ file without
    // touching code; promote Approved -> Planned afterward via
    // `aida plan promote`. trace:STORY-265 | ai:claude
    plan_only: bool,
    // STORY-735: guided keystone-implementation mode — launch
    // /aida-guided-implement (a structured decision dialog) instead of
    // /aida-pickup. Interactive-only; the spec's major architectural forks
    // are decided up front and recorded as ADRs before any code.
    // trace:STORY-735 | ai:claude
    guided: bool,
    // TASK-1053: single-spec preview. Resolve the full plan (scope, role,
    // skill, branch, worktree path, session id, lease) and print it, then
    // return WITHOUT creating a worktree, taking a lease, or launching a
    // session. The `--batch` form is handled at the dispatch site (it
    // returns there before reaching this function). trace:TASK-1053 | ai:claude
    dry_run: bool,
) -> Result<()> {
    // STORY-132: validate a caller-minted --session-id up front — before
    // any side effect — so a malformed id fails clean with a clear
    // message rather than surfacing deep in session setup.
    if let Some(sid) = session_id {
        uuid::Uuid::parse_str(sid)
            .with_context(|| format!("--session-id `{}` is not a valid UUID", sid))?;
    }
    // TASK-630: a deliberate PR-hold (BUG-250) parks the spec Done + dequeued
    // with a persisted marker at `.aida/pr-holds/<spec>.json`. Normal queue
    // resolution then bails ("isn't queued. Status is Done") — wrong for a
    // re-entry. When the operator explicitly `--resume`s such a spec, recognise
    // the hold as a re-enterable state and synthesise an Item-mode plan so the
    // rest of the verb (lease/pull/worktree + QueueWorkLaunch::Resume) runs
    // unchanged. We try the normal resolution first; only on its failure do we
    // consult the marker, so a still-queued or non-held spec keeps its existing
    // behaviour exactly. trace:TASK-630 | ai:claude
    let plan = match resolve_queue_work_plan(storage, user_id, arg, type_filter, strict, dry_run) {
        Ok(plan) => plan,
        Err(e) => match arg.filter(|_| resume.is_some()) {
            Some(arg_str) => {
                let store = storage.load()?;
                let held = store
                    .requirements
                    .iter()
                    .find(|r| spec_matches(r, arg_str))
                    .and_then(|req| {
                        let main_root = find_main_worktree_root().ok()?;
                        let display = req
                            .agreed_id
                            .as_deref()
                            .or(req.spec_id.as_deref())
                            .unwrap_or(arg_str);
                        let marker = punt::hold_signal_path(&main_root, display);
                        let present = punt::read_hold_signal(&marker).is_some();
                        held_resume_reentry_allowed(true, &req.status, present)
                            .then(|| held_resume_plan(req, user_id))
                    });
                match held {
                    Some(plan) => plan,
                    None => return Err(e),
                }
            }
            None => return Err(e),
        },
    };

    // TASK-304: on a no-arg head pickup, surface the ultraplan suggestion
    // for a chunky head spec under `[ultraplan] mode = "suggested"`. Only
    // the no-arg form (the operator hasn't already chosen a spec) gets the
    // nudge; an explicit `aida queue work SPEC` is already a deliberate
    // choice. Best-effort and read-only — never perturbs the pickup.
    // trace:TASK-304 | ai:claude
    if arg.is_none() && !list_sessions {
        if let Ok(root) = find_project_root() {
            if let Ok(store) = storage.load() {
                if let Some(req) = store.get_requirement_by_spec_id(&plan.anchor_display) {
                    print_ultraplan_suggestion_hint(&root, req);
                }
            }
        }
    }

    // TASK-516: warn before picking up a spec whose imported plan is still
    // awaiting master review (tagged `plan-review:pending`). The plan is
    // archived but NOT yet canonical — the master hasn't signed off, so
    // riding it into the implementer session as the brief would treat an
    // unreviewed plan as load-bearing. Best-effort, read-only; never blocks
    // the pickup (this minimal slice warns, it doesn't gate).
    // trace:TASK-516 | ai:claude
    if !list_sessions {
        if let Ok(store) = storage.load() {
            if let Some(req) = store.get_requirement_by_spec_id(&plan.anchor_display) {
                if let Some(msg) = plan_review_warning(&req.tags, &plan.anchor_display) {
                    eprintln!("{msg}");
                }
            }
        }
    }

    // STORY-439: capture pickup-time complexity + assistance estimate
    // ASAP after plan resolution — we know the anchor spec, the project
    // root is reachable via `find_project_root`, and the capture is a
    // local FS write that won't perturb the rest of the pickup flow.
    // Best-effort: a write error logs and continues. Cluster mode uses
    // the anchor (the parent scope) as the captured spec; the
    // operator's estimate is for the cluster as a whole.
    // trace:STORY-439 | ai:claude
    if (complexity.is_some() || assist_est.is_some()) && !list_sessions && !dry_run {
        if let Ok(project_root) = find_project_root() {
            let main_root = main_worktree_root_from(&project_root);
            let spec = plan.anchor_display.as_str();
            if let Err(e) =
                complexity_calibration::upsert_pickup(&main_root, spec, complexity, assist_est)
            {
                eprintln!(
                    "  {} could not record pickup calibration for {spec}: {e}",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                );
            }
            // Stamp the tags on the spec so existing tag tooling works
            // on the new dimension. Best-effort — a load/save failure
            // doesn't fail the pickup.
            apply_calibration_tags(storage, spec, complexity, assist_est);
        }
    }
    if effort.is_some() && !list_sessions && !dry_run {
        if let Ok(project_root) = find_project_root() {
            let main_root = main_worktree_root_from(&project_root);
            let spec = plan.anchor_display.as_str();
            if let Err(e) = effort_calibration::upsert_plan(
                &main_root,
                spec,
                effort,
                Some(current_user_id(None)),
            ) {
                eprintln!(
                    "  {} could not record plan effort for {spec}: {e}",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                );
            }
            apply_effort_tag(
                storage,
                spec,
                effort_calibration::EffortTouchpoint::Plan,
                effort,
            );
        }
    }

    // TASK-112: `--list-sessions` is a pure read — print the recorded
    // claude conversations for this scope and exit before any side
    // effects (no worktree, no lease, no pull).
    if list_sessions {
        return print_scope_sessions(&plan.anchor_display);
    }

    // TASK-112: decide cold-launch-vs-resume up front, *before*
    // session_start mints a worktree — so a bad `--resume <id>` (or a
    // bare `--resume` with no prior session) fails clean with nothing to
    // unwind. `None` when `--no-launch` (setup-only, no conversation).
    let launch: Option<QueueWorkLaunch> = if no_launch {
        None
    } else {
        Some(resolve_queue_work_launch(
            &plan.anchor_display,
            resume,
            fresh,
            session_id,
        )?)
    };

    let (role, role_origin, warnings) = infer_queue_work_role(&plan, role_override);

    // Permission mode resolution (TASK-83 → TASK-84). Order:
    //   1. --permission-mode flag (explicit override always wins)
    //   2. AIDA_PERMISSION_MODE env var (process-level opt-out)
    //   3. .aida/config.toml [behavior] permission_mode (project policy)
    //   4. AIDA-managed worktree default → `bypassPermissions` (TASK-84:
    //      worktree is sandboxed git state; the prompt flood was eating
    //      autonomous overnight runs and circuit breakers stay in place)
    //   5. Non-AIDA default → `acceptEdits` (safe default for foreign cwd)
    // The pass-through to `claude --permission-mode` is unvalidated, so
    // users can pick `auto`, `plan`, etc. trace:STORY-42, TASK-83, TASK-84
    // | ai:claude
    let env_mode = std::env::var("AIDA_PERMISSION_MODE")
        .ok()
        .filter(|s| !s.is_empty());
    let project_root_for_config = find_main_worktree_root().ok();
    let config_mode = project_root_for_config
        .as_deref()
        .and_then(read_behavior_permission_mode);
    // STORY-495: the interactive worktree default is now faithful (native).
    // The uniform `[agents] bypass` knob is the single opt-in that restores
    // bypass posture — read it from user-base + project agents.toml.
    let bypass_knob = project_root_for_config
        .as_deref()
        .map(|r| load_agents_bypass(r).unwrap_or(false))
        .unwrap_or(false);
    let contained_knob = project_root_for_config
        .as_deref()
        .map(|r| load_agents_contained(r).unwrap_or(false))
        .unwrap_or(false);
    let contained_env = std::env::var("AIDA_CONTAINED")
        .ok()
        .is_some_and(|v| matches!(v.as_str(), "1" | "true" | "yes"));
    if sandbox && permission_mode.is_some() {
        anyhow::bail!(
            "--sandbox and --permission-mode are mutually exclusive Claude launch postures"
        );
    }
    let contained = !plan_only && (sandbox || contained_env || contained_knob);
    if contained && bypass_knob {
        anyhow::bail!("[agents] bypass and contained mode are mutually exclusive launch postures");
    }
    if contained {
        std::env::set_var("AIDA_CONTAINED", "1");
    }
    let (permission_mode, permission_mode_origin) = if contained {
        (Some("dontAsk".to_string()), "contained sandbox")
    } else {
        resolve_queue_work_permission_mode(
            permission_mode,
            env_mode.as_deref(),
            config_mode.as_deref(),
            bypass_knob,
            plan_only,
        )
    };
    if permission_mode.is_none() && !contained {
        maybe_show_faithful_launcher_notice();
    }

    let prompt = derive_queue_work_prompt(&plan, &role, plan_only, guided);

    // STORY-281: reviewer pre-flight stale-base check. Fires only when
    // the resolved scope is a GitHub PR AND the inferred role is the
    // reviewer — every other pickup (implementer, dialog, architect,
    // GitLab MR) skips this branch. The check is also no-op'd when the
    // pickup is `--no-launch` (no reviewer session about to run) and
    // when the user passed `--list-sessions` (already exited above).
    //
    // Behaviour mirrors the orchestrator's phase-3 pre-flight:
    //   Current        → silent proceed
    //   StaleNoOverlap → warning, proceed
    //   StaleOverlap   → refuse (anyhow::bail!) unless allow_stale_base
    //   Err (gh / fetch) → warning, proceed (never block on transient infra)
    //
    // trace:STORY-281 | ai:claude
    if !no_launch && role == "reviewer" {
        if let Some((ReviewForge::GitHub, pr_n)) = plan.review_target {
            if let Some(root) = project_root_for_config.as_deref() {
                match preflight_stale_base_check(root, pr_n) {
                    Ok(pr_rebase::StaleBaseOutcome::Current) => {}
                    Ok(pr_rebase::StaleBaseOutcome::StaleNoOverlap { behind }) => {
                        eprintln!(
                            "  {} {}",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                            pr_rebase::stale_base_warn_message(pr_n, behind).yellow()
                        );
                    }
                    Ok(pr_rebase::StaleBaseOutcome::StaleOverlap {
                        behind,
                        overlap_files,
                        ..
                    }) => {
                        let msg = pr_rebase::stale_base_block_message(pr_n, behind, &overlap_files);
                        if allow_stale_base {
                            eprintln!(
                                "  {} stale-base + overlap detected; \
                                 `--allow-stale-base` is set, proceeding.\n{}",
                                crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                                msg.yellow()
                            );
                        } else {
                            anyhow::bail!(msg);
                        }
                    }
                    Err(e) => {
                        eprintln!(
                            "  {} pre-flight stale-base check for PR-{pr_n} failed \
                             ({e}); proceeding with reviewer",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                        );
                    }
                }
            }
        }
    }

    // TASK-480: reviewer pre-flight intermediate-only check. Sibling
    // substrate-as-bouncer gate to the STORY-281 stale-base refusal
    // above — same scoping (reviewer + GitHub PR + launching). Refuses a
    // PR whose diff is exclusively intermediate/generated paths (build
    // outputs, gitignored files, lockfiles with no source change)
    // because such a fix is not reproducible. The check is a
    // PROGRAMMATIC GATE here, not skill-template instruction text
    // (BUG-280-class lesson). Fails open on infra error.
    //
    //   Clean                   → silent proceed
    //   SourcePlusIntermediate  → warning, proceed (flag-but-allow)
    //   IntermediateOnly        → refuse unless --allow-intermediate-only
    //
    // trace:TASK-480 | ai:claude
    if !no_launch && role == "reviewer" {
        if let Some((ReviewForge::GitHub, pr_n)) = plan.review_target {
            if let Some(root) = project_root_for_config.as_deref() {
                let allow = allow_intermediate_only
                    || std::env::var("AIDA_ALLOW_INTERMEDIATE_ONLY")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
                        .unwrap_or(false);
                match preflight_intermediate_only_check(root, pr_n) {
                    Ok(pr_rebase::IntermediateOnlyOutcome::Clean) => {}
                    Ok(pr_rebase::IntermediateOnlyOutcome::SourcePlusIntermediate {
                        intermediate,
                    }) => {
                        eprintln!(
                            "  {} {}",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                            pr_rebase::intermediate_only_warn_message(pr_n, &intermediate).yellow()
                        );
                    }
                    Ok(pr_rebase::IntermediateOnlyOutcome::IntermediateOnly { intermediate }) => {
                        let msg = pr_rebase::intermediate_only_block_message(pr_n, &intermediate);
                        if allow {
                            eprintln!(
                                "  {} intermediate-only diff detected; \
                                 `--allow-intermediate-only` is set, proceeding.\n{}",
                                crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                                msg.yellow()
                            );
                        } else {
                            anyhow::bail!(msg);
                        }
                    }
                    Err(e) => {
                        eprintln!(
                            "  {} pre-flight intermediate-only check for PR-{pr_n} failed \
                             ({e}); proceeding with reviewer",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                        );
                    }
                }
            }
        }
    }

    // Pre-flight summary so the user sees what we resolved before any
    // side effects fire (worktree create, lease, exec). Goes to stderr.
    eprintln!();
    eprintln!(
        "{} queue work {} mode",
        crate::glyph(crate::glyphs::Glyph::FlowActive)
            .green()
            .bold(),
        format!("({:?})", plan.mode).to_lowercase().cyan()
    );
    let line = |label: &str, value: String| {
        // Pad label to 8 chars so anchor/scope/role/mode/skill/cluster
        // line up vertically. The bold() call doesn't affect width as
        // seen by humans (terminal renders the same column).
        eprintln!("  {:<8} {}", format!("{}:", label).bold(), value);
    };
    line(
        "anchor",
        format!(
            "{}  {}",
            plan.anchor_display.cyan(),
            plan.anchor_title.dimmed()
        ),
    );
    line("scope", plan.scope.cyan().to_string());
    line(
        "role",
        format!("{} {}", role.cyan(), format!("({})", role_origin).dimmed()),
    );
    line(
        "mode",
        format!(
            "{} {}",
            permission_mode.as_deref().unwrap_or("native").cyan(),
            format!("({})", permission_mode_origin).dimmed()
        ),
    );
    line("skill", prompt.cyan().to_string());
    // STORY-287: surface the `--zen` autonomy mode in the pre-flight so the
    // user sees the flag took. ADR-10 / TASK-1060: consult the typed `autonomy`
    // value (resolved ONCE at dispatch and threaded in) instead of re-reading
    // the bare `AIDA_ZEN` env var — the env var stays as the cross-process
    // transport to phase children, not the in-process source of truth. This
    // also subsumes the old TASK-327 value-semantics guard (`AIDA_ZEN=0`/`false`
    // must not enable zen): `resolve_autonomy_mode` already handles it.
    // The full three-mode pre-launch banner is TASK-306's job.
    // trace:STORY-287 trace:ADR-10 trace:TASK-1060 | ai:claude
    if autonomy.is_zen() {
        // BUG-232: `--zen`'s end-of-session behavior differs by whether an
        // orchestrator is present to hand off to. With one, `--auto-complete`
        // drives PR → CI → review → merge; without one, `--zen` auto-opens
        // the PR at end-of-session then pauses on the grab-next/stop fork.
        // Corroborate via `orchestrator::detect` — BUG-233: never key off
        // the bare `AIDA_AUTO_COMPLETE` var, a stray value would lie here.
        // trace:BUG-232 | ai:claude
        let orch_root = project_root_for_config
            .clone()
            .or_else(|| std::env::current_dir().ok())
            .unwrap_or_else(|| std::path::PathBuf::from("."));
        let (mode, note) = if orchestrator::detect(&orch_root).is_orchestrated() {
            (
                "zen + auto-complete",
                "(orchestrator drives end-of-session: PR → CI → review → merge)",
            )
        } else {
            (
                "zen",
                "(no orchestrator — confirmations auto-resolve; at end-of-session the PR \
                 auto-opens, then grab-next/stop pauses)",
            )
        };
        line("autonomy", format!("{} {}", mode.cyan(), note.dimmed()));
    }
    // TASK-112: surface a resume in the pre-flight summary.
    if let Some(QueueWorkLaunch::Resume(id)) = &launch {
        line(
            "resume",
            format!(
                "{} {}",
                id[..id.len().min(8)].cyan(),
                "(continuing prior conversation)".dimmed()
            ),
        );
    }
    if plan.entries.len() > 1 {
        line(
            "cluster",
            format!(
                "{} item{}",
                plan.entries.len().to_string().cyan(),
                if plan.entries.len() == 1 { "" } else { "s" }
            ),
        );
    }
    if let Some(warns) = &warnings {
        for w in warns {
            eprintln!(
                "  {} {}",
                crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                w.yellow()
            );
        }
    }

    // BUG-233: if this session carries `AIDA_AUTO_COMPLETE` without a live
    // corroboration token, surface it once — informationally. It is NOT a
    // leak to hunt (BUG-233's corrected diagnosis): the session simply runs
    // interactive. A corroborated orchestrator child stays silent here.
    // trace:BUG-233 | ai:claude
    {
        let root_for_orch = project_root_for_config
            .clone()
            .or_else(|| std::env::current_dir().ok())
            .unwrap_or_else(|| std::path::PathBuf::from("."));
        if let Some(note) = orchestrator::detect(&root_for_orch).informational_note() {
            eprintln!(
                "  {} {}",
                crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                note.dimmed()
            );
        }
    }

    // TASK-1053: single-spec dry-run preview. The plan is now fully resolved —
    // the pre-flight summary above already printed anchor/scope/role/mode/skill;
    // here we add the branch, worktree path, session id, and the lease the
    // pickup WOULD create, then return. We sit BEFORE the first side effect
    // (the scope-conflict sweep, the pre-pickup pull, and session_start that
    // follow), so a dry run creates no worktree, takes no lease, writes no
    // manifest, and launches no claude. The branch + worktree derivation
    // mirror `session_start` exactly so the preview matches a real pickup.
    // The `--batch` dry-run is a separate path that returns at the dispatch
    // site before this function is even called. trace:TASK-1053 | ai:claude
    if dry_run {
        let dry_line = |label: &str, value: String| {
            eprintln!("  {:<8} {}", format!("{}:", label).bold(), value);
        };
        let project_root = find_main_worktree_root()?;
        let slug = slugify(&plan.scope);
        let branch = if let Some(b) = branch_override {
            b.to_string()
        } else if let Some((forge, n)) = plan.review_target {
            forge.local_branch_for(n)
        } else {
            // Best-effort: on the rare all-candidates-taken error, fall back to
            // the bare slug rather than failing a read-only preview.
            resolve_session_branch(&project_root, &slug, "auto").unwrap_or_else(|_| slug.clone())
        };
        let repo_name = project_root
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("project");
        let worktree_path = match path_override {
            Some(p) => std::path::PathBuf::from(p),
            None => project_root
                .parent()
                .map(|parent| parent.join(format!("{}-{}", repo_name, slug)))
                .unwrap_or_else(|| std::path::PathBuf::from(format!("{}-{}", repo_name, slug))),
        };
        let session_render = match &launch {
            Some(l) => format!(
                "{} {}",
                l.session_id().cyan(),
                "(claude session id it would launch / resume)".dimmed()
            ),
            None => "(deferred — --no-launch)".dimmed().to_string(),
        };
        dry_line("branch", branch.cyan().to_string());
        dry_line(
            "worktree",
            worktree_path.display().to_string().cyan().to_string(),
        );
        dry_line("session", session_render);
        dry_line(
            "lease",
            format!(
                "{} {}",
                "would be created".cyan(),
                format!("(owner {}, scope {}, role {})", user_id, plan.scope, role).dimmed()
            ),
        );
        eprintln!();
        eprintln!(
            "{} dry run — nothing created (no worktree, no lease, no session). \
             Re-run without --dry-run to pick up.",
            crate::glyph(crate::glyphs::Glyph::Check).green().bold()
        );
        return Ok(());
    }

    // TASK-81: scope-conflict pre-flight. If any active lease already
    // owns plan.scope, `session_start` would refuse with "scope X already
    // owned by session Y". Surface that here with a queue-work-flavored
    // message that names --steal as the override, and when --steal is
    // passed, end EACH holding session cleanly first so session_start
    // sees a free scope. Re-list + re-detect after every end so we drain
    // the rare-but-possible multi-lease-same-scope state (manual lease
    // restores, partial session_end crashes, concurrent writes) — the
    // helper itself returns only the freshest, but session_start's guard
    // bails on ANY same-scope lease, so we must sweep until clean.
    // Uncommitted-changes guards in session_end still apply — we don't
    // escalate to --force on the user's behalf because that would
    // silently discard their in-flight work; the message points at
    // `aida session end --force` for the user-driven path.
    //
    // BUG-307 extension: before refusing or applying --steal, check
    // whether the conflict lease is **dormant** (process dead, mtime
    // stale, no live claude in the worktree). If it is AND the worktree
    // is clean, auto-release it transparently — the dominant friction
    // class for unsupervised drains is stale-lease state from PREVIOUS
    // stalls, every recovered failure leaves a lease behind. If the
    // worktree carries uncommitted changes we still refuse, but with a
    // loss-risk-aware message instead of the generic "pass --steal".
    // trace:TASK-81 trace:BUG-307 | ai:claude
    {
        let project_root_for_conflict = find_main_worktree_root()?;
        let orch_config = orchestrator::OrchestratorConfig::load(&project_root_for_conflict);
        // Safety cap: in practice this resolves in 1 iteration for the
        // canonical case, 2-3 for the multi-lease state. A bound prevents
        // a hypothetical infinite loop if session_end ever returns Ok
        // without actually removing the lease (defense-in-depth).
        let mut remaining = 16usize;
        while let Some(conflict) =
            find_scope_lease_conflict(&list_leases(&project_root_for_conflict), &plan.scope)
        {
            // BUG-307: classify before deciding to refuse. The auto-release
            // path only fires when every liveness signal says the lease is
            // truly dormant; a live or freshly-minted lease falls through to
            // the existing --steal/refuse logic unchanged.
            // trace:BUG-307 | ai:claude
            match auto_release_decision_for_lease(
                &project_root_for_conflict,
                &conflict,
                &orch_config,
            ) {
                orchestrator::AutoReleaseDecision::SafelyDormant {
                    process_dead,
                    mtime_age_secs,
                    worktree_missing,
                } => {
                    let cause = if worktree_missing {
                        format!(
                            "worktree missing, lease {}",
                            humanize_secs_short(mtime_age_secs)
                        )
                    } else if process_dead {
                        format!(
                            "process dead {} ago, worktree clean",
                            humanize_secs_short(mtime_age_secs)
                        )
                    } else {
                        format!(
                            "mtime {} old, worktree clean",
                            humanize_secs_short(mtime_age_secs)
                        )
                    };
                    eprintln!(
                        "  {} released stale lease {} ({})",
                        crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                        (&conflict.id[..conflict.id.len().min(8)]).yellow(),
                        cause.dimmed()
                    );
                    // force_cleanup_lease removes the lease file first, then
                    // attempts `git worktree remove --force`. A `false` return
                    // means the worktree leg failed (likely already gone or
                    // permissions); the lease file is still removed and the
                    // loop's `find_scope_lease_conflict` re-check will confirm
                    // the conflict has cleared. force_cleanup_lease prints its
                    // own Warning so the operator sees the worktree-remove
                    // failure without a hard bail.
                    let _ = force_cleanup_lease(&project_root_for_conflict, &conflict);
                    remaining -= 1;
                    if remaining == 0 {
                        anyhow::bail!(
                            "auto-release sweep gave up after 16 iterations on scope `{}` — \
                             the lease store may be corrupt; inspect `.aida/sessions/`",
                            plan.scope
                        );
                    }
                    continue;
                }
                orchestrator::AutoReleaseDecision::DormantDirty { dirty_entries } => {
                    // TASK-402 (friction #3 + #4): a dormant lease with a dirty
                    // worktree is the canonical resume-after-failure state — the
                    // process died mid-implementation (orphaned) and the
                    // unfinished work lives uncommitted in that exact worktree.
                    // The bare message ("commit/stash, or --force to discard")
                    // omits the one option that keeps the WIP: resume into the
                    // existing worktree. `--steal` would remove the worktree the
                    // WIP lives in, so name it as the destructive path, not the
                    // default. trace:TASK-402 | ai:claude
                    let resume_hint = if resume.is_some() {
                        format!(
                            " You passed --resume: keep this worktree and re-attach \
                             to the recorded session — re-run with \
                             `aida queue work {} --resume <session-uuid>` \
                             (--list-sessions shows the uuid).",
                            plan.scope
                        )
                    } else {
                        format!(
                            " To keep the work, resume into this worktree: \
                             `aida queue work {} --resume` (bare = most-recent session). \
                             Only commit/stash or `aida session end {} --force` (discards) \
                             if you intend to abandon it.",
                            plan.scope,
                            &conflict.id[..conflict.id.len().min(8)]
                        )
                    };
                    anyhow::bail!(
                        "lease {} for scope `{}` looks orphaned (dormant process, \
                         worktree has {} uncommitted change(s) at {}).{}",
                        &conflict.id[..conflict.id.len().min(8)],
                        plan.scope,
                        dirty_entries,
                        conflict.worktree_path.display(),
                        resume_hint
                    );
                }
                orchestrator::AutoReleaseDecision::Live => {
                    // Fall through to the existing --steal/refuse logic.
                }
            }

            if !steal {
                // TASK-402 (friction #4): the lease is live (the auto-release
                // sweep above handles dormant/orphaned leases). Warn that
                // `--steal` ends the session AND removes its worktree — so if
                // there is unfinished work in that worktree, `--resume` (which
                // re-attaches in place) is the work-preserving path, not
                // `--steal`. trace:TASK-402 | ai:claude
                anyhow::bail!(
                    "scope `{}` is owned by lease {} ({}, worktree: {}) — \
                     to take over: `--steal` ends that session and removes its \
                     worktree (work there is lost unless committed), \
                     or `--resume` re-attaches to it in place (keeps the worktree), \
                     or `aida session end {}` manually.",
                    plan.scope,
                    &conflict.id[..conflict.id.len().min(8)],
                    conflict.role.as_deref().unwrap_or("(unset)"),
                    conflict.worktree_path.display(),
                    &conflict.id[..conflict.id.len().min(8)]
                );
            }
            eprintln!(
                "  {} {} — ending it first (--steal)",
                "⟲".cyan().bold(),
                format!(
                    "scope `{}` owned by lease {}",
                    plan.scope,
                    &conflict.id[..conflict.id.len().min(8)]
                )
                .cyan()
            );
            let short_id = &conflict.id[..conflict.id.len().min(8)];
            session_end(
                Some(&conflict.id),
                /* spec */ None,
                /* branch */ None,
                /* yes */ true,
                /* force */ false,
                /* purge_cc */ false,
                /* wait_ci */ false,
                /* watch_ci */ false,
                // --steal is a recovery path for stuck leases; skip the
                // CI probe so we don't ask the user to wait on CI for a
                // session they're actively stealing. trace:TASK-111
                /* skip_ci */
                true,
                /* return_to_pool */ false,
                // --steal reclaims a stuck lease's tree; let the default apply
                // (a pooled tree is returned + reset clean, not deleted).
                /* remove */
                false,
            )
            // BUG-311: collapse the internal session_end error into the
            // primary message so it surfaces specifically as "--steal could
            // not end lease X: <actual reason>" — not the canned "pass
            // --steal" loop and not a context line that buries the cause
            // under a "Caused by:" chain. Anyhow's `{:#}` chains the cause
            // inline on one line for the same effect. trace:BUG-311
            .map_err(|e| {
                anyhow::anyhow!(
                    "--steal could not end lease {}: {:#} \
                     (resolve manually with `aida session end {} --force` to discard, \
                     or commit/stash the worktree's changes first, then re-run)",
                    short_id,
                    e,
                    short_id,
                )
            })?;
            remaining -= 1;
            if remaining == 0 {
                anyhow::bail!(
                    "--steal sweep gave up after 16 iterations on scope `{}` — \
                     the lease store may be corrupt; inspect `.aida/sessions/`",
                    plan.scope
                );
            }
        }
    }

    // TASK-619: capture the anchor spec's status from the *local* (pre-pull)
    // view so we can detect whether the pull below reveals that another
    // machine claimed the spec under us. Best-effort + read-only — a load
    // failure just yields None, which makes the guard a no-op.
    // trace:TASK-619 | ai:claude
    let status_before_pull: Option<RequirementStatus> = storage.load().ok().and_then(|store| {
        store
            .get_requirement_by_spec_id(&plan.scope)
            .map(|r| r.status.clone())
    });

    // Pull the orphan store before resolving the worktree — keeps the
    // queue + req view fresh for the new session. Best-effort: a
    // failed pull (offline, divergent) prints a note and continues
    // with local view rather than aborting the whole pickup.
    if !no_pull {
        if let Err(e) = run_aida_db_sync_pull(storage.path()) {
            eprintln!(
                "  {} {}",
                crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                format!("pre-pickup pull failed; proceeding with local view: {}", e).yellow()
            );
        }
    }

    // TASK-619: cross-machine duplicate-pickup guard. Session leases are
    // machine-local (.aida/sessions/, gitignored), so the only shared
    // "someone is on this" signal across machines is the git-canonical
    // status flip — which is eventually-consistent. Now that we've pulled
    // the latest store, re-read the anchor spec's status and refuse if it
    // was claimed/shipped elsewhere in the window between planning this
    // pickup and now. The existing BUG-379 preflight in `session_start`
    // catches stuck-InProgress-without-lease; this guard specifically names
    // the cross-machine dup-pickup case with a recovery hint and respects
    // --force-claim / orchestrator-corroboration / review sessions.
    // trace:TASK-619 | ai:claude
    if !no_pull {
        let status_after_pull: Option<RequirementStatus> = storage.load().ok().and_then(|store| {
            store
                .get_requirement_by_spec_id(&plan.scope)
                .map(|r| r.status.clone())
        });
        let orchestrator_corroborated = {
            let root = project_root_for_config
                .clone()
                .or_else(|| std::env::current_dir().ok())
                .unwrap_or_else(|| std::path::PathBuf::from("."));
            orchestrator::detect(&root).is_orchestrated()
        };
        let is_review_session = plan.review_target.is_some()
            || role == "reviewer"
            || std::env::var("AIDA_REVIEW_VERDICT_FILE").is_ok();
        if let DupPickupDecision::Refuse(msg) = dup_pickup_recheck(
            &plan.anchor_display,
            status_before_pull.as_ref(),
            status_after_pull.as_ref(),
            force_claim,
            orchestrator_corroborated,
            is_review_session,
        ) {
            anyhow::bail!("{}", msg);
        }
    }

    // Set AIDA_SESSION_ROLE for the exec'd claude (and for any in-process
    // logic the rest of this command runs against). session_start reads
    // it to record the lease's role field when --role isn't passed; we
    // pass --role anyway, but the env var is what the claude SessionStart
    // hook sees on launch.
    std::env::set_var("AIDA_SESSION_ROLE", &role);

    // STORY-248: resolve the stacked base BEFORE session_start so the
    // worktree is forked from the right place and the SHA capture has a
    // real base to record. Both `--stack` and `--base` flow through the
    // same `session_start(base: Option<&str>)` parameter.
    // trace:STORY-248 | ai:claude
    let project_root_for_base = find_main_worktree_root()?;
    let cwd_for_base = std::env::current_dir().unwrap_or_else(|_| project_root_for_base.clone());
    let resolved_base = resolve_stack_base(
        &project_root_for_base,
        &cwd_for_base,
        stack,
        base,
        force_base,
    )?;
    if let Some(b) = resolved_base.as_deref() {
        eprintln!(
            "  {} base: {} {}",
            crate::glyph(crate::glyphs::Glyph::FlowActive).cyan().bold(),
            b.cyan(),
            if stack {
                "(detected via --stack)".dimmed().to_string()
            } else {
                "(--base)".dimmed().to_string()
            }
        );
    }

    // session_start handles worktree creation, lease persistence, env
    // shim, conflict detection. We always pass launch=false so we can
    // (a) write the cluster manifest from the new lease and (b) emit
    // a queue-work-specific launch summary before exec.
    session_start(
        &plan.scope,
        branch_override,
        resolved_base.as_deref(),
        /* reuse_branch */ false,
        path_override,
        /* forge_override */ None,
        /* branch_style */ "auto",
        /* launch */ false,
        /* launch_title */ None,
        /* launch_name */ None,
        // STORY-495: inert here (launch=false); the real launch below threads
        // the resolved `permission_mode` into the exec call directly.
        /* permission_mode */
        permission_mode.as_deref(),
        /* launch_contained */
        false,
        /* role */ Some(role.clone()),
        /* force_claim */ force_claim,
        // STORY-714: config-driven ([worktree_pool] enabled). The pool is used
        // only for non-stacked spawns (resolved_base is None unless --stack /
        // --base), so stacked work keeps a fresh `git worktree add`.
        /* use_pool */
        None,
    )?;

    // Look up the lease we just minted: by scope, by owner=us, freshest.
    let project_root = find_main_worktree_root()?;
    let lease = list_leases(&project_root)
        .into_iter()
        .filter(|l| l.scope.eq_ignore_ascii_case(&plan.scope))
        .max_by_key(|l| l.started_at)
        .ok_or_else(|| {
            anyhow::anyhow!(
                "session_start completed but no lease for scope `{}` is visible — try `aida session leases`",
                plan.scope
            )
        })?;

    // TASK-99: warn (don't auto-pull) when the base the new worktree forked
    // from is behind origin/main. Closes the visibility half of the
    // 2026-05-13 stale-base pain cheaply: the operator sees the drift at
    // pickup and can `aida rebase` before the session accumulates work on a
    // stale base. We deliberately do NOT auto-pull here — that risks
    // surprising the worktree; the orchestrator drain (fresh main per-phase)
    // and the rebase verb own divergence handling. Best-effort + silent on
    // missing data (no origin/main → fresh clone / offline).
    // trace:TASK-99 | ai:claude
    {
        let base_ref = resolved_base.as_deref().unwrap_or("main");
        if let Some(behind) = commits_behind_origin_main(&project_root, base_ref) {
            if let Some(msg) = behind_origin_warning(behind, "main") {
                eprintln!(
                    "  {} {}",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                    msg.yellow()
                );
            }
        }
    }

    // STORY-248: register the stacked-branch entry in `.aida/stacks.json`
    // so `aida pull --auto`'s cascade can find it when the parent merges.
    // session_start records the parent fields on the lease itself; we
    // mirror them into the dedicated graph file because the cascade
    // needs to consult them AFTER the lease has been removed by
    // `aida queue done`. Best-effort — a write failure logs but doesn't
    // fail the pickup. trace:STORY-248 | ai:claude
    if let (Some(parent), Some(sha)) = (
        lease.parent_branch.as_deref(),
        lease.parent_branch_sha.as_deref(),
    ) {
        let mut graph = stacks::load(&project_root);
        stacks::add(
            &mut graph,
            stacks::StackEntry {
                branch: lease.branch.clone(),
                parent_branch: parent.to_string(),
                parent_branch_sha: sha.to_string(),
                spec_id: Some(plan.scope.clone()),
                created_at: chrono::Utc::now(),
            },
        );
        if let Err(e) = stacks::save(&project_root, &graph) {
            eprintln!(
                "  {} {}",
                crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                format!(
                    "stack graph save failed: {} (cascade may miss this branch)",
                    e
                )
                .yellow()
            );
        } else {
            eprintln!(
                "  {} stacked: {} → {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                lease.branch.cyan(),
                parent.cyan()
            );
        }
    }

    // Cluster manifest: pre-populate items so /aida-pickup can walk
    // them top-down. Skip for head/item modes (single item → no plan
    // needed beyond the queue head). trace:STORY-98 | ai:claude
    //
    // TASK-95: discover the plan brief for the anchor spec from any
    // owning docs/plans/ file. Cluster mode always writes a manifest, so
    // it just gains the brief; head/item modes write a manifest only
    // when a plan file exists (no plan file → today's no-op behavior).
    // trace:TASK-95 | ai:claude
    let plan_context = discover_plan_context(&project_root, &plan.anchor_display);
    // TASK-112: the claude session id to record in the manifest — the
    // UUID minted for a fresh launch, or the id being resumed.
    // STORY-132: a caller-minted `--session-id` is recorded even under
    // `--no-launch` (the TUI sets up a session then hosts the launch
    // itself), so the manifest carries the id either way.
    let claude_session_id: Option<String> = match (&launch, session_id) {
        (Some(l), _) => Some(l.session_id().to_string()),
        // --no-launch + caller-minted id: record it so the manifest
        // carries it (already validated as a UUID at function entry).
        (None, Some(sid)) => Some(sid.to_string()),
        // BUG-225: --no-launch --no-human defers a headless launch, and
        // `claude -p` requires a `--session-id`. Mint one when the caller
        // didn't supply it so the manifest carries the id and the printed
        // hint is a complete, round-trippable command.
        (None, None) if no_human => Some(uuid::Uuid::now_v7().to_string()),
        (None, None) => None,
    };
    // Write the manifest when there are planned cluster items, a plan
    // brief was discovered, there's a claude session id to record so
    // a later `--resume` can find this conversation, or this is a batch
    // pickup whose batch marker /aida-pickup needs.
    // trace:STORY-98, TASK-95, TASK-112, TASK-272 | ai:claude
    if plan.mode == QueueWorkMode::Cluster
        || plan_context.is_some()
        || claude_session_id.is_some()
        || batch_name.is_some()
    {
        write_queue_work_manifest(
            &project_root,
            &lease,
            &plan,
            plan_context.clone(),
            claude_session_id.clone(),
            batch_name,
        )?;
        if plan.mode == QueueWorkMode::Cluster {
            eprintln!(
                "  {} wrote manifest with {} planned item(s)",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                plan.entries.len()
            );
        }
        if let Some(ctx) = &plan_context {
            eprintln!(
                "  {} attached plan brief from {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                ctx.plan_file.cyan()
            );
        }
    }

    if no_launch {
        eprintln!();
        eprintln!(
            "{} setup complete; launch deferred (`--no-launch`).",
            crate::glyph(crate::glyphs::Glyph::Check).green().bold()
        );
        eprintln!(
            "  {}",
            format!("cd {}", lease.worktree_path.display()).cyan()
        );
        eprintln!(
            "  {}    {}",
            "source .aida/session-env.sh".cyan(),
            "# share parent's cargo target/".dimmed()
        );
        if no_human {
            // STORY-263: mirror the headless launch the non-`--no-launch`
            // path would have run. BUG-225: render it from
            // `claude_headless_args` (via `headless_launch_hint`) so the
            // copy-pasteable command can't drift from `exec_claude_headless`
            // — same flag order, `--session-id` included, prompt last.
            // STORY-278: helper also prefixes `AIDA_HEADLESS=1` to match
            // the env `exec_claude_headless` sets, so the copy-pasted hint
            // launches an equivalent process.
            let sid = claude_session_id.as_deref().unwrap_or_default();
            eprintln!("  {}", headless_launch_hint(&prompt, sid, contained).cyan());
        } else {
            let mut args = session::claude_session_args(
                permission_mode.as_deref(),
                None,
                Some(&prompt),
                None,
                contained,
            );
            if contained && !args.iter().any(|arg| arg == "--permission-mode") {
                args.splice(
                    0..0,
                    ["--permission-mode".to_string(), "dontAsk".to_string()],
                );
            }
            eprintln!(
                "  {}",
                format!("claude {}", shell_join_display(&args)).cyan()
            );
        }
        // BUG-673: next-step breadcrumb after a `queue work` pickup. The lease
        // is taken and the worktree is set up (only the launch is deferred), so
        // this IS a genuine pickup — the natural next move is to finish the work
        // (`aida queue done <id>`). Closes the gap where the next[] block
        // dropped out at `queue work`. Emit the TOON `next[]` block in agent
        // mode, the human `Next:` block otherwise. trace:BUG-673 | ai:claude
        {
            let next = crate::help_next::queue_work_next(&plan.anchor_display);
            let rendered = if agent_output_mode() {
                crate::help_next::render(&next)
            } else {
                crate::help_next::render_human(&next)
            };
            if let Some(block) = rendered {
                println!("{block}");
            }
        }
        return Ok(());
    }

    // Chdir + source session-env shim + exec claude with the skill prompt.
    // Mirrors session_start's launch path (TASK-63 env sourcing).
    let env_shim = lease.worktree_path.join(".aida").join("session-env.sh");
    let applied_vars: Vec<String> = match std::fs::read_to_string(&env_shim) {
        Ok(body) => apply_session_env_to_process(&body),
        Err(_) => Vec::new(),
    };
    if !applied_vars.is_empty() {
        eprintln!(
            "  {} sourced .aida/session-env.sh ({})",
            crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
            applied_vars.join(", ").dimmed()
        );
    }
    std::env::set_current_dir(&lease.worktree_path)
        .with_context(|| format!("failed to chdir into {}", lease.worktree_path.display()))?;

    // TASK-112: exec — resume the prior conversation, or cold-launch
    // with the minted session id so this conversation is itself
    // resumable later. trace:TASK-112 | ai:claude
    let launch = launch.expect("launch decision is set when !no_launch");

    // BUG-226: a standalone `aida queue work <PR-N> --role reviewer` — a
    // reviewer session on a PR scope NOT spawned by the `--auto-complete`
    // orchestrator. The orchestrator sets `AIDA_REVIEW_VERDICT_FILE` on
    // its phase-3 child, so its absence is the standalone signal. For a
    // standalone run, point the `/aida-review` skill at a verdict file and
    // route the launch through `run_standalone_reviewer` (spawn + wait +
    // end-of-command summary) instead of `exec`'ing claude — so the
    // command no longer exits silently to the shell prompt.
    // trace:BUG-226 | ai:claude
    let standalone_reviewer: Option<(u64, std::path::PathBuf)> = if role
        .eq_ignore_ascii_case("reviewer")
        && std::env::var("AIDA_REVIEW_VERDICT_FILE")
            .ok()
            .filter(|s| !s.is_empty())
            .is_none()
    {
        plan.review_target.map(|(_, n)| {
            (
                n,
                project_root
                    .join(".aida")
                    .join("review-verdicts")
                    .join(format!("PR-{n}.json")),
            )
        })
    } else {
        None
    };
    if let Some((_, verdict_path)) = &standalone_reviewer {
        if let Some(dir) = verdict_path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        // Clear any stale verdict so the summary can't read a prior run's.
        let _ = std::fs::remove_file(verdict_path);
        // The `/aida-review` skill writes the verdict here — it keys off
        // this env var. Setting it for standalone runs too is what makes
        // the skill "always write the verdict file" (BUG-226 acceptance).
        std::env::set_var("AIDA_REVIEW_VERDICT_FILE", verdict_path);
    }

    eprintln!();
    if let Some((pr, verdict_path)) = standalone_reviewer {
        return run_standalone_reviewer(
            &project_root,
            pr,
            launch,
            &prompt,
            permission_mode.as_deref(),
            &plan.scope,
            &lease.branch,
            &role,
            &lease.worktree_path,
            no_human,
            quiet,
            &verdict_path,
            contained,
        );
    }
    // TASK-895: a Codex tab hosts a fresh interactive Codex session. Codex has
    // no caller-minted session id / AIDA-addressable resume, and the interactive
    // tab launch is never `--no-human` (the headless drain resolves its own
    // vendor via STORY-683), so this branch handles only the interactive Codex
    // launch and leaves the entire Claude `match launch` below byte-identical.
    // trace:TASK-895 | ai:claude
    if vendor.eq_ignore_ascii_case("codex") && !no_human {
        // BUG-743: queue/do's interactive Codex path used to ignore the
        // STORY-495 `[agents] bypass` resolver and launch bare `codex
        // /aida-pickup`, leaving operators in prompt-per-command posture even
        // after opting the supervised fleet into bypass. Map the resolved
        // uniform bypass posture to Codex's actual flag here; `None` and every
        // non-bypass Claude permission mode keep Codex native.
        let codex_bypass = permission_mode.as_deref() == Some("bypassPermissions");
        eprintln!(
            "{} {}",
            crate::glyph(crate::glyphs::Glyph::FlowActive)
                .green()
                .bold(),
            format!(
                "launching codex in {} ({}, prompt `{}`)",
                lease.worktree_path.display(),
                if codex_bypass { "bypass" } else { "native" },
                prompt
            )
            .cyan()
        );
        return session::exec_codex_session(&prompt, codex_bypass);
    }
    match launch {
        QueueWorkLaunch::Resume(id) => {
            if no_human {
                let log_path = project_root
                    .join(".aida")
                    .join("headless-logs")
                    .join(format!("{}-{}.jsonl", lease.branch, id));
                eprintln!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::FlowActive)
                        .green()
                        .bold(),
                    format!(
                        "resuming claude headless session {} in {} (claude -p, {}, prompt `{}`)",
                        &id[..id.len().min(8)],
                        lease.worktree_path.display(),
                        claude_posture_display(permission_mode.as_deref(), contained),
                        prompt
                    )
                    .cyan()
                );
                eprintln!(
                    "  {} headless output → {}",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    log_path.display().to_string().dimmed()
                );
                // BUG-342: no-human resumes must use the same structural
                // AskUserQuestion denial as fresh headless launches. Plain
                // `claude --resume` bypasses `claude_headless_resume_args`.
                // trace:BUG-342 | ai:codex
                let tee_opts =
                    headless_tee::TeeOptions::from_env_and_flag(false).with_label(&lease.branch);
                let status = session::spawn_claude_headless_resume(
                    &prompt,
                    &id,
                    &log_path,
                    &lease.worktree_path,
                    &tee_opts,
                    contained,
                )?;
                std::process::exit(status.code().unwrap_or(1));
            }
            eprintln!(
                "{} {}",
                crate::glyph(crate::glyphs::Glyph::FlowActive)
                    .green()
                    .bold(),
                format!(
                    "resuming claude session {} in {} ({})",
                    &id[..id.len().min(8)],
                    lease.worktree_path.display(),
                    claude_posture_display(permission_mode.as_deref(), contained)
                )
                .cyan()
            );
            session::exec_claude_resume(&id, permission_mode.as_deref(), contained)
        }
        QueueWorkLaunch::Fresh(id) => {
            let name = session::derive_session_name(&plan.scope, &lease.branch, &role);
            if no_human {
                // STORY-263: headless launch — `claude -p`, single-turn,
                // exits on its own (no Ctrl+D). `bypassPermissions` is forced
                // (SPIKE-7 Q2 — `acceptEdits` leaves Bash gated); the
                // stream-json output goes to a log file the watchdog
                // (TASK-298) can tail. trace:STORY-263 | ai:claude
                let log_path = project_root
                    .join(".aida")
                    .join("headless-logs")
                    .join(format!("{}-{}.jsonl", lease.branch, id));
                // BUG-705: the banner names the RESOLVED headless vendor —
                // before, it always said claude even when the drain was
                // routed to codex, hiding the unrouted-exec bug.
                let headless_vendor = crate::session::resolve_headless_vendor(
                    &find_project_root().unwrap_or_else(|_| std::path::PathBuf::from(".")),
                );
                let launch_detail = match headless_vendor {
                    crate::session::HeadlessVendor::Claude => format!(
                        "claude -p, {}",
                        claude_posture_display(permission_mode.as_deref(), contained)
                    ),
                    crate::session::HeadlessVendor::Codex => "codex exec".to_string(),
                    // trace:TASK-1048 | ai:claude
                    crate::session::HeadlessVendor::Agy => "agy -p".to_string(),
                };
                eprintln!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::FlowActive)
                        .green()
                        .bold(),
                    format!(
                        "launching {} headless in {} ({}, prompt `{}`)",
                        headless_vendor.as_str(),
                        lease.worktree_path.display(),
                        launch_detail,
                        prompt
                    )
                    .cyan()
                );
                eprintln!(
                    "  {} headless output → {}",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    log_path.display().to_string().dimmed()
                );
                // TASK-307: tee high-signal events so the operator can
                // follow the headless run without opening a second terminal
                // to tail the JSONL. Disable with `--no-tee-headless` or
                // `AIDA_TEE_HEADLESS=0`; failure events stream regardless.
                // trace:TASK-307 | ai:claude
                let tee_opts =
                    headless_tee::TeeOptions::from_env_and_flag(false).with_label(&lease.branch);
                return session::exec_claude_headless(
                    &prompt,
                    &id,
                    &log_path,
                    &tee_opts,
                    contained,
                    Some(&lease.id),
                );
            }
            eprintln!(
                "{} {}",
                crate::glyph(crate::glyphs::Glyph::FlowActive)
                    .green()
                    .bold(),
                format!(
                    "launching claude in {} ({}, prompt `{}`)",
                    lease.worktree_path.display(),
                    claude_posture_display(permission_mode.as_deref(), contained),
                    prompt
                )
                .cyan()
            );
            session::exec_claude_with_session(
                permission_mode.as_deref(),
                name.as_deref(),
                &prompt,
                &id,
                contained,
            )
        }
    }
}

/// BUG-226: drive a standalone `aida queue work <PR-N> --role reviewer`
/// launch — spawn `claude` (not `exec`) so this process survives to read
/// the verdict file + headless JSONL log and print an end-of-command
/// summary. The bug was the silent exit to the shell prompt: a headless
/// reviewer ran to completion, posted a real review, and left no terminal
/// trace of pass/fail, cost, or where the artifacts landed.
///
/// The `--auto-complete` orchestrator's phase-3 reviewer does NOT come
/// here — it sets `AIDA_REVIEW_VERDICT_FILE`, which clears the standalone
/// signal — so the orchestrator keeps owning its own progress output.
/// trace:BUG-226 | ai:claude
#[allow(clippy::too_many_arguments)]
fn run_standalone_reviewer(
    project_root: &std::path::Path,
    pr: u64,
    launch: QueueWorkLaunch,
    prompt: &str,
    // STORY-495: `None` → faithful native launch (no `--permission-mode`).
    permission_mode: Option<&str>,
    scope: &str,
    branch: &str,
    role: &str,
    worktree: &std::path::Path,
    no_human: bool,
    quiet: bool,
    verdict_path: &std::path::Path,
    contained: bool,
) -> Result<()> {
    // Spawn claude, wait, and capture the headless JSONL log path (None
    // for an interactive review — there is no stream-json log).
    let (status, log_path): (std::process::ExitStatus, Option<std::path::PathBuf>) = match launch {
        QueueWorkLaunch::Resume(id) => {
            if no_human {
                let log_path = project_root
                    .join(".aida")
                    .join("headless-logs")
                    .join(format!("{branch}-{id}.jsonl"));
                eprintln!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::FlowActive)
                        .green()
                        .bold(),
                    format!(
                        "resuming claude headless reviewer session {} in {} (claude -p, {})",
                        &id[..id.len().min(8)],
                        worktree.display(),
                        claude_posture_display(permission_mode, contained)
                    )
                    .cyan()
                );
                eprintln!(
                    "  {} headless output → {}",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    log_path.display().to_string().dimmed()
                );
                // BUG-342: a no-human reviewer resume is still unattended;
                // route it through the shared headless resume argv so
                // AskUserQuestion is structurally denied.
                // trace:BUG-342 | ai:codex
                let tee_opts =
                    headless_tee::TeeOptions::from_env_and_flag(false).with_label("reviewer");
                let status = session::spawn_claude_headless_resume(
                    prompt, &id, &log_path, worktree, &tee_opts, contained,
                )?;
                (status, Some(log_path))
            } else {
                eprintln!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::FlowActive)
                        .green()
                        .bold(),
                    format!(
                        "resuming claude reviewer session {} in {} ({})",
                        &id[..id.len().min(8)],
                        worktree.display(),
                        claude_posture_display(permission_mode, contained)
                    )
                    .cyan()
                );
                (
                    session::spawn_claude_resume(&id, permission_mode, contained)?,
                    None,
                )
            }
        }
        QueueWorkLaunch::Fresh(id) => {
            if no_human {
                let log_path = project_root
                    .join(".aida")
                    .join("headless-logs")
                    .join(format!("{branch}-{id}.jsonl"));
                eprintln!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::FlowActive)
                        .green()
                        .bold(),
                    format!(
                        "launching claude headless reviewer in {} (claude -p, {})",
                        worktree.display(),
                        claude_posture_display(permission_mode, contained)
                    )
                    .cyan()
                );
                eprintln!(
                    "  {} headless output → {}",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    log_path.display().to_string().dimmed()
                );
                // TASK-307: tee high-signal events for the standalone
                // reviewer too. Label = "reviewer" so a future concurrent
                // batch can disambiguate `│ [headless:reviewer]` lines.
                // trace:TASK-307 | ai:claude
                let tee_opts =
                    headless_tee::TeeOptions::from_env_and_flag(false).with_label("reviewer");
                let status =
                    session::spawn_claude_headless(prompt, &id, &log_path, &tee_opts, contained)?;
                (status, Some(log_path))
            } else {
                let name = session::derive_session_name(scope, branch, role);
                eprintln!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::FlowActive)
                        .green()
                        .bold(),
                    format!(
                        "launching claude reviewer in {} ({}, prompt `{}`)",
                        worktree.display(),
                        claude_posture_display(permission_mode, contained),
                        prompt
                    )
                    .cyan()
                );
                let status = session::spawn_claude_session(
                    permission_mode,
                    name.as_deref(),
                    prompt,
                    &id,
                    contained,
                )?;
                (status, None)
            }
        }
    };

    // STORY-439: tag-along reviewer-side calibration capture. Resolve
    // every spec the PR credits (via the existing title / branch / body
    // precedence used by the squash-subject repair) and write a review
    // slot per spec. Best-effort; never blocks the summary print.
    // trace:STORY-439 | ai:claude
    if let Ok(meta) = fetch_pr_ship_metadata_via_gh(project_root, pr) {
        for spec in pr_ship::derive_squash_subject_spec_ids(&meta.title, branch, &meta.body) {
            capture_review_calibration_for_spec(project_root, verdict_path, &spec);
        }
    }

    // End-of-command summary, assembled from the verdict file the
    // `/aida-review` skill wrote and (headless only) the JSONL log.
    // `--quiet` suppresses it for scripted consumers that read the
    // verdict file directly. trace:BUG-226 | ai:claude
    if !quiet {
        let verdict_json = std::fs::read_to_string(verdict_path).ok();
        let result_event = log_path
            .as_deref()
            .and_then(|p| std::fs::read_to_string(p).ok())
            .and_then(|s| reviewer_summary::parse_result_event(&s));
        let summary = reviewer_summary::format_reviewer_summary(
            pr,
            verdict_json.as_deref(),
            result_event.as_ref(),
            verdict_path,
            log_path.as_deref(),
            status.code(),
        );
        println!();
        println!("{summary}");
    }

    // Propagate claude's exit code so a scripted consumer can branch on
    // it; a clean exit returns `Ok(())` so `main` records telemetry.
    match status.code() {
        Some(0) | None => Ok(()),
        Some(code) => std::process::exit(code),
    }
}

// ===========================================================================
// STORY-246: `aida queue work --auto-complete` — full lifecycle orchestrator.
// The phase-sequencing logic lives in `auto_complete.rs`; this is the real
// `PhaseDriver` — it spawns Claude sessions, polls CI, and shells out to
// `gh` / `aida` / `cargo`. trace:STORY-246 | ai:claude
// ===========================================================================

/// Partial view of a `SessionLease` TOML — just the fields the orchestrator
/// needs to discover after spawning a session. trace:STORY-246 | ai:claude
#[derive(serde::Deserialize)]
struct LeasePeek {
    id: String,
    branch: String,
    /// Optional for older leases and minimal test fixtures. Used only by the
    /// phase watchdog's local descendant scan.
    // trace:BUG-749 | ai:codex
    #[serde(default)]
    creator_pid: Option<u32>,
    /// Worktree path — re-read by the BUG-223 branch-swap reconciliation to
    /// recover the live branch when `/aida-pr` swapped it mid-phase.
    /// `#[serde(default)]` so a lease (or hand-written test fixture) without
    /// the field still parses. trace:BUG-223 | ai:claude
    #[serde(default)]
    worktree_path: std::path::PathBuf,
}

/// Statuses the `--auto-complete` orchestrator can drive from scratch
/// (TASK-292). The orchestrator runs a full implementer → CI → reviewer →
/// merge lifecycle starting at phase 1, so it can only begin a spec that
/// hasn't started: Draft / Approved / Planned. In Progress and Done are
/// mid-flight (someone is on it / it sits on a branch awaiting merge);
/// Completed and Rejected are terminal. trace:TASK-292 | ai:claude
fn auto_complete_head_drivable(status: &RequirementStatus) -> bool {
    matches!(
        status,
        RequirementStatus::Draft | RequirementStatus::Approved | RequirementStatus::Planned
    )
}

/// Pure pickup-order resolution for the `aida queue work --auto-complete` head
/// (TASK-292): given queued `(display_id, status)` pairs already in pickup
/// order, return the first orchestrator-drivable spec together with the items
/// skipped to reach it, or `Err(skipped)` when none is drivable. Split out of
/// [`resolve_auto_complete_head`] so the skip / empty-queue logic is
/// unit-testable without a storage fixture. trace:TASK-292 | ai:claude
#[allow(clippy::type_complexity)]
fn pick_auto_complete_head(
    candidates: &[(String, RequirementStatus)],
) -> std::result::Result<(String, Vec<(String, RequirementStatus)>), Vec<(String, RequirementStatus)>>
{
    let mut skipped: Vec<(String, RequirementStatus)> = Vec::new();
    for (id, status) in candidates {
        if auto_complete_head_drivable(status) {
            return Ok((id.clone(), skipped));
        }
        skipped.push((id.clone(), status.clone()));
    }
    Err(skipped)
}

/// Build the `(display_id, status)` candidate list for the active role's
/// queue in pickup order (queue position ascending, same as `aida queue
/// next`) — the shared input to [`pick_auto_complete_head`] for both
/// single-head pickup (TASK-292) and the `nextN` drain (TASK-293).
/// trace:TASK-292 TASK-293 | ai:claude
fn auto_complete_head_candidates(
    storage: &Storage,
    user_id: &str,
) -> Result<Vec<(String, RequirementStatus)>> {
    let entries = storage.queue_list(user_id, /* include_completed */ false)?;
    let store = storage.load()?;
    let role_filter: Option<String> = std::env::var("AIDA_SESSION_ROLE")
        .ok()
        .filter(|s| !s.is_empty());

    let mut ordered: Vec<&aida_core::QueueEntry> = entries
        .iter()
        .filter(|e| match &role_filter {
            Some(r) => e.for_role.as_deref() == Some(r.as_str()),
            None => true,
        })
        .collect();
    ordered.sort_by_key(|e| e.position);

    Ok(ordered
        .iter()
        .filter_map(|e| {
            store
                .requirements
                .iter()
                .find(|r| r.id == e.requirement_id)
                .map(|r| (r.display_id(), r.status.clone()))
        })
        .collect())
}

/// Resolve the queue head for `aida queue work --auto-complete` invoked with no
/// positional SPEC id (TASK-292) — the natural composition of the no-arg "pick
/// the head" semantics with `--auto-complete`. Walks the active role's queue in
/// pickup order (queue position ascending, same as `aida queue next`) and
/// returns the first item the orchestrator can drive from scratch, skipping —
/// with a note — any item already In Progress / Done / terminal. Errors when
/// nothing drivable remains. trace:TASK-292 | ai:claude
fn resolve_auto_complete_head(storage: &Storage, user_id: &str) -> Result<String> {
    let role_label = std::env::var("AIDA_SESSION_ROLE")
        .ok()
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "any role".to_string());
    let candidates = auto_complete_head_candidates(storage, user_id)?;

    match pick_auto_complete_head(&candidates) {
        Ok((spec, skipped)) => {
            // Acceptance criterion: name each item skipped to reach the
            // drivable head so the pickup is never silently surprising.
            for (id, status) in &skipped {
                eprintln!(
                    "  {} skipping {} ({}) — the orchestrator drives a full \
                     lifecycle from scratch and cannot resume it",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    id,
                    status
                );
            }
            Ok(spec)
        }
        Err(skipped) if skipped.is_empty() => {
            anyhow::bail!("queue is empty for {role_label}; nothing to drive")
        }
        Err(skipped) => {
            // The queue has items, but every one is in-flight or terminal —
            // name the first few so it's clear *why* there's nothing to
            // drive, without dumping a long stale list.
            const SHOWN: usize = 5;
            let detail = skipped
                .iter()
                .take(SHOWN)
                .map(|(id, status)| format!("{id} ({status})"))
                .collect::<Vec<_>>()
                .join(", ");
            let more = skipped.len().saturating_sub(SHOWN);
            let suffix = if more > 0 {
                format!(", +{more} more")
            } else {
                String::new()
            };
            anyhow::bail!(
                "no drivable item in the queue for {role_label}; nothing to drive — \
                 {} queued item{} in-flight or terminal: {detail}{suffix}",
                skipped.len(),
                if skipped.len() == 1 { "" } else { "s" },
            )
        }
    }
}

/// `aida orchestrator status` — print the corroborated orchestrator context
/// of the current process. The bare status word goes to stdout (so a skill can
/// branch on it cleanly); any informational note goes to stderr.
/// trace:BUG-233 | ai:claude
fn handle_orchestrator_command(cmd: &OrchestratorCommand) -> Result<()> {
    match cmd {
        OrchestratorCommand::Status { json } => {
            // Resolve the shared `.aida/` root from any worktree so a child in
            // a sibling worktree reads the *orchestrator's* marker dir. On a
            // resolution failure the marker lookup simply finds nothing — the
            // verdict fails safe to interactive. trace:BUG-233 | ai:claude
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let ctx = orchestrator::detect(&project_root);
            if *json {
                println!(
                    "{{\"context\":\"{}\",\"corroborated\":{},\"reason\":\"{}\"}}",
                    ctx.status_word(),
                    ctx.is_orchestrated(),
                    ctx.reason_slug()
                );
            } else {
                println!("{}", ctx.status_word());
            }
            // The note is informational, never alarming — BUG-233's corrected
            // diagnosis: a bare `AIDA_AUTO_COMPLETE` is not a leak to chase.
            if let Some(note) = ctx.informational_note() {
                eprintln!(
                    "  {} {}",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                    note.dimmed()
                );
            }
            Ok(())
        }
    }
}

/// `aida state-snapshot --spec <SPEC-ID>` — emit the seven-row
/// finish-state preamble deterministically (TASK-391). Reads the spec from
/// the git-canonical store, the branch + ahead/upstream facts from `git`,
/// the open PR from `gh pr list`, the drain phase + mode from
/// `.aida/drain-state.json`, the orchestrator on/off from the same
/// corroboration `aida orchestrator status` uses, and the plan path from
/// the active session's manifest. Tests / fmt are caller-supplied (the
/// skill knows what it just ran). trace:TASK-391 | ai:claude
fn handle_state_snapshot_command(
    backend: &dyn aida_core::DatabaseBackend,
    store_path: &std::path::Path,
    spec: &str,
    tests: &str,
    fmt: &str,
    json: bool,
) -> Result<()> {
    let snap = gather_state_snapshot(backend, store_path, spec, tests, fmt)?;
    let out = if json {
        snap.render_json()
    } else {
        snap.render_text()
    };
    println!("{}", out);
    Ok(())
}

/// Assemble the [`state_snapshot::StateSnapshot`] from the live process
/// context — spec store + git + gh + drain-state + manifest. Kept as a
/// gathering function (no rendering) so the renderer stays unit-testable
/// with hand-constructed snapshots.
fn gather_state_snapshot(
    backend: &dyn aida_core::DatabaseBackend,
    store_path: &std::path::Path,
    spec_id: &str,
    tests: &str,
    fmt: &str,
) -> Result<state_snapshot::StateSnapshot> {
    use state_snapshot::{BranchRow, PlanRow, PrRow, SpecRow, StateSnapshot};

    let req = backend
        .get_requirement_by_spec_id(spec_id)?
        .ok_or_else(|| anyhow::anyhow!("requirement not found: {spec_id}"))?;
    let spec = SpecRow {
        id: req.display_id(),
        title: req.title.clone(),
        status: req.status.to_string(),
    };

    // `project_root` is the current (possibly session) worktree — it holds
    // this session's branch, its PR, and its `.aida/sessions/` symlink. The
    // *main* worktree root holds the shared drain-state and orchestrator
    // marker dirs that every worktree of the same project sees. Resolve
    // both: branch/PR/manifest read from `project_root`; drain + orchestrator
    // read from `main_root`. trace:TASK-391 | ai:claude
    let project_root = store_path
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
    let main_root = find_main_worktree_root().unwrap_or_else(|_| project_root.clone());

    let branch = current_branch_at(&project_root).map(|name| {
        let ahead_main = ahead_behind_vs_ref(&project_root, &name, "origin/main")
            .or_else(|| ahead_behind_vs_ref(&project_root, &name, "main"))
            .map(|(a, _)| a);
        let push_status = describe_push_status(&project_root, &name);
        BranchRow {
            name,
            ahead_main,
            push_status,
        }
    });

    let pr = match branch.as_ref() {
        // STORY-516: forge-routed. trace:STORY-516 | ai:claude
        Some(b) => match change_lookup_for_branch(&project_root, &b.name) {
            crate::forge::ChangeLookup::Found(c) => PrRow::Open {
                number: c.id,
                url: c.url,
            },
            crate::forge::ChangeLookup::NoChange => PrRow::None,
            crate::forge::ChangeLookup::CliMissing => PrRow::GhMissing,
            crate::forge::ChangeLookup::Unreachable(detail) => PrRow::GhUnreachable { detail },
            crate::forge::ChangeLookup::CliFailed(detail) => PrRow::GhFailed { detail },
        },
        None => PrRow::None,
    };

    let drain = describe_drain_row(&main_root);

    let plan = locate_plan_for_active_session(&project_root)
        .map(|path| PlanRow::File { path })
        .unwrap_or(PlanRow::None);

    Ok(StateSnapshot {
        spec,
        branch,
        pr,
        drain,
        tests: tests.to_string(),
        fmt: fmt.to_string(),
        plan,
    })
}

/// Classify the branch's push state versus its tracked upstream:
///   * `"pushed"`  — upstream tracks AND local has no commits ahead of it
///   * `"local"`   — no upstream, or local is ahead of upstream
///   * `"unknown"` — the upstream lookup itself failed (git error / detached)
///     trace:TASK-391 | ai:claude
fn describe_push_status(project_root: &std::path::Path, branch: &str) -> String {
    match upstream_ref_for(project_root, branch) {
        None => "local".to_string(),
        Some(u) => match ahead_behind_vs_ref(project_root, branch, &u) {
            Some((0, _behind)) => "pushed".to_string(),
            Some(_) => "local".to_string(),
            None => "unknown".to_string(),
        },
    }
}

/// Build the Drain row from `.aida/drain-state.json` (the live
/// `--auto-complete` orchestrator's record) plus the orchestrator
/// corroboration check. Both inputs are best-effort: missing drain file
/// → "interactive" mode; missing phase env → unknown phase number.
/// trace:TASK-391 | ai:claude
fn describe_drain_row(project_root: &std::path::Path) -> state_snapshot::DrainRow {
    let orchestrator = orchestrator::detect(project_root).is_orchestrated();
    let phase = std::env::var(orchestrator::PHASE_ENV)
        .ok()
        .and_then(|s| s.parse::<u32>().ok());

    let drain_state = drain_state::DrainState::read(project_root);
    let mode = match drain_state {
        None => "interactive".to_string(),
        Some(state) => describe_drain_mode(&state),
    };

    state_snapshot::DrainRow {
        phase,
        mode,
        orchestrator,
    }
}

/// Build the "mode" portion of the Drain row — the human-readable
/// descriptor right of `phase N/6` and left of `orchestrator on|off`:
///   * `"single (<spec>)"`
///   * `"batch <NAME> (<done>/<total> done, <queued> queued)"`
///   * `"next-N (<done>/<total> done, <queued> queued)"`
///     Lives in main.rs (not in `state_snapshot`) so the module stays free of
///     `DrainState` coupling for tests. trace:TASK-391 trace:TASK-417 | ai:claude
fn describe_drain_mode(state: &drain_state::DrainState) -> String {
    let total = state.members.len();
    let done = state
        .members
        .iter()
        .filter(|m| m.state == drain_state::STATE_COMPLETED)
        .count();
    let queued = state
        .members
        .iter()
        .filter(|m| m.state == drain_state::STATE_QUEUED)
        .count();
    match state.mode.as_str() {
        "single" => {
            let spec = state.current.clone().unwrap_or_else(|| "?".to_string());
            format!("single ({spec})")
        }
        "batch" => {
            let name = state.batch.clone().unwrap_or_else(|| "?".to_string());
            format!("batch {name} ({done}/{total} done, {queued} queued)")
        }
        "next-n" => format!("next-{total} ({done}/{total} done, {queued} queued)"),
        other => other.to_string(),
    }
}

/// Find the `docs/plans/` path attached to the active session's manifest,
/// if any — the Plan row's value. Walks `active_lease_for_cwd` to find the
/// session id, then loads `<project_root>/.aida/sessions/<id>.manifest.toml`
/// and reads its `PlanContext`. Best-effort: returns `None` when no
/// session is active, no manifest exists, or no plan was attached.
/// trace:TASK-391 | ai:claude
fn locate_plan_for_active_session(project_root: &std::path::Path) -> Option<String> {
    let cwd = std::env::current_dir().ok()?;
    let lease = active_lease_for_cwd(project_root, &cwd)?;
    let path = session_manifest::manifest_path(project_root, &lease.id);
    let manifest = session_manifest::load(&path).ok()?;
    manifest.plan.map(|p| p.plan_file)
}

/// `aida zen status` — print the corroborated zen context of the current
/// process. The bare status word (`zen` / `interactive`) goes to stdout so a
/// skill can branch on it cleanly; any informational note goes to stderr.
/// trace:BUG-237 | ai:claude
fn handle_zen_command(cmd: &ZenCommand) -> Result<()> {
    match cmd {
        ZenCommand::Status { json } => {
            // Resolve the shared `.aida/` root from any worktree so a child in
            // a sibling worktree reads the orchestrator's marker dir and the
            // canonical lease set. On a resolution failure the lookups simply
            // find nothing — the verdict fails safe to interactive.
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let cwd = std::env::current_dir().unwrap_or_else(|_| project_root.clone());
            let ctx = zen::detect(&project_root, &cwd);
            if *json {
                println!(
                    "{{\"context\":\"{}\",\"corroborated\":{},\"reason\":\"{}\"}}",
                    ctx.status_word(),
                    ctx.is_zen(),
                    ctx.reason_slug()
                );
            } else {
                println!("{}", ctx.status_word());
            }
            // The note is informational. For the no-provenance case it names
            // a real stale value and suggests `unset AIDA_ZEN`.
            if let Some(note) = ctx.informational_note() {
                eprintln!(
                    "  {} {}",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                    note.dimmed()
                );
            }
            Ok(())
        }
        // STORY-564: the clean-vs-human-needed finish decision for the
        // standalone `--zen` lane. The `/aida-pr` checkpoint branches off
        // the bare decision word: `auto-exit` → run `aida session end` and
        // exit; `pause` → render the grab-next/stop table. trace:STORY-564
        ZenCommand::Finish { json } => {
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let cwd = std::env::current_dir().unwrap_or_else(|_| project_root.clone());
            let is_zen = zen::detect(&project_root, &cwd).is_zen();
            let lease = active_lease_for_cwd(&project_root, &cwd);
            // Marker: the session flagged itself human-needed (paused on a
            // design-fork / raised a punt) via `aida zen needs-human`.
            let needs_human_marked = lease
                .as_ref()
                .map(|l| zen::has_needs_human_marker(&project_root, &l.id))
                .unwrap_or(false);
            // Punt: a substrate record of a human-needed fork raised during
            // this session — scoped to the lease's spec + start time so a
            // sibling session's punt sharing the ledger doesn't leak in.
            let has_open_punt = lease
                .as_ref()
                .map(|l| {
                    let spec = l.scope.trim().to_ascii_uppercase();
                    punt::read_ledger(&project_root)
                        .iter()
                        .any(|r| r.timestamp >= l.started_at && r.spec.to_ascii_uppercase() == spec)
                })
                .unwrap_or(false);
            let pause_always = zen_pause_always_in_force(&project_root);
            let presence_bias = if presence::read_presence_file().is_some() {
                match presence::current_presence(chrono::Utc::now()) {
                    presence::Presence::Away => zen::FinishPresence::Away,
                    presence::Presence::Home => zen::FinishPresence::Home,
                }
            } else {
                zen::FinishPresence::NoOpinion
            };
            let verdict = zen::classify_finish(
                is_zen,
                needs_human_marked,
                has_open_punt,
                pause_always,
                presence_bias,
            );
            if *json {
                println!(
                    "{{\"decision\":\"{}\",\"reason\":\"{}\",\"corroborated\":{}}}",
                    verdict.decision_word(),
                    verdict.reason_slug(),
                    is_zen
                );
            } else {
                println!("{}", verdict.decision_word());
            }
            // STORY-569: on a CLEAN finish — auto-exit, or a pause only
            // because the operator elected `--pause-always` — hand the
            // just-opened PR to the advisor through the agent mailbox.
            // This lives in the gate (not skill text) so the finish
            // sequence is finish → PR → review brief → exit by
            // construction, and the build→review handoff never falls back
            // to an operator relay. A needs-human / punt pause skips: the
            // operator is actively in the loop and the PR may still
            // change. Fail-open: a notify failure must never block the
            // finish decision. trace:STORY-569 | ai:claude
            let clean_finish = matches!(
                verdict,
                zen::ZenFinish::AutoExit | zen::ZenFinish::Pause(zen::FinishPause::PauseAlways)
            );
            if clean_finish {
                if let Some(l) = lease.as_ref() {
                    match file_zen_review_brief(&project_root, l) {
                        Ok(Some((agent, path))) => eprintln!(
                            "  {} review brief filed to the {} mailbox: {}",
                            crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                            agent.cyan(),
                            path.display()
                        ),
                        Ok(None) => {}
                        Err(e) => eprintln!(
                            "  {} could not file the review brief ({e}) — \
                             hand the PR to your reviewer manually",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                        ),
                    }
                }
            }
            Ok(())
        }
        // STORY-564: record that this `--zen` session needed a human. Keyed
        // to the session lease so concurrent zen sessions don't collide.
        ZenCommand::NeedsHuman { reason } => {
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let cwd = std::env::current_dir().unwrap_or_else(|_| project_root.clone());
            match active_lease_for_cwd(&project_root, &cwd) {
                Some(lease) => {
                    zen::mark_needs_human(&project_root, &lease.id, reason)?;
                    println!(
                        "{} marked this --zen session human-needed — the finish checkpoint will pause",
                        crate::glyph(crate::glyphs::Glyph::Check).green()
                    );
                    Ok(())
                }
                None => {
                    // No lease over this cwd: nothing to scope the marker to.
                    // Don't fail — just tell the operator the gate can't see it.
                    eprintln!(
                        "  {} no active session lease covers this directory — `aida zen finish` \
                         keys the needs-human marker off the lease, so there is nothing to mark",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                    );
                    Ok(())
                }
            }
        }
    }
}

/// `aida drain status` — show the active `aida queue work --auto-complete`
/// drain (STORY-301). Reads `.aida/drain-state.json`, corroborates the recorded
/// orchestrator PID against a liveness probe, and prints the human summary —
/// or `No drain in progress.` (exit 0) when no drain is running. `--clear`
/// removes a stale file left by a crashed orchestrator. trace:STORY-301
// BUG-759: launcher-held drains (`aida burndown run`, `aida queue integrate`)
// hold `.aida/drain.lock` for their entire wall-clock but write no drain-state
// file, so the state-file read alone said "No drain in progress" mid-burndown.
// When the state file is absent (or a stale tombstone) and the lock's pid is
// LIVE, report the drain from the lock instead. trace:BUG-759 | ai:claude
fn handle_drain_command(cmd: &DrainCommand) -> Result<()> {
    match cmd {
        DrainCommand::Status { json, clear } => {
            // Resolve the shared `.aida/` root from any worktree so a child in
            // a sibling worktree reads the *orchestrator's* drain-state file.
            // On a resolution failure the lookup simply finds nothing — the
            // verdict fails safe to "no drain".
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let status = drain_state::probe(&project_root);
            if *clear {
                return drain_clear(&project_root, &status, *json);
            }
            // BUG-759: corroborate the launcher-held drain lock alongside the
            // orchestrator drain-state file. A live lock is authoritative when
            // the state file can't speak for the drain (absent, or a dead-pid
            // tombstone a killed orchestrator left behind).
            let live_lock = match drain_lock::probe_lock(&project_root) {
                drain_lock::LockStatus::Running(lock) => Some(lock),
                _ => None,
            };
            if let (
                drain_state::DrainStatus::None | drain_state::DrainStatus::Stale(_),
                Some(lock),
            ) = (&status, &live_lock)
            {
                let stale_state = matches!(status, drain_state::DrainStatus::Stale(_));
                if *json {
                    println!("{}", drain_state::render_lock_json(lock, stale_state));
                } else {
                    print!("{}", drain_state::render_lock_human(lock, stale_state));
                    // TASK-294 parity with the state-backed report: surface any
                    // pending worker directives alongside the drain summary.
                    let directives =
                        worker::parse_directives(&worker::worker_cmd_path(&project_root));
                    if let Some(line) = worker::status_line(&directives) {
                        println!();
                        println!("  {line}");
                    }
                }
                return Ok(());
            }
            if *json {
                println!("{}", drain_state::render_json(&status));
                return Ok(());
            }
            match status {
                drain_state::DrainStatus::None => {
                    println!("No drain in progress.");
                }
                drain_state::DrainStatus::Active(state) => {
                    print!("{}", drain_state::render_human(&state, false));
                }
                drain_state::DrainStatus::Stale(state) => {
                    print!("{}", drain_state::render_human(&state, true));
                }
            }
            // TASK-294: equal visibility for the worker control channel —
            // the directive FIFO surfaces here alongside the drain summary
            // so a user sees both at once. Silent when no directives are
            // pending so quiet projects stay quiet.
            let directives = worker::parse_directives(&worker::worker_cmd_path(&project_root));
            if let Some(line) = worker::status_line(&directives) {
                println!();
                println!("  {line}");
            }
            Ok(())
        }
    }
}

/// `aida stack {show,list}` (STORY-248). Reads `.aida/stacks.json` —
/// no requirement-store dependency, so dispatches pre-storage like
/// `aida drain status`. Prints "No stacked branches." (exit 0) on an
/// empty graph so a quiet project never errors. `--prune-stale` (show
/// only) drops entries whose branch no longer exists locally or on
/// origin; the prune writes the graph back atomically.
/// trace:STORY-248 | ai:claude
fn handle_stack_command(cmd: &StackCommand) -> Result<()> {
    let project_root = find_main_worktree_root()
        .or_else(|_| std::env::current_dir())
        .unwrap_or_else(|_| std::path::PathBuf::from("."));
    let mut graph = stacks::load(&project_root);

    match cmd {
        StackCommand::Show { json, prune_stale } => {
            if *prune_stale {
                let stale: Vec<String> = graph
                    .entries
                    .values()
                    .filter(|e| !branch_exists_anywhere(&project_root, &e.branch))
                    .map(|e| e.branch.clone())
                    .collect();
                if !stale.is_empty() {
                    for s in &stale {
                        stacks::remove(&mut graph, s);
                    }
                    stacks::save(&project_root, &graph)?;
                    if !*json {
                        eprintln!(
                            "  {} pruned {} stale entr{}",
                            crate::glyph(crate::glyphs::Glyph::Check).green(),
                            stale.len(),
                            if stale.len() == 1 { "y" } else { "ies" }
                        );
                    }
                }
            }
            if *json {
                let chains: Vec<Vec<&stacks::StackEntry>> = stacks::chains(&graph);
                println!(
                    "{}",
                    serde_json::to_string_pretty(&serde_json::json!({ "chains": chains }))?
                );
                return Ok(());
            }
            if graph.is_empty() {
                println!("No stacked branches.");
                return Ok(());
            }
            for chain in stacks::chains(&graph) {
                // Root parent of the chain is the first entry's parent —
                // typically `main`, sometimes a since-merged branch.
                if let Some(first) = chain.first() {
                    println!("{}", first.parent_branch.dimmed());
                }
                for (depth, entry) in chain.iter().enumerate() {
                    let indent = "  ".repeat(depth + 1);
                    let spec = entry
                        .spec_id
                        .as_deref()
                        .map(|s| format!(" {}", format!("({})", s).dimmed()))
                        .unwrap_or_default();
                    println!("{}└─ {}{}", indent, entry.branch.cyan(), spec);
                }
            }
            Ok(())
        }
        StackCommand::List { json } => {
            let chains = stacks::chains(&graph);
            if *json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&serde_json::json!({ "chains": chains }))?
                );
                return Ok(());
            }
            if chains.is_empty() {
                println!("No stacked branches.");
                return Ok(());
            }
            for chain in chains {
                let root = chain
                    .first()
                    .map(|e| e.parent_branch.as_str())
                    .unwrap_or("main");
                let rest: Vec<&str> = chain.iter().map(|e| e.branch.as_str()).collect();
                println!("{} → {}", root.dimmed(), rest.join(" → ").cyan());
            }
            Ok(())
        }
    }
}

/// `aida headless tail` — clean tailer for `.aida/headless-logs/<spec>-<lease>.jsonl`
/// (TASK-398). Wraps the right JSONL filtering so the user doesn't have to
/// remember (and debug) the non-obvious jq pipeline that picks text content
/// out of multi-block assistant messages. trace:TASK-398
fn handle_headless_command(cmd: &HeadlessCommand) -> Result<()> {
    match cmd {
        HeadlessCommand::Tail {
            target,
            list,
            with_tools,
            tools_only,
            include_user,
            no_follow,
            since,
        } => {
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let since_duration = match since {
                Some(s) => Some(headless_tail::parse_since(s)?),
                None => None,
            };
            let color = std::io::IsTerminal::is_terminal(&std::io::stdout())
                && std::env::var_os("NO_COLOR").is_none();
            let opts = headless_tail::TailOptions {
                selector: target.clone(),
                list: *list,
                with_tools: *with_tools,
                tools_only: *tools_only,
                include_user: *include_user,
                follow: !*no_follow,
                since: since_duration,
                color,
            };
            headless_tail::handle_tail(&project_root, &opts)
        }
    }
}

/// `aida worker directives` — list the FIFO of pending directives the
/// `aida-worker` shell function will act on next (TASK-294). Reads
/// `.aida/worker.cmd` only — no requirement-store dependency, so it
/// dispatches pre-storage like `aida drain status`. Prints "No pending
/// directives." (exit 0) when the file is empty or absent so a quiet
/// project never errors. trace:TASK-294 | ai:claude
///
/// `aida worker gc` prunes stale drain orders — spec-targeted drain lines
/// whose target spec is already archived / Completed / Rejected. The worker
/// dispatch stays pre-storage; the gc arm opens the cache-backed backend
/// itself to resolve target-spec statuses.
// trace:BUG-723 | ai:claude
fn handle_worker_command(cmd: &WorkerCommand) -> Result<()> {
    match cmd {
        WorkerCommand::Directives { json } => {
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let path = worker::worker_cmd_path(&project_root);
            let directives = worker::parse_directives(&path);
            if *json {
                println!("{}", worker::render_json(&directives));
                return Ok(());
            }
            if directives.is_empty() {
                println!("No pending directives.");
            } else {
                print!("{}", worker::render_human(&directives));
            }
            Ok(())
        }
        // trace:BUG-723 | ai:claude
        WorkerCommand::Gc { dry_run } => {
            let project_root = find_main_worktree_root()
                .or_else(|_| std::env::current_dir())
                .unwrap_or_else(|_| std::path::PathBuf::from("."));
            let path = worker::worker_cmd_path(&project_root);
            let body = std::fs::read_to_string(&path).unwrap_or_default();
            if worker::parse_directives_from_str(&body).is_empty() {
                println!("No pending directives.");
                return Ok(());
            }
            let store_path = detect_distributed_store_from(&project_root).ok_or_else(|| {
                anyhow::anyhow!(
                    "no requirement store found — cannot resolve directive target specs"
                )
            })?;
            let backend = advance_backend(&store_path)?;
            // Both view axes wide open: an archived (or deferred) target must
            // still resolve so its directive is classified correctly.
            let summaries = backend.list_summaries(&aida_core::ListFilter {
                archive: aida_core::ArchiveFilter::Both,
                defer: aida_core::DeferFilter::Both,
                ..Default::default()
            })?;
            // Dead = the spec still exists AND is archived or terminal
            // (Completed / Rejected) — same predicate as the queue's GC. A
            // directive targeting an unknown spec is LEFT alone (fail-safe:
            // no store row means no evidence the work shipped).
            let mut dead_ids = std::collections::HashSet::new();
            for s in &summaries {
                if s.archived || is_terminal_status_str(&s.status) {
                    for id in [s.spec_id.as_deref(), s.agreed_id.as_deref()]
                        .into_iter()
                        .flatten()
                    {
                        dead_ids.insert(id.to_ascii_uppercase());
                    }
                }
            }
            let is_dead = |spec: &str| dead_ids.contains(&spec.to_ascii_uppercase());
            let outcome = worker::gc_directives_body(&body, &is_dead);
            if outcome.pruned.is_empty() {
                println!("No stale directives to prune.");
                return Ok(());
            }
            println!(
                "{} stale directive{} (target spec archived / Completed / Rejected):",
                outcome.pruned.len(),
                if outcome.pruned.len() == 1 { "" } else { "s" }
            );
            for d in &outcome.pruned {
                println!("  - {}", d.raw);
            }
            if *dry_run {
                println!("Dry run — file unchanged.");
                return Ok(());
            }
            std::fs::write(&path, &outcome.kept_body)?;
            let remaining = worker::parse_directives_from_str(&outcome.kept_body).len();
            println!(
                "Pruned {} directive{}; {} remain{}.",
                outcome.pruned.len(),
                if outcome.pruned.len() == 1 { "" } else { "s" },
                remaining,
                if remaining == 1 { "s" } else { "" }
            );
            Ok(())
        }
    }
}

/// `aida drain status --clear` — remove a stale drain-state file. Refuses
/// while the orchestrator is still live: a live orchestrator removes the file
/// itself on a clean exit, so clearing it from under a running drain would
/// only hide work in progress. trace:STORY-301 | ai:claude
fn drain_clear(
    project_root: &std::path::Path,
    status: &drain_state::DrainStatus,
    json: bool,
) -> Result<()> {
    match status {
        drain_state::DrainStatus::None => {
            if json {
                println!("{{\"status\":\"none\"}}");
            } else {
                println!("No drain-state file to clear.");
            }
            Ok(())
        }
        drain_state::DrainStatus::Active(state) => anyhow::bail!(
            "the drain is still live (orchestrator pid {}) — not clearing. \
             The drain-state file is removed automatically when the \
             orchestrator exits.",
            state.orchestrator_pid
        ),
        drain_state::DrainStatus::Stale(_) => {
            drain_state::DrainState::clear(project_root)?;
            if json {
                println!("{{\"status\":\"cleared\"}}");
            } else {
                println!(
                    "{} removed the stale drain-state file",
                    crate::glyph(crate::glyphs::Glyph::Check).green().bold()
                );
            }
            Ok(())
        }
    }
}

/// TASK-306: the decision the `--no-human` kickoff gate makes — split from
/// its terminal/stdin I/O so it is unit-testable. `acknowledged` is whether
/// `AIDA_NO_HUMAN_ACKNOWLEDGED=1` is set. STORY-276 dropped `BothUnavailable`
/// — the headless implementer now ships, so `both` is a real, acknowledgeable
/// mode like `reviewer-only`; the gate keys purely off acknowledgement.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NoHumanGate {
    /// Already acknowledged via the env var — proceed with a one-line scope
    /// reminder, no prompt.
    Acknowledged,
    /// Not yet acknowledged — show the scope banner and ask.
    NeedsAck,
}

/// TASK-306 / STORY-276: pure classification for [`no_human_kickoff_gate`].
/// The decision no longer depends on the mode (both modes ship) — only on
/// whether the scope was acknowledged. The *banner wording* still varies by
/// mode; that lives in [`no_human_kickoff_gate`].
fn classify_no_human_gate(acknowledged: bool) -> NoHumanGate {
    if acknowledged {
        NoHumanGate::Acknowledged
    } else {
        NoHumanGate::NeedsAck
    }
}

/// STORY-276: the one-line scope description for a `--no-human` mode — used in
/// the acknowledged-path reminder and as the lead line of the ack banner.
fn no_human_scope_line(mode: auto_complete::NoHumanMode) -> &'static str {
    if mode.wants_headless_implementer() {
        "--no-human=both: the implementer AND reviewer phases run headless — \
         no human at the keyboard. On a design-fork it cannot safely resolve, \
         the implementer punts the spec to Needs Attention instead of guessing."
    } else {
        "--no-human: the reviewer phase runs headless; the implementer phase \
         stays interactive and will pause for you."
    }
}

/// BUG-740: fail fast when an auto-complete drive would launch an interactive
/// implementer from a non-TTY context. The failure used to happen much later,
/// after queue/store/lease/worktree setup, when the child vendor CLI finally
/// reported "stdin is not a terminal". `--no-human=both` is the explicit
/// headless implementer mode; `AIDA_HEADLESS=1` is accepted as the environment
/// opt-in used by agent shells.
// trace:BUG-740 | ai:codex
fn non_tty_interactive_implementer_preflight(
    no_human: Option<auto_complete::NoHumanMode>,
    stdin_is_tty: bool,
    stdout_is_tty: bool,
    aida_headless: bool,
) -> Result<Option<auto_complete::NoHumanMode>> {
    let implementer_is_headless = no_human
        .map(auto_complete::NoHumanMode::wants_headless_implementer)
        .unwrap_or(false);
    if implementer_is_headless || (stdin_is_tty && stdout_is_tty) {
        return Ok(no_human);
    }
    if aida_headless {
        return Ok(Some(auto_complete::NoHumanMode::Both));
    }
    anyhow::bail!(
        "aida do needs a terminal for the interactive implementer — run it from \
         your shell, or add --no-human=both for a headless implementer. \
         (`aida queue work --auto-complete` has the same requirement.)"
    );
}

/// TASK-306: the pre-launch gate for `aida queue work --auto-complete
/// --no-human`, run once per kickoff. It prints a loud scope banner — what
/// runs unattended and what does not — and requires a one-time
/// acknowledgement, either interactively or up front with
/// `AIDA_NO_HUMAN_ACKNOWLEDGED=1` for an unattended run. STORY-276: `both` is
/// now a shipped mode, so it is acknowledged like `reviewer-only` rather than
/// rejected; the banner wording differs by mode. trace:TASK-306, STORY-276
/// TASK-394: machine-wide `--no-human` acknowledgement marker
/// (`~/.aida/no-human-acknowledged`) — persists across every project on the host.
fn no_human_machine_marker() -> Option<std::path::PathBuf> {
    dirs::home_dir().map(|h| h.join(".aida").join("no-human-acknowledged"))
}

/// TASK-394: project-scoped marker (`.aida/no-human-acknowledged`) — fresh per
/// project, so the safety prompt returns on a new clone unless re-acked.
fn no_human_project_marker() -> std::path::PathBuf {
    std::path::Path::new(".aida").join("no-human-acknowledged")
}

/// TASK-394: is `--no-human` acknowledged via any channel? Returns the source
/// label for the reminder line. Checked order: env var (existing path) → machine
/// marker → project marker. An overnight loop acks once (the marker) instead of
/// re-exporting the env var per iteration. trace:TASK-394 | ai:claude
fn no_human_ack_source() -> Option<&'static str> {
    if std::env::var("AIDA_NO_HUMAN_ACKNOWLEDGED")
        .map(|v| v == "1")
        .unwrap_or(false)
    {
        return Some("AIDA_NO_HUMAN_ACKNOWLEDGED");
    }
    if no_human_machine_marker()
        .map(|p| p.exists())
        .unwrap_or(false)
    {
        return Some("~/.aida/no-human-acknowledged");
    }
    if no_human_project_marker().exists() {
        return Some(".aida/no-human-acknowledged");
    }
    None
}

/// TASK-394: `aida no-human acknowledge|revoke|status` — manage the persistent
/// `--no-human` scope-acknowledgement marker so an unattended loop acks once
/// rather than re-exporting AIDA_NO_HUMAN_ACKNOWLEDGED per iteration.
/// trace:TASK-394 | ai:claude
fn handle_no_human_command(cmd: &cli::NoHumanCommand) -> Result<()> {
    let marker_for = |project: bool| -> Result<std::path::PathBuf> {
        if project {
            Ok(no_human_project_marker())
        } else {
            no_human_machine_marker()
                .ok_or_else(|| anyhow::anyhow!("could not resolve home directory for the marker"))
        }
    };
    match cmd {
        cli::NoHumanCommand::Acknowledge { project } => {
            let path = marker_for(*project)?;
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(&path, "acknowledged\n")
                .with_context(|| format!("writing {}", path.display()))?;
            let scope = if *project {
                "this project"
            } else {
                "this machine"
            };
            println!(
                "{} --no-human acknowledged for {} ({}). Future drains skip the scope prompt.",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                scope,
                path.display()
            );
            if *project {
                println!(
                    "  {}",
                    "Note: .aida/no-human-acknowledged is gitignored runtime state (per-clone)."
                        .dimmed()
                );
            }
            Ok(())
        }
        cli::NoHumanCommand::Revoke { project } => {
            let path = marker_for(*project)?;
            if path.exists() {
                std::fs::remove_file(&path)
                    .with_context(|| format!("removing {}", path.display()))?;
                println!(
                    "{} revoked {} — the scope prompt will return.",
                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                    path.display()
                );
            } else {
                println!("(no acknowledgement marker at {})", path.display());
            }
            Ok(())
        }
        cli::NoHumanCommand::Status => {
            match no_human_ack_source() {
                Some(src) => println!(
                    "{} --no-human is acknowledged (via {}).",
                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                    src
                ),
                None => println!(
                    "{} --no-human is NOT acknowledged — the scope prompt will fire. \
                     Run `aida no-human acknowledge` to persist it.",
                    "○".dimmed()
                ),
            }
            Ok(())
        }
    }
}

fn no_human_kickoff_gate(mode: auto_complete::NoHumanMode) -> Result<()> {
    let ack_source = no_human_ack_source();
    let both = mode.wants_headless_implementer();
    match classify_no_human_gate(ack_source.is_some()) {
        NoHumanGate::Acknowledged => {
            eprintln!(
                "  {} {} (acknowledged via {})",
                crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                no_human_scope_line(mode),
                ack_source.unwrap_or("acknowledgement"),
            );
            Ok(())
        }
        NoHumanGate::NeedsAck => {
            eprintln!();
            if both {
                eprintln!(
                    "{}  --no-human=both runs the implementer AND reviewer phases \
                     headless.",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                );
                eprintln!("   No human is at the keyboard during phase 1 (implementer).");
                eprintln!(
                    "   On a design-fork it cannot safely resolve, the implementer \
                     punts the spec"
                );
                eprintln!(
                    "   to Needs Attention instead of guessing — review punts later \
                     with `aida findings list`."
                );
            } else {
                eprintln!(
                    "{}  --no-human covers the reviewer phase only.",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                );
                eprintln!("   Phase 1 (implementer) still requires interactive input.");
                eprintln!("   The drain will pause at each phase-1 completion until you act.");
                eprintln!(
                    "   {}",
                    "For a fully headless drain use `--no-human=both`.".dimmed()
                );
            }
            eprintln!(
                "   {}",
                "Set AIDA_NO_HUMAN_ACKNOWLEDGED=1 to skip this prompt on an \
                 unattended run,"
                    .dimmed()
            );
            // BUG-703: keep the SPEC-ID out of this user-facing warning — a
            // trace marker in stderr is developer noise to a first-user.
            // trace:TASK-394 | ai:claude
            eprintln!(
                "   {}",
                "or `aida no-human acknowledge` once to persist it across runs \
                 (per machine; --project to scope to this repo)."
                    .dimmed()
            );
            eprintln!();
            // `--no-human` is meant for unattended drains, so a non-terminal
            // stdin is the expected unattended case — but it cannot answer a
            // prompt. Fail loud with the env-var escape rather than blocking
            // forever on a stdin read. trace:TASK-306 | ai:claude
            if !std::io::IsTerminal::is_terminal(&std::io::stdin()) {
                anyhow::bail!(
                    "--no-human needs a one-time scope acknowledgement, but stdin \
                     is not a terminal. Re-run with AIDA_NO_HUMAN_ACKNOWLEDGED=1 to \
                     confirm you understand its scope."
                );
            }
            if !prompt_yes_no("   Continue? [y/N] ", false)? {
                anyhow::bail!("aborted — --no-human scope not acknowledged");
            }
            Ok(())
        }
    }
}

/// STORY-492: clamp a reconciled resume phase to one a *fresh* resume process
/// can actually run. Phases 1-2 are coupled to the implementer session/lease,
/// which a restarted process does not hold: phase 1 (branch absent) re-runs the
/// whole drain cleanly, but a reconciled CI(2) — implementer done, CI
/// postcondition unmet — is bumped to the reviewer (phase 3), because the
/// lease-coupled CI-end step cannot be replayed and the reviewer + merge phases
/// re-establish gating (`gh pr merge` still respects required checks). Pure so
/// the safety clamp is unit-pinned. trace:STORY-492 | ai:claude
fn clamp_resume_start_phase(reconciled: auto_complete::Phase) -> auto_complete::Phase {
    if reconciled == auto_complete::Phase::Ci {
        auto_complete::Phase::Reviewer
    } else {
        reconciled
    }
}

/// BUG-478: does the requirement for `spec` carry a `failure_reason` — the TRUE
/// "deliberately shelved" signal? The shelve function (`finish_failure`) sets
/// `req.failure_reason` (+ usually `NeedsAttention`) on a shelvable phase
/// failure; the drain-state member's `STATE_FAILED` is stamped on ANY non-zero
/// outcome and so cannot distinguish a deliberate shelve from a non-shelve
/// resume failure. Resolves spec→requirement the same way `probe_resume_facts`
/// resolves `spec_completed` (matching `spec_id` OR `agreed_id`) so agreed/raw
/// ids behave identically. Returns `false` when the store can't be loaded or the
/// requirement isn't found — a missing req must not wedge resume into the
/// LeaveShelved branch. trace:BUG-478 | ai:claude
fn requirement_has_failure_reason(storage: &Storage, spec: &str) -> bool {
    storage
        .load()
        .ok()
        .and_then(|store| {
            store
                .requirements
                .iter()
                .find(|r| {
                    r.spec_id.as_deref() == Some(spec) || r.agreed_id.as_deref() == Some(spec)
                })
                .map(|r| r.failure_reason.is_some())
        })
        .unwrap_or(false)
}

/// STORY-492 (slice 2c): probe the real world for a crashed drain member's
/// per-phase postconditions, returning the [`drain_resume::ResumeFacts`] plus
/// the branch + PR the re-entry must seed into the driver.
///
/// Conservative by design: a postcondition we cannot confirm stays `false`
/// (re-run that phase). Re-running an already-merged `merge()` is redeemed by
/// the BUG-241 reconcile, and CI / reviewer / build are idempotent — so the
/// only postconditions that MUST be accurate are the ones gating the
/// irreversible tail: `pr_merged` (don't re-merge) and `spec_completed` (don't
/// re-pull). trace:STORY-492 | ai:claude
fn probe_resume_facts(
    project_root: &std::path::Path,
    storage: &Storage,
    spec: &str,
    member: Option<&drain_state::DrainMember>,
) -> (drain_resume::ResumeFacts, Option<String>, Option<u32>) {
    let mut sink = network_retry::StderrSink;

    // PR number: prefer what drain-state recorded; else look it up by spec.
    let mut pr = member.and_then(|m| m.pr);
    if pr.is_none() {
        if let PrLookup::Found(p) = detect_open_pr_for_spec_via_forge(project_root, spec) {
            pr = Some(p.number as u32);
        }
    }
    // The PR's head branch (the merge / CI phases probe against it).
    let branch = pr.and_then(|n| pr_head_branch(project_root, n as u64));

    // pr_merged — ACCURATE (gates skipping the irreversible merge).
    let pr_merged = pr
        .and_then(|n| pr_is_merged_with_sink(project_root, n, &mut sink))
        .unwrap_or(false);

    // branch_exists — a PR (open or merged) exists, or the branch is on origin.
    let branch_exists = pr.is_some()
        || branch
            .as_deref()
            .map(|b| {
                matches!(
                    probe_branch_on_origin(project_root, b),
                    BranchOriginProbe::Present
                )
            })
            .unwrap_or(false);

    // ci_green — a point-in-time CI probe; a merged PR implies CI cleared.
    let ci_green = pr_merged
        || branch
            .as_deref()
            .map(|b| matches!(ci_probe_via_forge(b), CiProbe::Green { .. })) // STORY-516
            .unwrap_or(false);

    // reviewed — an Approved verdict file exists for the PR.
    let reviewed = pr
        .map(|n| {
            let path = project_root
                .join(".aida")
                .join("review-verdicts")
                .join(format!("PR-{n}.json"));
            matches!(
                read_verdict_file(&path),
                Ok(auto_complete::ReviewerOutcome::Verdict(
                    auto_complete::Verdict::Approved
                ))
            )
        })
        .unwrap_or(false);

    // spec_completed — ACCURATE (gates skipping the pull/auto-bump).
    let spec_completed = storage
        .load()
        .ok()
        .and_then(|store| {
            store
                .requirements
                .iter()
                .find(|r| {
                    r.spec_id.as_deref() == Some(spec) || r.agreed_id.as_deref() == Some(spec)
                })
                .map(|r| r.status == RequirementStatus::Completed)
        })
        .unwrap_or(false);

    let facts = drain_resume::ResumeFacts {
        branch_exists,
        ci_green,
        reviewed,
        pr_merged,
        // Build is idempotent — always re-run on resume (plan note).
        build_ok: false,
        spec_completed,
    };
    (facts, branch, pr)
}

/// STORY-492 (slice 2d): the `--resume-drain` entry point. Reads the
/// crashed-drain state, runs the PID-liveness gate (refuse if the original
/// orchestrator is still alive — the catastrophic double-drive guard),
/// reconciles the re-entry phase from probed git/PR/spec reality, prints the
/// decision, and — unless `--dry-run` — re-enters the current member at the
/// reconciled phase. Never returns. trace:STORY-492 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_drain_resume(
    storage: &Storage,
    user_id: &str,
    drain_id: Option<&str>,
    dry_run: bool,
    json: bool,
    permission_mode: Option<&str>,
    no_human: Option<auto_complete::NoHumanMode>,
    escalate_mode: auto_complete::EscalateMode,
    steal: bool,
    force_claim: bool,
    allow_stale_base: bool,
    no_auto_rebase: bool,
) -> ! {
    let project_root = match storage.path().parent() {
        Some(p) => p.to_path_buf(),
        None => {
            eprintln!(
                "{} cannot derive project root from the store path",
                crate::glyph(crate::glyphs::Glyph::Cross)
            );
            std::process::exit(1);
        }
    };
    let Some(state) = drain_state::DrainState::read(&project_root) else {
        eprintln!(
            "{} no `.aida/drain-state.json` — there is no crashed drain to resume.",
            crate::glyph(crate::glyphs::Glyph::Cross).red().bold()
        );
        eprintln!(
            "  {} a clean drain removes its state file on exit; only a crashed/killed \
             drain leaves one behind.",
            "→".dimmed()
        );
        std::process::exit(1);
    };

    // Optional `--drain-id` corroboration — match the run UUID or the start
    // timestamp so a stale state file isn't resumed by mistake.
    if let Some(id) = drain_id {
        let matches = state.run_uuid == id || state.started_at.starts_with(id);
        if !matches {
            eprintln!(
                "{} --drain-id `{}` does not match the recorded drain (run `{}`, started {}).",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                id,
                state.run_uuid,
                state.started_at
            );
            std::process::exit(1);
        }
    }

    // PID-liveness gate — the catastrophic double-drive guard. Conservative:
    // any doubt resolves to "alive". trace:STORY-492 | ai:claude
    let orchestrator_alive = process_probe::pid_is_alive(state.orchestrator_pid);

    let current = state.current.clone();
    let member = current
        .as_ref()
        .and_then(|c| state.members.iter().find(|m| &m.spec == c))
        .cloned();
    let member_in_flight = current.is_some();
    let member_state_in_phase = member
        .as_ref()
        .map(|m| m.state.starts_with("in-phase-"))
        .unwrap_or(false);
    // BUG-478: the "deliberately shelved" signal lives on the REQUIREMENT
    // (`failure_reason`, set by the shelve function), NOT on the drain-state
    // member. The member is stamped STATE_FAILED on ANY non-zero outcome —
    // including a non-shelve resume failure (spawn / internal error) — so
    // keying `has_failure_reason` off `member.state == STATE_FAILED` conflated
    // "failed resume" with "deliberately shelved", wedging a re-resumable crash
    // into the LeaveShelved branch. Read the requirement's `failure_reason`
    // instead: a genuinely shelved spec still has it set (→ Shelved), but a
    // non-shelve resume failure leaves it None (→ ResumableCrash, restoring
    // BUG-438's keep-state-and-re-resume intent). A requirement we can't load
    // defaults to not-shelved (resumable) — a missing req must not wedge resume.
    // The spec→requirement resolution mirrors `probe_resume_facts`'s
    // spec_completed lookup so agreed/raw ids match identically.
    // trace:BUG-478 | ai:claude
    let has_failure_reason = current
        .as_deref()
        .map(|spec| requirement_has_failure_reason(storage, spec))
        .unwrap_or(false);

    // Probe the world for the current member's per-phase postconditions.
    let (facts, branch, pr) = match &current {
        Some(spec) => probe_resume_facts(&project_root, storage, spec, member.as_ref()),
        None => (drain_resume::ResumeFacts::default(), None, None),
    };

    let outcome = drain_resume::resume_plan(
        orchestrator_alive,
        member_in_flight,
        member_state_in_phase,
        has_failure_reason,
        &facts,
    );

    let spec_label = current.as_deref().unwrap_or("<none>");
    match outcome {
        drain_resume::ResumeOutcome::RefuseOrchestratorAlive => {
            eprintln!(
                "{} refusing to resume — the original orchestrator (pid {}) is still alive.",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                state.orchestrator_pid
            );
            eprintln!(
                "  {} resuming a live drain would DOUBLE-DRIVE the same spec (two processes \
                 merging the same PR). Stop the running drain first, then re-run --resume-drain.",
                "→".dimmed()
            );
            std::process::exit(1);
        }
        drain_resume::ResumeOutcome::NothingToResume => {
            println!(
                "{} nothing to resume — no member was mid-flight in `{}`.",
                crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                drain_state::drain_state_path(&project_root).display()
            );
            std::process::exit(0);
        }
        drain_resume::ResumeOutcome::LeaveShelved => {
            println!(
                "{} `{}` was deliberately shelved, not crashed — leave it parked and triage \
                 with `aida findings list` (don't resume).",
                crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                spec_label
            );
            std::process::exit(0);
        }
        drain_resume::ResumeOutcome::AlreadyComplete => {
            println!(
                "{} every phase of `{}` is already complete — clearing the stale drain-state.",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                spec_label
            );
            let _ = drain_state::DrainState::clear(&project_root);
            std::process::exit(0);
        }
        drain_resume::ResumeOutcome::ResumeAt(reconciled) => {
            // SAFETY clamp: phases 1-2 (implementer + CI-wait) are coupled to the
            // implementer session/lease, which a fresh resume process does not
            // hold. Phase 1 (branch absent) re-runs the whole drain cleanly. A
            // reconciled CI(2) means the implementer finished but CI's
            // postcondition is unmet — we cannot re-run the lease-coupled CI-end
            // step, so re-enter at the reviewer (phase 3); the reviewer + merge
            // re-establish gating and `gh pr merge` still respects required
            // checks. trace:STORY-492 | ai:claude
            let start_phase = clamp_resume_start_phase(reconciled);
            if reconciled != start_phase {
                println!(
                    "{} reconciled to phase {} (CI) — re-entering at phase {} (reviewer) instead \
                     (CI-wait is coupled to the implementer session a resume cannot hold).",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                    reconciled.index(),
                    start_phase.index()
                );
            }
            println!(
                "{} resuming `{}` at phase {} ({}) — earlier phases reconciled as already done.",
                "↩".cyan().bold(),
                spec_label,
                start_phase.index(),
                start_phase.slug()
            );
            if let Some(n) = pr {
                println!("  {} seeded PR-{}", "→".dimmed(), n);
            }
            if dry_run {
                println!(
                    "  {} --dry-run — not re-entering. Drop --dry-run to resume.",
                    "→".dimmed()
                );
                std::process::exit(0);
            }
            // Live re-entry: phase 1 means a from-scratch redo (no seed); any
            // later phase seeds the probed branch + PR.
            let spec = current.expect("ResumeAt implies a current member");
            let variant = auto_complete::AutoCompleteVariant::Full;
            let resume_entry = if start_phase == auto_complete::Phase::Implementer {
                None
            } else {
                Some(ResumeEntry {
                    start_phase,
                    branch,
                    pr,
                })
            };
            // BUG-438: when we re-enter past phase 1, the crashed implementer's
            // lease on this spec may still be held (a fast resume outruns the
            // mtime-based auto-release). Release it now — process-dead +
            // clean-worktree only — so the reviewer phase doesn't collide with
            // it (it resolves PR→spec and would otherwise hit "scope owned by
            // lease …"). trace:BUG-438 | ai:claude
            if resume_entry.is_some() {
                release_dead_leases_for_resume(&project_root, &spec);
            }
            let result = run_auto_complete(
                storage,
                user_id,
                &spec,
                variant,
                json,
                permission_mode,
                no_human,
                escalate_mode,
                // The resume owns the drain-state file (updates it, clears on a
                // clean finish).
                true,
                steal,
                force_claim,
                allow_stale_base,
                no_auto_rebase,
                resume_entry,
            );
            // TASK-1054: collapse the failed-phase index to the canonical
            // 0/2/3 process code so a wrapping script can branch on the outcome.
            std::process::exit(result.process_exit_code());
        }
    }
}

/// TASK-405: the `--from-pr` entry point — PR-only invocation. Implementation
/// shipped OUTSIDE the orchestrator (a PR is already open for `spec`), so drive
/// the remaining phases (reviewer → CI → merge → pull → build) WITHOUT
/// re-running the implementer. Probes the PR's real state, decides the entry
/// phase (or a clean refusal) via the pure [`drain_resume::from_pr_plan`], and
/// — unless `--dry-run` (the shared `--resume-dry-run` flag) — re-enters at that
/// phase via `run_auto_complete`'s resume-entry seam. Never returns.
///
/// Distinct from `handle_drain_resume`: there is no crashed drain-state file,
/// no PID-liveness gate (the implementer ran elsewhere, possibly by hand), and
/// the entry phase is computed straight from probed PR/spec reality.
/// trace:TASK-405 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_from_pr(
    storage: &Storage,
    user_id: &str,
    spec: &str,
    variant: auto_complete::AutoCompleteVariant,
    dry_run: bool,
    json: bool,
    permission_mode: Option<&str>,
    no_human: Option<auto_complete::NoHumanMode>,
    escalate_mode: auto_complete::EscalateMode,
    steal: bool,
    force_claim: bool,
    allow_stale_base: bool,
    no_auto_rebase: bool,
) -> ! {
    let project_root = match storage.path().parent() {
        Some(p) => p.to_path_buf(),
        None => {
            eprintln!(
                "{} cannot derive project root from the store path",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold()
            );
            std::process::exit(1);
        }
    };

    // Probe the world for this spec's PR + per-phase postconditions. Passing
    // `member: None` is exactly the standalone-PR case `probe_resume_facts`
    // already handles (it falls back to a forge lookup by spec when drain-state
    // recorded no PR). trace:TASK-405 | ai:claude
    let (facts, branch, pr) = probe_resume_facts(&project_root, storage, spec, None);
    let pr_exists = pr.is_some();

    match drain_resume::from_pr_plan(pr_exists, &facts) {
        drain_resume::FromPrOutcome::RefuseAlreadyCompleted => {
            eprintln!(
                "{} `{}` is already Completed — the merge already promoted it; nothing to drive.",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                spec
            );
            eprintln!(
                "  {} `--from-pr` engages the orchestrator on an OPEN PR — there is no open work here.",
                "→".dimmed()
            );
            std::process::exit(1);
        }
        drain_resume::FromPrOutcome::RefuseNoPr => {
            eprintln!(
                "{} no open PR found for `{}` — nothing to drive with `--from-pr`.",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                spec
            );
            eprintln!(
                "  {} `--from-pr` drives phases 3-6 on a PR shipped outside the orchestrator. \
                 To run the FULL pipeline (implementer first) drop `--from-pr`.",
                "→".dimmed()
            );
            std::process::exit(1);
        }
        drain_resume::FromPrOutcome::RefuseAlreadyMerged => {
            eprintln!(
                "{} {} is already merged — the merge already happened, so there is nothing to drive.",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                pr.map(|n| format!("PR-{n}")).unwrap_or_else(|| "the PR".into())
            );
            eprintln!(
                "  {} run `aida pull` to auto-bump `{}` Done → Completed.",
                "→".dimmed(),
                spec
            );
            std::process::exit(1);
        }
        drain_resume::FromPrOutcome::DriveFrom(start_phase) => {
            println!(
                "{} driving `{}` from phase {} ({}) — implementation shipped outside the \
                 orchestrator (skipping the implementer phase).",
                "↩".cyan().bold(),
                spec,
                start_phase.index(),
                start_phase.slug()
            );
            if let Some(n) = pr {
                println!("  {} seeded PR-{}", "→".dimmed(), n);
            }
            if dry_run {
                println!(
                    "  {} --resume-dry-run — not re-entering. Drop it to drive the PR.",
                    "→".dimmed()
                );
                std::process::exit(0);
            }
            // The implementer ran outside the orchestrator and may hold a stale
            // lease on this scope; release a dead/clean one so the reviewer
            // phase (which resolves PR→spec) doesn't collide. Same guard the
            // resume path applies (BUG-438). trace:TASK-405 | ai:claude
            release_dead_leases_for_resume(&project_root, spec);
            let resume_entry = Some(ResumeEntry {
                start_phase,
                branch,
                pr,
            });
            let result = run_auto_complete(
                storage,
                user_id,
                spec,
                variant,
                json,
                permission_mode,
                no_human,
                escalate_mode,
                // A standalone `--from-pr` drive owns its drain-state file.
                true,
                steal,
                force_claim,
                allow_stale_base,
                no_auto_rebase,
                resume_entry,
            );
            // TASK-1054: collapse the failed-phase index to the canonical
            // 0/2/3 process code so a wrapping script can branch on the outcome.
            std::process::exit(result.process_exit_code());
        }
    }
}

/// STORY-384: `aida queue recover <id>` — the failed-phase-1 recovery wizard.
///
/// Inspects the spec's recovery-relevant state (lease, branch, worktree, PR),
/// derives the recommended recovery path via the pure
/// [`queue_recover::recommend`], prints the inspection + recommendation, and —
/// unless `--dry-run` — steps through the recovery, confirming destructive ops
/// (push, PR-create, session end) unless `--auto`.
///
/// A FRONT-END over existing primitives: the probes reuse the same lease/PR/git
/// helpers the orchestrator and `aida session leases` use; the execution shells
/// out to `aida` subcommands (`queue work --from-pr`, `pull`, `session end`,
/// `queue add`) and `git` / `gh` rather than reimplementing them.
/// trace:STORY-384 | ai:claude
fn handle_queue_recover(
    storage: &Storage,
    user_id: &str,
    spec_query: &str,
    dry_run: bool,
    auto: bool,
) -> Result<()> {
    let project_root = find_project_root()?;

    // Resolve the spec id + status from the store (canonical SPEC-ID, status
    // for display). A spec we can't find still gets a best-effort recovery
    // using the query string verbatim, but we warn.
    let store = storage.load().ok();
    let (spec, status_label, spec_completed) = match store.as_ref().and_then(|s| {
        s.requirements.iter().find(|r| {
            r.spec_id.as_deref() == Some(spec_query)
                || r.agreed_id.as_deref() == Some(spec_query)
                || r.id.to_string() == spec_query
        })
    }) {
        Some(req) => {
            let id = req
                .agreed_id
                .clone()
                .or_else(|| req.spec_id.clone())
                .unwrap_or_else(|| spec_query.to_string());
            (
                id,
                req.status.to_string(),
                req.status == RequirementStatus::Completed,
            )
        }
        None => {
            eprintln!(
                "{} no spec matched `{}` in the store — probing git/PR state by the id verbatim.",
                crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                spec_query
            );
            (spec_query.to_string(), "<unknown>".to_string(), false)
        }
    };

    // --- Inspection: probe the world for this spec. ---
    // Reuse the orchestrator's PR/branch/CI/reviewed/merged probe (the same
    // helper `--from-pr` and `--resume-drain` use). `member: None` is the
    // standalone-PR case it already handles. trace:STORY-384 | ai:claude
    let (facts, pr_branch, pr) = probe_resume_facts(&project_root, storage, &spec, None);

    // Lease state — does a session still hold this spec's scope?
    let leases = list_leases(&project_root);
    let lease = find_lease_by_spec(&spec, &leases).ok();
    let now = chrono::Utc::now();
    let live = process_probe::probe_live_claude_sessions();
    // BUG-511: review-verb leases classify by creator PID, not worktree.
    let lease_state = lease.as_ref().map(|l| lease_state_for(l, &live, now));

    // The branch we inspect for commits-ahead / dirty: prefer the lease's
    // branch (where a phase-1 implementer committed), else the PR head branch.
    let branch = lease
        .as_ref()
        .map(|l| l.branch.clone())
        .or_else(|| pr_branch.clone());

    // Commits ahead of origin/main on the branch (work that exists but may not
    // have shipped). Probe against the lease worktree if present, else root.
    let probe_repo = lease
        .as_ref()
        .map(|l| l.worktree_path.clone())
        .filter(|p| p.exists())
        .unwrap_or_else(|| project_root.clone());
    let commits_ahead = branch
        .as_deref()
        .and_then(|b| branch_commits_ahead_main(&probe_repo, b))
        .unwrap_or(0);

    // Branch pushed? A PR implies a pushed branch; otherwise probe origin.
    let branch_pushed = pr.is_some()
        || branch
            .as_deref()
            .map(|b| {
                matches!(
                    probe_branch_on_origin(&project_root, b),
                    BranchOriginProbe::Present
                )
            })
            .unwrap_or(false);

    // Worktree dirty? Only meaningful when a lease worktree exists.
    let dirty_entries = lease
        .as_ref()
        .filter(|l| l.worktree_path.exists())
        .map(|l| worktree_dirty_entries(&l.worktree_path))
        .unwrap_or_default();
    let uncommitted_changes = !dirty_entries.is_empty();

    let state = queue_recover::RecoverState {
        spec_completed: spec_completed || facts.spec_completed,
        pr_exists: pr.is_some(),
        pr_merged: facts.pr_merged,
        commits_ahead,
        branch_pushed,
        uncommitted_changes,
        lease_held: lease.is_some(),
    };

    // --- Print the inspection result. ---
    println!("🔎 recovery inspection for {}", spec.bold());
    println!("  {:<14} {}", "status".dimmed(), status_label);
    match (&lease, lease_state) {
        (Some(l), Some(st)) => println!(
            "  {:<14} {} {} (id {}, branch {})",
            "lease".dimmed(),
            st.glyph(),
            st.label(),
            &l.id[..l.id.len().min(8)],
            l.branch
        ),
        _ => println!("  {:<14} none", "lease".dimmed()),
    }
    match &branch {
        Some(b) => println!(
            "  {:<14} {} — {} commit(s) ahead of origin/main, {}",
            "branch".dimmed(),
            b,
            commits_ahead,
            if branch_pushed {
                "pushed"
            } else {
                "NOT pushed"
            }
        ),
        None => println!("  {:<14} none", "branch".dimmed()),
    }
    if uncommitted_changes {
        println!(
            "  {:<14} {} uncommitted change(s)",
            "worktree".dimmed(),
            dirty_entries.len()
        );
        for e in dirty_entries.iter().take(3) {
            println!("                   {}", e.dimmed());
        }
        if dirty_entries.len() > 3 {
            println!(
                "                   {} … and {} more",
                "".dimmed(),
                dirty_entries.len() - 3
            );
        }
    } else {
        println!("  {:<14} clean", "worktree".dimmed());
    }
    match pr {
        Some(n) if facts.pr_merged => println!("  {:<14} PR-{} (merged)", "pr".dimmed(), n),
        Some(n) => println!("  {:<14} PR-{} (open)", "pr".dimmed(), n),
        None => println!("  {:<14} none", "pr".dimmed()),
    }
    println!();

    // --- Recommendation. ---
    let action = queue_recover::recommend(&state);
    println!(
        "{} recommended: {}",
        "→".cyan().bold(),
        recover_action_label(action).bold()
    );
    println!("  {} {}", "rationale:".dimmed(), action.rationale());
    println!();

    if dry_run {
        println!(
            "{} --dry-run — not executing. Drop it to run the recovery.",
            crate::glyph(crate::glyphs::Glyph::Info).cyan()
        );
        return Ok(());
    }

    // --- Execution. ---
    let aida = std::env::current_exe().unwrap_or_else(|_| std::path::PathBuf::from("aida"));
    // Helper: run an `aida` subcommand from the project root, surfacing its
    // exit code. Non-zero leaves the state visible for manual resume.
    let run_aida = |args: &[&str]| -> std::io::Result<std::process::ExitStatus> {
        println!(
            "  {} aida {}",
            crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
            args.join(" ")
        );
        std::process::Command::new(&aida)
            .current_dir(&project_root)
            .args(args)
            .status()
    };
    let run_git =
        |args: &[&str], cwd: &std::path::Path| -> std::io::Result<std::process::ExitStatus> {
            println!(
                "  {} git {}",
                crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                args.join(" ")
            );
            std::process::Command::new("git")
                .arg("-C")
                .arg(cwd)
                .args(args)
                .status()
        };
    // Confirm a destructive op unless --auto. Non-interactive (no TTY) defaults
    // to NO so a scripted run without --auto never silently ships.
    let confirm = |what: &str| -> bool {
        if auto {
            return true;
        }
        prompt_yes_no(&format!("  {} {} [y/N] ", "?".yellow(), what), false).unwrap_or(false)
    };

    match action {
        queue_recover::RecoverAction::AlreadyCompleted => {
            println!(
                "{} `{}` is already Completed — nothing to recover.",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                spec
            );
            if state.lease_held && confirm("end the leaked lease for this spec?") {
                let _ = run_aida(&["session", "end", &spec]);
            }
        }
        queue_recover::RecoverAction::AlreadyMergedPull => {
            println!(
                "{} the PR merged — pulling to auto-bump `{}` Done → Completed.",
                "↩".cyan().bold(),
                spec
            );
            let _ = run_aida(&["pull"]);
            if state.lease_held && confirm("end the leaked lease for this spec?") {
                let _ = run_aida(&["session", "end", &spec]);
            }
        }
        queue_recover::RecoverAction::DrivePhasesFromPr => {
            if !confirm("drive phases 3-6 on the open PR (reviewer → merge → pull → build)?")
            {
                println!(
                    "{} skipped — state left intact.",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan()
                );
                return Ok(());
            }
            // Reuse the TASK-405 PR-only orchestrator path.
            let _ = run_aida(&["queue", "work", &spec, "--auto-complete", "--from-pr"]);
        }
        queue_recover::RecoverAction::PushOpenPrDrive => {
            let Some(b) = branch.as_deref() else {
                eprintln!(
                    "{} no branch to push for `{}` — cannot recover automatically.",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    spec
                );
                return Ok(());
            };
            if !confirm(&format!("push `{b}`, open a PR, then drive phases 3-6?")) {
                println!(
                    "{} skipped — state left intact.",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan()
                );
                return Ok(());
            }
            let push_st = run_git(&["push", "-u", "origin", b], &probe_repo)?;
            if !push_st.success() {
                eprintln!(
                    "{} push failed — resolve manually, then re-run `aida queue recover {}`.",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    spec
                );
                return Ok(());
            }
            // Open the change through the forge — title/body derived from the
            // branch commits (the forge-routed equivalent of `gh pr create
            // --fill`), so a GitLab/pure-git repo opens its own change.
            // trace:TASK-961 trace:STORY-621 | ai:claude
            if recover_open_change(&probe_repo, b) {
                // Now drive phases 3-6 on the freshly-opened change.
                let _ = run_aida(&["queue", "work", &spec, "--auto-complete", "--from-pr"]);
            } else {
                eprintln!(
                    "{} opening the {} failed — open it manually, then run \
                     `aida queue recover {}` again (it will take the drive-from-PR path).",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    crate::forge::resolve_forge_kind(&probe_repo).change_noun(),
                    spec
                );
            }
        }
        queue_recover::RecoverAction::WipCommitPushDrive => {
            if !confirm("commit the WIP, then push + open PR + drive phases 3-6?") {
                println!(
                    "{} skipped — commit/stash the WIP yourself, then re-run.",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan()
                );
                return Ok(());
            }
            let _ = run_git(&["add", "-A"], &probe_repo)?;
            let _ = run_git(
                &["commit", "-m", &format!("wip: recover {spec}")],
                &probe_repo,
            )?;
            let Some(b) = branch.as_deref() else {
                eprintln!(
                    "{} no branch to push.",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold()
                );
                return Ok(());
            };
            let push_st = run_git(&["push", "-u", "origin", b], &probe_repo)?;
            if !push_st.success() {
                eprintln!(
                    "{} push failed — resolve manually.",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold()
                );
                return Ok(());
            }
            // Forge-routed change open — title/body derived from the branch
            // commits. trace:TASK-961 trace:STORY-621 | ai:claude
            if recover_open_change(&probe_repo, b) {
                let _ = run_aida(&["queue", "work", &spec, "--auto-complete", "--from-pr"]);
            } else {
                eprintln!(
                    "{} opening the {} failed — open it manually, then re-run recover.",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    crate::forge::resolve_forge_kind(&probe_repo).change_noun()
                );
            }
        }
        queue_recover::RecoverAction::WipCommitPark => {
            println!(
                "{} preserving uncommitted work as a WIP commit (parked for resumption).",
                crate::glyph(crate::glyphs::Glyph::Info).cyan()
            );
            if !confirm("commit the WIP on the branch and park (no PR)?") {
                println!(
                    "{} skipped — state left intact.",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan()
                );
                return Ok(());
            }
            let _ = run_git(&["add", "-A"], &probe_repo)?;
            let _ = run_git(
                &["commit", "-m", &format!("wip: recover {spec} (parked)")],
                &probe_repo,
            )?;
            println!(
                "{} WIP committed. Resume later with `aida queue work {} --resume`.",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                spec
            );
        }
        queue_recover::RecoverAction::EndAndRequeue => {
            println!(
                "{} nothing was shipped — ending the lease and re-queueing `{}` for a fresh attempt.",
                "↩".cyan().bold(),
                spec
            );
            if !confirm("end the session and re-queue the spec?") {
                println!(
                    "{} skipped — state left intact.",
                    crate::glyph(crate::glyphs::Glyph::Info).cyan()
                );
                return Ok(());
            }
            if state.lease_held {
                let _ = run_aida(&["session", "end", &spec]);
            }
            // Re-queue for the spec's owner. queue add is advisor-gated in
            // non-TTY contexts, so route the role explicitly.
            let _ = run_aida(&["queue", "add", &spec, "--user", user_id]);
        }
    }

    Ok(())
}

/// TASK-836: probe the richer pre-merge facts for ONE ready integration
/// candidate — CI rollup, RequestChanges (local verdict OR forge decision), and
/// mergeability — and normalize them into the pure [`integrate::PrIntegrationState`]
/// the pre-merge gate decides on. All the messy `gh`-string interpretation lives
/// here, at the probe boundary; the decision ([`integrate::classify_integration_action`])
/// stays pure + unit-tested.
///
/// Conservative: anything we cannot tell degrades to the optimistic value
/// (CI `None`, no RequestChanges, `Unknown` mergeable) — the `--from-pr` drive
/// re-gates CI + merge before the irreversible step, so "couldn't tell" never
/// ships something unsafe; it just doesn't pre-empt a park. trace:TASK-836
fn probe_pr_integration_state(
    project_root: &std::path::Path,
    spec_id: &str,
    branch: Option<&str>,
    snapshot: &OpenPrSnapshot,
) -> integrate::PrIntegrationState {
    // The forge row for this PR (keyed by head branch).
    let item = branch.and_then(|b| snapshot.by_branch.get(b));

    // CI: prefer the snapshot rollup ("pass"/"fail"/"pending"/"?"), normalized.
    let ci = match item.and_then(|i| i.ci_rollup.as_deref()) {
        Some("pass") => integrate::CiState::Passing,
        Some("fail") => integrate::CiState::Failing,
        Some("pending") => integrate::CiState::Running,
        _ => integrate::CiState::None,
    };

    // Mergeability: the forge's `mergeable` field — MERGEABLE / CONFLICTING /
    // UNKNOWN. "UNKNOWN" means GitHub hasn't computed it yet; treated optimistic.
    // A behind-base branch presents as CONFLICTING only on a real conflict, so
    // we can't distinguish BehindBase from the snapshot alone — the caller's
    // --rebase step covers the behind-base case, so mapping non-conflict to
    // Unknown here is sufficient. trace:TASK-836
    let mergeable = match item.and_then(|i| i.mergeable.as_deref()) {
        Some("MERGEABLE") => integrate::MergeableState::Mergeable,
        Some("CONFLICTING") => integrate::MergeableState::Conflicting,
        _ => integrate::MergeableState::Unknown,
    };

    // RequestChanges from the forge's reviewDecision (CHANGES_REQUESTED).
    let forge_request_changes = item
        .and_then(|i| i.review_decision.as_deref())
        .map(|d| d.eq_ignore_ascii_case("CHANGES_REQUESTED"))
        .unwrap_or(false);

    // RequestChanges from the LOCAL review-verdict file (the orchestrator's own
    // reviewer writes `.aida/review-verdicts/PR-N.json`). Either source is a
    // hard stop — never merge over a pending RequestChanges. trace:TASK-836
    let local_request_changes = item
        .map(|i| i.number)
        .map(|n| {
            let path = project_root
                .join(".aida")
                .join("review-verdicts")
                .join(format!("PR-{n}.json"));
            matches!(
                read_verdict_file(&path),
                Ok(auto_complete::ReviewerOutcome::Verdict(
                    auto_complete::Verdict::RequestChanges
                ))
            )
        })
        .unwrap_or(false);

    let _ = spec_id; // spec id is the caller's message prefix, not a probe input.
    integrate::PrIntegrationState {
        ci,
        request_changes_pending: forge_request_changes || local_request_changes,
        mergeable,
    }
}

/// STORY-520: `aida queue integrate` — the thin integrator watch-loop.
///
/// The consumer half of a producer/consumer split: parallel implementers
/// produce PRs + flip specs to Done; this single serial loop consumes that
/// signal (Done + open PR) and drives the back-end merge phases on each in turn.
///
/// A FRONT-END over existing primitives, not new mechanism: the ready-set query
/// reuses the store load + the forge PR/merged probes (`probe_resume_facts`),
/// the membership decision is the pure [`integrate::classify_candidate`], and
/// each ready spec is driven by shelling out to the SAME TASK-405 PR-only path
/// (`aida queue work <id> --auto-complete --from-pr`) the resume/recover flows
/// use. The serial-merge invariant (one merge authority over `main`) is
/// preserved by driving each spec to completion before the next.
/// trace:STORY-520 | ai:claude
// why: command-dispatch fn whose params mirror distinct CLI flags; bundling into a struct adds indirection without clarifying the call sites.
#[allow(clippy::too_many_arguments)]
/// TASK-1036: build the focus subtree as a set of display SPEC-IDs — the focus
/// root (`focus_ref`, a spec/agreed/uuid form) plus its transitive descendants
/// (the cache's `descendant_ids` closure, TASK-955, which INCLUDES the root),
/// mapped to the same display-id form the integrator keys candidates on. Used to
/// scope the integrator `--watch` candidate scan and the event-wake filter.
///
/// Best-effort: an unresolvable store / focus spec / cache error yields `None`,
/// which the caller treats as "no scoping" (whole-project scan) rather than
/// blocking — a focus that no longer resolves must never wedge the integrator.
// trace:TASK-1036 | ai:claude
fn build_focus_display_subtree(
    project_root: &std::path::Path,
    focus_ref: &str,
    store: &aida_core::RequirementsStore,
) -> Option<std::collections::HashSet<String>> {
    let store_path = detect_distributed_store_from(project_root)?;
    let backend = advance_backend(&store_path).ok()?;
    let focus_req = backend
        .get_requirement_by_spec_id(focus_ref)
        .ok()
        .flatten()?;
    let uuid_subtree = backend.descendant_ids(&focus_req.id).ok()?;
    let display: std::collections::HashSet<String> = store
        .requirements
        .iter()
        .filter(|r| uuid_subtree.contains(&r.id))
        .map(|r| r.display_id())
        .collect();
    Some(display)
}

#[allow(clippy::too_many_arguments)]
fn handle_queue_integrate(
    storage: &Storage,
    _user_id: &str,
    dry_run: bool,
    watch: bool,
    interval: u64,
    max: usize,
    rebase: bool,
    strategy: Option<integrate::IntegrateStrategy>,
    // TASK-1036: scope the candidate scan to a focus subtree. `--focus <id>`
    // overrides; else the per-worktree `aida focus` marker / `AIDA_FOCUS`.
    focus_override: Option<String>,
    // TASK-1036: idle backstop for the event-driven `--watch` loop, in minutes.
    // `None` falls back to `--interval` seconds (the old blind-timer cadence).
    idle_minutes: Option<u64>,
) -> Result<()> {
    let project_root = find_project_root()?;

    // TASK-812: take the global drain lock so an integrate run (especially
    // `--watch`, which a solo operator leaves running) can't double-drive the
    // tree against a `burndown run` / `queue work --auto-complete` / a second
    // `integrate` — they ALL merge into the shared default branch, so there can
    // be only one merge authority at a time. Held for the whole run, including
    // the `--watch` loop; a crashed watcher's lock is stale-reclaimed by the
    // next launch (BUG-538). `--dry-run` drives nothing, so it skips the lock.
    // The guard frees on return (this fn returns Result, never `process::exit`).
    // trace:TASK-812 | ai:claude
    let _drain_guard = if dry_run {
        None
    } else {
        Some(drain_lock::acquire_drain_lock(
            &project_root,
            "queue integrate",
        )?)
    };

    // TASK-691: resolve the accumulation strategy — the --strategy flag wins,
    // else the project default (`[integrate] strategy` in .aida/config.toml),
    // else `per-item`. trace:TASK-691 | ai:claude
    let strategy = strategy
        .or_else(|| {
            std::fs::read_to_string(project_root.join(".aida").join("config.toml"))
                .ok()
                .and_then(|c| integrate::integrate_strategy_from_config(&c))
        })
        .unwrap_or(integrate::IntegrateStrategy::PerItem);

    // STORY-335: only `per-item` is built; refuse `one-branch`/`stacked` cleanly
    // (with a pointer) before doing any probing or acting. trace:STORY-335
    if let Some(msg) = integrate::strategy_unsupported_message(strategy) {
        anyhow::bail!(msg);
    }

    let aida = std::env::current_exe().unwrap_or_else(|_| std::path::PathBuf::from("aida"));

    // TASK-1036: resolve the active focus once — `--focus <id>` wins, else the
    // per-worktree `aida focus` marker / `AIDA_FOCUS` (STORY-706). The per-pass
    // subtree is re-resolved inside the loop (cache-backed, cheap) so newly-filed
    // descendants are picked up. trace:TASK-1036 | ai:claude
    let active_focus = focus_override.or_else(|| crate::focus::resolve_focus(&project_root));

    // TASK-1036: in `--watch`, wake on real drain events instead of a blind
    // timer. Seed the event cursor at the stream's CURRENT end so a stale backlog
    // from a prior drain never re-fires an old wake (the advisor_watch precedent).
    // The idle backstop is the documented timer fallback: `--idle-minutes` if
    // given, else the legacy `--interval` seconds. trace:TASK-1036 | ai:claude
    let events_path = crate::events::events_path(&project_root);
    let mut event_offset: u64 = std::fs::metadata(&events_path)
        .map(|m| m.len())
        .unwrap_or(0);
    let idle_backstop_secs = idle_minutes
        .map(|m| m.saturating_mul(60))
        .unwrap_or(interval);

    // TASK-1050 / BUG-650 (slice 2b): give `aida integrate` its OWN checkout so
    // it never contends the advisor's harness-worktree lease — the gate that
    // unblocks UNATTENDED `--watch`. (1) acquire/reuse a dedicated warm-pool
    // worktree pinned to the default branch under a distinct integrator lease
    // scope; (2) refuse to drive from — or relocate the drives out of — a shared
    // checkout a live non-integrator session holds (option-c). The merge drives
    // below run IN this dedicated checkout. `--dry-run` drives nothing, so it
    // skips both. The global drain lock taken above is untouched: it stays the
    // one merge authority repo-wide. trace:TASK-1050 trace:BUG-650 | ai:claude
    let integrator_checkout: Option<std::path::PathBuf> = if dry_run {
        None
    } else {
        let dedicated = integrate_checkout::ensure_integrator_checkout(&project_root)?;
        let cwd = std::env::current_dir().unwrap_or_else(|_| project_root.clone());
        integrate_checkout::guard_not_shared_checkout(&project_root, &cwd, &dedicated)?;
        Some(dedicated)
    };
    // The cwd for the spawned child drives: the dedicated integrator checkout
    // when we have one, else the project root (dry-run never spawns a real
    // drive). trace:TASK-1050 | ai:claude
    let drive_cwd: &std::path::Path = integrator_checkout
        .as_deref()
        .unwrap_or(project_root.as_path());

    let mut integrated_total: usize = 0;
    let mut pass: usize = 0;
    // TASK-836: track whether any member was parked (shelvable scenario) or made
    // to wait (CI running) across the whole run, so the exit code mirrors the
    // resilient-drain contract: exit 2 when anything was parked/skipped so a
    // wrapping script triages instead of treating the run as a clean success.
    // trace:TASK-836 | ai:claude
    let mut any_parked_or_waited = false;

    loop {
        pass += 1;

        // --- Probe: build the candidate set from store status + forge facts. ---
        // Reuse `probe_resume_facts` (the same PR/merged probe `--from-pr` and
        // `--resume-drain` use) so the integrator sees exactly the reality the
        // drive path will. trace:STORY-520 | ai:claude
        let store = storage.load()?;

        // TASK-1036: re-resolve the focus subtree this pass (cache-backed, cheap)
        // — the display-id set of the focus root + its transitive descendants —
        // so an out-of-scope Done spec is never probed or driven. `None` = no
        // focus set → whole-project scan, exactly as before. trace:TASK-1036
        let focus_subtree: Option<std::collections::HashSet<String>> = active_focus
            .as_deref()
            .and_then(|focus_ref| build_focus_display_subtree(&project_root, focus_ref, &store));
        if watch {
            if let (Some(focus_ref), Some(subtree)) = (active_focus.as_deref(), &focus_subtree) {
                println!(
                    "  {} focus {} — scanning {} spec(s) in subtree",
                    crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                    focus_ref,
                    subtree.len()
                );
            }
        }

        let mut candidates: Vec<integrate::IntegrationCandidate> = Vec::new();
        // STORY-335: keep each candidate's PR branch (for the dry-run forecast)
        // and PR number (for the --rebase step) per ready member. trace:STORY-335
        let mut branches: std::collections::HashMap<String, Option<String>> =
            std::collections::HashMap::new();
        let mut pr_numbers: std::collections::HashMap<String, Option<u32>> =
            std::collections::HashMap::new();
        for req in &store.requirements {
            if req.status != RequirementStatus::Done {
                continue;
            }
            let id = req
                .agreed_id
                .as_deref()
                .or(req.spec_id.as_deref())
                .unwrap_or("?")
                .to_string();
            // TASK-1036: focus-scope the scan BEFORE the (forge) probe, so an
            // out-of-scope Done spec is never probed, reported, or driven. Pure
            // `integrate::in_focus_scope` over the display-id subtree set.
            // trace:TASK-1036 | ai:claude
            if let Some(subtree) = &focus_subtree {
                if !integrate::in_focus_scope(&id, subtree) {
                    continue;
                }
            }
            // Classify the PR lookup as conclusive-or-not BEFORE probing the
            // richer facts, so a flaky gh never gets read as "no PR".
            let lookup = detect_open_pr_for_spec_via_forge(&project_root, &id);
            let inconclusive = matches!(
                lookup,
                PrLookup::GhMissing | PrLookup::GhFailed(_) | PrLookup::GhUnreachable(_)
            );
            let (facts, branch, pr) = probe_resume_facts(&project_root, storage, &id, None);
            branches.insert(id.clone(), branch);
            pr_numbers.insert(id.clone(), pr);
            candidates.push(integrate::IntegrationCandidate {
                id,
                is_done: true,
                has_open_pr: pr.is_some(),
                pr_merged: facts.pr_merged,
                pr_lookup_inconclusive: inconclusive,
                // TASK-813: keystone work the integrator must NOT auto-merge.
                held_for_human: req.tags.iter().any(|t| {
                    let t = t.trim();
                    t.eq_ignore_ascii_case("supervised")
                        || t.eq_ignore_ascii_case("review:draft-only")
                }),
            });
        }

        let ready = integrate::ready_for_integration(&candidates);

        // TASK-836: one forge snapshot per pass (CI rollup + mergeable +
        // reviewDecision keyed by branch) feeds the pre-merge scenario gate
        // below. Empty when gh is missing/failing — the gate then degrades to
        // the optimistic "Merge" verdict, and the --from-pr drive re-gates the
        // irreversible step. trace:TASK-836 | ai:claude
        let mut pr_snapshot = if dry_run || !ready.is_empty() {
            collect_open_prs(&project_root)
        } else {
            OpenPrSnapshot::default()
        };

        // --- Report the pass. ---
        if watch {
            println!(
                "{} integrator pass {} — {} Done spec(s), {} ready for integration",
                crate::glyph(crate::glyphs::Glyph::Arrow).cyan().bold(),
                pass,
                candidates.len(),
                ready.len()
            );
        } else {
            println!(
                "{} {} Done spec(s); {} ready for integration",
                crate::glyph(crate::glyphs::Glyph::Arrow).cyan().bold(),
                candidates.len(),
                ready.len()
            );
        }
        for c in &candidates {
            match integrate::classify_candidate(c) {
                integrate::CandidateVerdict::Integrate => {
                    println!("  {} {} — open PR, ready to merge", "→".green(), c.id);
                }
                integrate::CandidateVerdict::SkipNoPr => {
                    println!("  {} {} — Done but no open PR (skip)", "·".dimmed(), c.id);
                }
                integrate::CandidateVerdict::SkipAlreadyMerged => {
                    println!(
                        "  {} {} — PR already merged; `aida pull` will promote it (skip)",
                        "·".dimmed(),
                        c.id
                    );
                }
                integrate::CandidateVerdict::SkipProbeInconclusive => {
                    println!(
                        "  {} {} — PR probe inconclusive (gh missing/auth/network); skipping, not guessing",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                        c.id
                    );
                }
                integrate::CandidateVerdict::SkipHeldForHuman => {
                    println!(
                        "  {} {} — keystone (supervised / review:draft-only): parked for your review, not auto-merged",
                        "⏸".yellow(),
                        c.id
                    );
                }
                // Non-Done specs were filtered out before classification.
                integrate::CandidateVerdict::SkipNotDone => {}
            }
        }

        // --- Act: drive each ready spec, serially, through the PR-only path. ---
        let mut ready_ids: Vec<String> = ready.iter().map(|c| c.id.clone()).collect();

        // TASK-841: `--strategy stacked` — order + gate the ready set by the
        // recorded stack graph. A member stacked behind another still-open branch
        // is DEFERRED this pass (merging it now would drag the parent's
        // un-squashed commits in under the wrong PR); only the mergeable
        // bottom-of-stack layer is driven. Completion stays per-commit (each
        // member auto-bumps when its own commit lands), so no special barrier is
        // needed — just this ordering. The drive's `aida pull` then cascade-
        // rebases the next layer's worktree (STORY-248); a later `--watch` pass
        // (or re-run) picks it up. trace:TASK-841 | ai:claude
        if matches!(strategy, integrate::IntegrateStrategy::Stacked) && !ready_ids.is_empty() {
            let mut graph = stacks::load(&project_root);
            let default_short = detect_default_branch_ref(&project_root)
                .as_deref()
                .map(|s| s.strip_prefix("origin/").unwrap_or(s).to_string())
                .unwrap_or_else(|| "main".to_string());
            let plan =
                integrate::plan_stacked_integration(&ready_ids, &branches, &graph, &default_short);
            // TASK-1080: stack-aware promotion. A deferred member whose parent
            // branch is GONE on origin (squash-merged + deleted) is promoted in
            // place: its ORIGIN PR branch is rebased with the 3-arg
            // `git rebase --onto <default> <recorded fork SHA>` + force-pushed
            // with lease — composing the one `pr rebase` machinery (temp
            // worktree, BUG-640 patch-id guard, lease-anchored push) via
            // `--onto-parent` — then merged by the normal drive THIS pass. The
            // STORY-248 cascade only rebases the child's local worktree; this
            // closes the origin-PR half so a 2-deep stack drains without a
            // manual `/aida-rebase`. The decision per member is the pure
            // `integrate::classify_stacked_promotion`. trace:TASK-1080 | ai:claude
            let mut promoted: Vec<String> = Vec::new();
            let mut still_deferred = 0usize;
            for d in &plan.deferred {
                if let Some(parent_spec) = &d.blocked_on_spec {
                    // Parent is in THIS pass's ready set — it merges below; the
                    // next pass (or --watch wake) promotes this child.
                    println!(
                        "  {} {} — stacked behind {} (branch `{}`); deferring until it lands",
                        "⏸".yellow(),
                        d.id,
                        parent_spec,
                        d.blocked_on_branch
                    );
                    still_deferred += 1;
                    continue;
                }
                let child_branch = branches.get(&d.id).and_then(|b| b.clone());
                let recorded_sha = child_branch
                    .as_deref()
                    .and_then(|b| graph.get(b))
                    .map(|e| e.parent_branch_sha.clone());
                let parent_gone = remote_branch_gone(&project_root, &d.blocked_on_branch);
                let pr_num = pr_numbers.get(&d.id).and_then(|p| *p);
                match integrate::classify_stacked_promotion(
                    recorded_sha.as_deref(),
                    parent_gone,
                    pr_num.is_some(),
                ) {
                    integrate::StackedPromotion::Promote { parent_sha } => {
                        let pr = pr_num.expect("Promote implies a resolved PR number");
                        if dry_run {
                            println!(
                                "  {} {} — parent `{}` merged+deleted; [dry-run] would rebase PR #{} onto {} (stack-aware) and force-push-with-lease",
                                "↻".cyan(),
                                d.id,
                                d.blocked_on_branch,
                                pr,
                                default_short
                            );
                            promoted.push(d.id.clone());
                            continue;
                        }
                        println!(
                            "  {} {} — parent `{}` merged+deleted; promoting: stack-aware rebase of PR #{} onto {}…",
                            "↻".cyan(),
                            d.id,
                            d.blocked_on_branch,
                            pr,
                            default_short
                        );
                        let status = std::process::Command::new(&aida)
                            .current_dir(drive_cwd)
                            .args(integrate::promotion_rebase_args(pr, &parent_sha))
                            .status();
                        match status {
                            Ok(s) if s.success() => {
                                // The child now forks straight from the default
                                // branch — drop its stack entry so no later pass
                                // or cascade replays the consumed fork record.
                                // Dependents (grandchildren) keep their own
                                // records: their recorded fork SHA is still an
                                // ancestor of THEIR untouched PR head, so their
                                // eventual promotion stays correct.
                                if let Some(b) = child_branch.as_deref() {
                                    stacks::remove(&mut graph, b);
                                    if let Err(e) = stacks::save(&project_root, &graph) {
                                        eprintln!(
                                            "  {} could not update .aida/stacks.json: {e}",
                                            "Note:".dimmed()
                                        );
                                    }
                                }
                                println!(
                                    "  {} {} promoted — PR #{} rebased + force-pushed; merging this pass",
                                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                                    d.id,
                                    pr
                                );
                                promoted.push(d.id.clone());
                            }
                            Ok(_) => {
                                // Shelvable failure — park + continue (resilient-
                                // drain contract). Never corrupts: `pr rebase`
                                // aborts a conflicted rebase and cleans its temp
                                // worktree; nothing was pushed.
                                println!(
                                    "  {} {} — stack-aware rebase failed (conflict?); parking and continuing",
                                    "⏸".yellow(),
                                    d.id
                                );
                                if let Err(e) = shelve_spec_on_failure(
                                    &project_root,
                                    &d.id,
                                    "integrate",
                                    0,
                                    "stacked-rebase",
                                    &format!(
                                        "stack-aware rebase of PR #{pr} onto {default_short} failed (likely a conflict replaying the stacked commits)"
                                    ),
                                    &format!(
                                        "resolve with `aida pr rebase {pr} --onto-parent {parent_sha}` (or add `--interactive`), then re-run `aida queue integrate --strategy stacked`"
                                    ),
                                ) {
                                    eprintln!(
                                        "  {} could not park {}: {e}",
                                        "Note:".dimmed(),
                                        d.id
                                    );
                                }
                                any_parked_or_waited = true; // trace:TASK-836
                            }
                            Err(e) => {
                                println!(
                                    "  {} {} — could not launch the stack-aware rebase ({e}); deferring",
                                    crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                                    d.id
                                );
                                still_deferred += 1;
                            }
                        }
                    }
                    integrate::StackedPromotion::ParentStillOpen => {
                        println!(
                            "  {} {} — stacked behind `{}` (parent not merged yet); deferring until it lands",
                            "⏸".yellow(),
                            d.id,
                            d.blocked_on_branch
                        );
                        still_deferred += 1;
                    }
                    integrate::StackedPromotion::ProbeInconclusive => {
                        println!(
                            "  {} {} — stacked behind `{}`; couldn't verify the parent branch on origin (offline?); deferring, not guessing",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                            d.id,
                            d.blocked_on_branch
                        );
                        still_deferred += 1;
                    }
                    integrate::StackedPromotion::ChurnedNoEntry => {
                        // Churn guard: the cascade removed the stack entry after
                        // this pass's plan was computed — defer and let the next
                        // re-plan classify it (it will read as mergeable).
                        println!(
                            "  {} {} — its stack record vanished mid-pass; deferring (next pass re-plans)",
                            "·".dimmed(),
                            d.id
                        );
                        still_deferred += 1;
                    }
                    integrate::StackedPromotion::NoPrNumber => {
                        println!(
                            "  {} {} — parent `{}` merged but no PR number resolved; run `/aida-rebase` in its worktree, then re-run",
                            "⏸".yellow(),
                            d.id,
                            d.blocked_on_branch
                        );
                        still_deferred += 1;
                    }
                }
            }
            if still_deferred > 0 {
                // Mirror the resilient-drain contract: something was held back, so
                // the run exits 2 and a wrapping loop (or `--watch`) re-checks
                // after the bottom layer merges. trace:TASK-836 | ai:claude
                any_parked_or_waited = true;
            }
            ready_ids = plan.mergeable;
            ready_ids.extend(promoted.iter().cloned());
            // A promoted child's snapshot row predates the force-push — refresh
            // so the TASK-836 pre-merge gate judges the NEW head, not the stale
            // stacked one. trace:TASK-1080 | ai:claude
            if !promoted.is_empty() && !dry_run {
                pr_snapshot = collect_open_prs(&project_root);
            }
        }

        // STORY-335: dry-run rebase-conflict forecast. Each ready member's PR
        // branch is checked (read-only, via `git merge-tree`) against current
        // main — surfacing which WILL conflict before any merge is attempted.
        // Read-only first slice: the act path below is unchanged (no rebase step
        // yet). trace:STORY-335 | ai:claude
        if dry_run && !ready_ids.is_empty() {
            let base = detect_default_branch_ref(&project_root);
            let rows: Vec<integrate::ForecastRow> = ready_ids
                .iter()
                .map(|id| {
                    let forecast = match (&base, branches.get(id).and_then(|b| b.clone())) {
                        (Some(base_ref), Some(branch)) => {
                            forecast_rebase_onto(&project_root, base_ref, &branch)
                        }
                        (None, _) => integrate::RebaseForecast::Unknown(
                            "no default branch (origin/main) detected".to_string(),
                        ),
                        (_, None) => integrate::RebaseForecast::Unknown(
                            "no PR branch resolved for spec".to_string(),
                        ),
                    };
                    integrate::ForecastRow {
                        id: id.clone(),
                        forecast,
                    }
                })
                .collect();
            let base_label = base.as_deref().unwrap_or("main");
            println!(
                "\n{} Rebase forecast (each PR branch onto {}, in order):",
                crate::glyph(crate::glyphs::Glyph::Arrow).cyan().bold(),
                base_label
            );
            for r in &rows {
                match &r.forecast {
                    integrate::RebaseForecast::Clean => {
                        println!(
                            "    {} {} — clean",
                            crate::glyph(crate::glyphs::Glyph::Check).green(),
                            r.id
                        );
                    }
                    integrate::RebaseForecast::Conflict(files) => {
                        let detail = if files.is_empty() {
                            String::new()
                        } else {
                            format!(": {}", files.join(", "))
                        };
                        println!(
                            "    {} {} — conflict{}",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                            r.id,
                            detail
                        );
                    }
                    integrate::RebaseForecast::Unknown(why) => {
                        println!("    {} {} — unknown ({})", "?".dimmed(), r.id, why);
                    }
                }
            }
            let s = integrate::summarize_forecast(&rows);
            if s.conflict > 0 {
                println!(
                    "  {} {} of {} will conflict — resolve {} first.",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                    s.conflict,
                    rows.len(),
                    s.conflicting_ids.join(", ")
                );
            } else if s.unknown > 0 {
                println!(
                    "  {} {} clean, {} indeterminate — re-check those before integrating.",
                    crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                    s.clean,
                    s.unknown
                );
            } else {
                println!(
                    "  {} all {} forecast clean.",
                    crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                    s.clean
                );
            }
            println!(
                "  {} forecast checks each branch against current {} independently; a member that\n    only conflicts with an earlier un-landed batch member won't show here yet (follow-up).",
                "·".dimmed(),
                base_label
            );
        }

        // TASK-842: recognize the full set of specs each ready PR will complete,
        // and dedupe by PR number across the ready set so a multi-spec cluster PR
        // — surfaced once per member spec by the Done-spec scan — is driven ONCE,
        // not N times. The merge-trailer → auto-bump path still completes every
        // trailered spec; this is recognition + dedupe + reporting only. The
        // dedupe itself is the pure `integrate::dedupe_pr_completions` over
        // (pr_number, trailered-spec-ids) rows, so it's unit-tested independently.
        // trace:TASK-842 | ai:claude
        let completion_rows: Vec<(u64, Vec<String>)> = ready_ids
            .iter()
            .filter_map(|id| {
                let pr_num = pr_numbers.get(id).and_then(|p| *p)? as u64;
                // The PR's trailered spec set, from the snapshot title (AIDA PR
                // titles carry the `(SPEC-ID)` trailers); fall back to the spec
                // the scan keyed on when the title can't be read.
                let spec_ids = branches
                    .get(id)
                    .and_then(|b| b.as_deref())
                    .and_then(|b| pr_snapshot.by_branch.get(b))
                    .map(|it| extract_spec_ids_from_commit(&it.title))
                    .filter(|v| !v.is_empty())
                    .unwrap_or_else(|| vec![id.clone()]);
                Some((pr_num, spec_ids))
            })
            .collect();
        let pr_completions = integrate::dedupe_pr_completions(&completion_rows);
        let multi_spec_pr: std::collections::HashMap<u64, integrate::PrCompletion> = pr_completions
            .into_iter()
            .filter(|c| c.spec_ids.len() > 1)
            .map(|c| (c.number, c))
            .collect();
        // Track which PR numbers we've already driven this pass — so a multi-spec
        // PR reached again via a sibling spec isn't re-driven. trace:TASK-842
        let mut integrated_pr_numbers: std::collections::HashSet<u32> =
            std::collections::HashSet::new();

        for id in &ready_ids {
            if max != 0 && integrated_total >= max {
                println!(
                    "{} reached --max {} this run; stopping.",
                    crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                    max
                );
                return Ok(());
            }
            // TASK-836: pre-merge scenario gate. Probe the richer PR facts (CI
            // state, RequestChanges, mergeability) and decide handle-vs-park
            // BEFORE driving the merge. Reuses the resilient-drain
            // park-and-continue contract: a shelvable scenario (CI red,
            // RequestChanges, conflict) parks the spec with one legible line and
            // the loop continues; CI-running waits (re-decided next --watch
            // pass). trace:TASK-836 | ai:claude
            let branch = branches.get(id).and_then(|b| b.clone());
            let pr_state =
                probe_pr_integration_state(&project_root, id, branch.as_deref(), &pr_snapshot);
            match integrate::classify_integration_action(&pr_state) {
                integrate::IntegrationAction::Park(reason) => {
                    println!("  {} {} — {}", "⏸".yellow(), id, reason.message());
                    any_parked_or_waited = true;
                    continue;
                }
                integrate::IntegrationAction::WaitCi => {
                    println!(
                        "  {} {} — CI still running; skipping this pass (will re-check)",
                        crate::glyph(crate::glyphs::Glyph::Hourglass).yellow(),
                        id
                    );
                    any_parked_or_waited = true;
                    continue;
                }
                integrate::IntegrationAction::Merge => {}
            }

            // TASK-843: a spec may have MORE than one open PR (a reopened /
            // duplicate). Before driving, list every open PR referencing the spec
            // and apply the pure newest-canonical policy: pick the newest
            // mergeable PR, report the rest as ignored-this-pass, or PARK when
            // none are clean. When only one PR is found this is a no-op (the
            // common case). The forge list is best-effort — an empty result (gh
            // missing/failing, or no title/body match) falls back to the existing
            // single-PR drive path. trace:TASK-843 | ai:claude
            let multi_prs = all_open_prs_for_spec_via_forge(&project_root, id);
            if multi_prs.len() > 1 {
                // Mergeability per candidate from the pass snapshot (CONFLICTING
                // → not mergeable; anything else admissible — the --from-pr drive
                // re-gates the irreversible merge).
                let candidates: Vec<integrate::PrCandidate> = multi_prs
                    .iter()
                    .map(|(number, branch)| {
                        let mergeable = pr_snapshot
                            .by_branch
                            .get(branch)
                            .and_then(|it| it.mergeable.as_deref())
                            .map(|m| !m.eq_ignore_ascii_case("CONFLICTING"))
                            .unwrap_or(true);
                        integrate::PrCandidate {
                            number: *number,
                            mergeable,
                        }
                    })
                    .collect();
                match integrate::select_canonical_pr(&candidates) {
                    integrate::CanonicalPrDecision::Park { candidates } => {
                        let list = candidates
                            .iter()
                            .map(|n| format!("#{n}"))
                            .collect::<Vec<_>>()
                            .join(", ");
                        println!(
                            "  {} {} — {} open PRs but none mergeable ({}); parked for triage",
                            "⏸".yellow(),
                            id,
                            candidates.len(),
                            list
                        );
                        any_parked_or_waited = true;
                        continue;
                    }
                    integrate::CanonicalPrDecision::Integrate { chosen, ignored } => {
                        if !ignored.is_empty() {
                            let list = ignored
                                .iter()
                                .map(|n| format!("#{n}"))
                                .collect::<Vec<_>>()
                                .join(", ");
                            println!(
                                "  {} {} — {} open PRs; integrating newest (#{}), ignoring this pass: {}",
                                crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                                id,
                                ignored.len() + 1,
                                chosen,
                                list
                            );
                        }
                    }
                    // 0 or 1 candidate is handled by the len()>1 guard above.
                    integrate::CanonicalPrDecision::NoPr => {}
                }
            }

            // TASK-842: dedupe drive + emit the multi-spec completion line. The
            // recognition + dedupe were computed (purely) before the loop; here
            // we (a) skip re-driving a PR already driven this pass for a sibling
            // spec, and (b) emit one legible line naming every spec the merge
            // completes. trace:TASK-842 | ai:claude
            if let Some(pr_num) = pr_numbers.get(id).and_then(|p| *p) {
                if !integrated_pr_numbers.insert(pr_num) {
                    // Already driven this pass for a sibling spec — the
                    // merge-trailer → auto-bump completes this spec too; don't
                    // re-drive the same PR.
                    println!(
                        "  {} {} — same PR (#{}) already integrating this pass for a sibling spec (skip re-drive)",
                        "·".dimmed(),
                        id,
                        pr_num
                    );
                    continue;
                }
                if let Some(completion) = multi_spec_pr.get(&(pr_num as u64)) {
                    println!(
                        "  {} {}",
                        "↩".cyan(),
                        integrate::describe_pr_completion(completion)
                    );
                }
            }

            if dry_run {
                let rebase_note = if rebase { " (would rebase first)" } else { "" };
                println!(
                    "  {} [dry-run] would drive `{}` via `aida queue work {} --auto-complete --from-pr`{}",
                    "→".dimmed(),
                    id,
                    id,
                    rebase_note
                );
                continue;
            }

            // STORY-335: rebase this member's PR branch onto current main before
            // merging it. A deferred batch cuts every branch from the same stale
            // main, so without this they would merge un-rebased. Composes the
            // existing `aida pr rebase <N> --no-smoke` primitive (temp-worktree
            // rebase + force-push-with-lease). A rebase conflict/failure skips
            // this member and continues — punt-and-continue, like the resilient
            // drain; the slice-1 --dry-run forecast previews these. The local
            // smoke is skipped because the --from-pr drive below runs CI.
            // trace:STORY-335 | ai:claude
            if rebase {
                match pr_numbers.get(id).and_then(|p| *p) {
                    Some(pr) => {
                        println!(
                            "{} rebasing `{}` (PR #{}) onto current main…",
                            "↻".cyan(),
                            id,
                            pr
                        );
                        // TASK-1050/BUG-650: rebase in the integrator's own
                        // checkout, not the (possibly advisor-leased) launch
                        // worktree. trace:TASK-1050 | ai:claude
                        let rb = std::process::Command::new(&aida)
                            .current_dir(drive_cwd)
                            .args(build_integrate_rebase_args(pr))
                            .status();
                        match rb {
                            Ok(s) if s.success() => {
                                println!(
                                    "  {} `{}` rebased onto main",
                                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                                    id
                                );
                            }
                            Ok(_) => {
                                println!(
                                    "  {} `{}` rebase failed (conflict?) — skipping; resolve with `aida pr rebase {}` then re-run",
                                    crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                                    id,
                                    pr
                                );
                                any_parked_or_waited = true; // trace:TASK-836
                                continue;
                            }
                            Err(e) => {
                                println!(
                                    "  {} `{}` rebase could not run ({e}) — skipping",
                                    crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                                    id
                                );
                                any_parked_or_waited = true; // trace:TASK-836
                                continue;
                            }
                        }
                    }
                    None => {
                        // Defensive: ready members have an open PR, so a number
                        // should resolve. If it somehow doesn't, integrate as-is
                        // rather than skip — the --from-pr drive still gates on CI.
                        println!(
                            "  {} `{}` — --rebase set but no PR number resolved; integrating without rebase",
                            "·".dimmed(),
                            id
                        );
                    }
                }
            }

            println!(
                "{} integrating `{}` (reviewer → CI → merge → pull → build)…",
                "↩".cyan().bold(),
                id
            );
            // TASK-1050/BUG-650: drive in the integrator's OWN checkout so the
            // merge work never sits in (or lease-contends) a live session's
            // worktree. Because the drive runs in a linked worktree, its
            // `find_main_worktree_root()` drain lock targets MAIN — the very lock
            // THIS integrate run already holds. Authorize the delegated sub-drive
            // past that self-conflict with the force escape (env-scoped to the
            // child only); a genuinely independent drain never inherits it and is
            // still refused, so the repo-wide one-authority invariant holds.
            // trace:TASK-1050 trace:BUG-650 | ai:claude
            // ONE per-spec orchestration engine (ADR-7): integrate hands the
            // spec to the SAME `--auto-complete` engine, entering at the
            // reviewer phase via `--from-pr`. The routing argv is a pure helper
            // so the `orchestration_routing` guardrail can assert it.
            // trace:ADR-7 trace:ADR-9 | ai:claude
            let status = std::process::Command::new(&aida)
                .current_dir(drive_cwd)
                .env("AIDA_DRAIN_FORCE", "1")
                // BUG-748: this is an internal child drive launched under the
                // integrator's existing drain lock. Borrow that parent lock so
                // the child does not overwrite and release `.aida/drain.lock`
                // before the parent loop finishes. trace:BUG-748 | ai:codex
                .env("AIDA_DRAIN_BORROW", "1")
                .args(integrate::drive_args(id))
                .status();
            match status {
                Ok(s) if s.success() => {
                    integrated_total += 1;
                    println!(
                        "  {} `{}` integrated",
                        crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                        id
                    );
                }
                Ok(s) => {
                    // A non-zero exit means the drive shelved/refused this spec
                    // (CI red, RequestChanges, already-merged race, …). Leave it
                    // visible and move on — the serial loop must not stall on one
                    // spec. trace:STORY-520 | ai:claude
                    eprintln!(
                        "  {} `{}` did not integrate cleanly (exit {}); leaving for triage and continuing",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                        id,
                        s.code().unwrap_or(-1)
                    );
                    any_parked_or_waited = true; // trace:TASK-836
                }
                Err(e) => {
                    eprintln!(
                        "  {} failed to launch the drive for `{}`: {}",
                        crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                        id,
                        e
                    );
                    any_parked_or_waited = true; // trace:TASK-836
                }
            }
        }

        if !watch {
            break;
        }
        if max != 0 && integrated_total >= max {
            break;
        }
        // TASK-1036: event-driven wake. Instead of a blind `interval` sleep, BLOCK
        // until a focus-relevant actionable drain event lands in
        // `.aida/events.jsonl` (PhaseDonePr / CiTerminal / PrMerged / SpecShelved
        // — the same `events::is_actionable` taxonomy `aida watch` and the advisor
        // loop use), the idle backstop elapses (the old blind timer, now the
        // documented fallback — exactly like `advisor_watch::plan_watch_tick`'s
        // cadence path), or a live drain we were following stops. The store reload
        // at the top of the loop then picks up whatever shipped. trace:TASK-1036
        match event_wait::wait_for_actionable(
            &project_root,
            &mut event_offset,
            idle_backstop_secs,
            focus_subtree.as_ref(),
        ) {
            event_wait::WakeReason::Event(kind) => {
                let label = match &kind {
                    crate::events::EventKind::PhaseDonePr { .. } => "a PR is ready",
                    crate::events::EventKind::CiTerminal { .. } => "CI reached a verdict",
                    crate::events::EventKind::PrMerged { .. } => "a PR merged",
                    crate::events::EventKind::SpecShelved { .. } => "a spec shelved",
                    _ => "a drain event",
                };
                println!(
                    "  {} woke on {} — rescanning",
                    crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                    label
                );
            }
            event_wait::WakeReason::DrainCrashed => {
                println!(
                    "  {} the drain we were following stopped streaming events — rescanning",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                );
            }
            event_wait::WakeReason::IdleBackstop => {
                // Quiet idle re-scan — same cadence the old blind timer gave.
            }
        }
    }

    // TASK-836: mirror the resilient-drain exit-code contract — exit 2 when any
    // member was parked (CI red / RequestChanges / conflict / rebase-skip /
    // drive-refused) or made to wait (CI running), so a wrapping script (the
    // solo loop) treats the run as "did its job but triage pending" rather than
    // a clean success. Dry-run never mutates, so it always exits 0. The drain
    // guard is RAII (Drop), and process::exit skips destructors — so drop it
    // explicitly first to release the lock cleanly. trace:TASK-836 | ai:claude
    if !dry_run && any_parked_or_waited {
        println!(
            "{} integration left member(s) parked/waiting — triage with `aida findings list`, then re-run.",
            crate::glyph(crate::glyphs::Glyph::Arrow).yellow().bold()
        );
        drop(_drain_guard);
        std::process::exit(2);
    }

    Ok(())
}

/// STORY-384: short human label for a recovery action (the recommendation
/// headline). The longer "why" is [`queue_recover::RecoverAction::rationale`].
/// trace:STORY-384 | ai:claude
fn recover_action_label(action: queue_recover::RecoverAction) -> &'static str {
    use queue_recover::RecoverAction as A;
    match action {
        A::AlreadyCompleted => "already completed — nothing to recover",
        A::AlreadyMergedPull => "pull to auto-bump the merged PR",
        A::DrivePhasesFromPr => "drive phases 3-6 on the open PR",
        A::PushOpenPrDrive => "push + open PR + drive phases 3-6",
        A::WipCommitPushDrive => "commit WIP + push + open PR + drive phases 3-6",
        A::WipCommitPark => "commit WIP and park for resumption",
        A::EndAndRequeue => "end the lease and re-queue",
    }
}

/// Entry point for `aida queue work <SPEC> --auto-complete`. Never returns:
/// always terminates the process with an exit code (0 success, 1-6 = the
/// 1-based index of the phase that failed). trace:STORY-246 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_auto_complete(
    storage: &Storage,
    user_id: &str,
    spec: &str,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<&str>,
    no_human: Option<auto_complete::NoHumanMode>,
    escalate_mode: auto_complete::EscalateMode,
    // BUG-311: thread the outer `--steal` through so phase 1's
    // `aida queue work` subprocess can clear a dormant lease on this scope.
    steal: bool,
    // TASK-559: thread the outer `--force-claim` through so phase 1 can
    // recover NeedsAttention / ambiguous InProgress specs the same way a
    // direct `aida queue work <SPEC> --force-claim` does.
    force_claim: bool,
    // STORY-281: thread the outer `--allow-stale-base` through so phase 3's
    // pre-flight stale-base check warns-only instead of refusing.
    allow_stale_base: bool,
    // STORY-429: opt out of phase-3 auto-rebase recovery.
    no_auto_rebase: bool,
) -> ! {
    let result = run_auto_complete(
        storage,
        user_id,
        spec,
        variant,
        json,
        permission_mode,
        no_human,
        escalate_mode,
        // STORY-301: a bare single-spec drain owns its drain-state file.
        true,
        steal,
        force_claim,
        allow_stale_base,
        no_auto_rebase,
        // STORY-492: not a resume — start at phase 1.
        None,
    );
    // STORY-493: drain-end mailbox digest for the single-spec drain, matching
    // the batch / batch-chain paths. Best-effort + non-fatal. trace:STORY-493
    if let Ok(root) = find_main_worktree_root() {
        maybe_digest_mailbox_best_effort(&root.join(".aida-store"), "drain-end");
    }
    // TASK-1054: collapse the failed-phase index to the canonical 0/2/3 process
    // code (0 clean, 2 shelved/parked, 3 hard fail) so a wrapping script can
    // branch on the outcome. trace:TASK-1054 | ai:claude
    std::process::exit(result.process_exit_code());
}

/// STORY-265 slice 3: execute the `--with-plan` PLAN PRELUDE for one spec —
/// the plan phase that runs before the auto-complete drain's phase 1. Reuses
/// slice 2's `aida queue work <spec> --plan-only` planning session (headless
/// when the drain runs a headless implementer) and slice 1's
/// `aida plan promote <spec>` Approved→Planned transition, in that order
/// (decided by [`auto_complete::plan_prelude_steps`]). The drain itself is
/// entered unchanged after this returns `Ok`; the Phase enum is untouched (the
/// prelude is NOT a renumbered phase). Each step shells out to the current
/// `aida` binary; a non-zero exit aborts the prelude so the caller skips the
/// drain. trace:STORY-265 | ai:claude
fn run_plan_prelude(spec: &str, headless_implementer: bool, json: bool) -> Result<()> {
    use auto_complete::PlanPreludeStep;
    let exe = std::env::current_exe().context("could not resolve the aida binary path")?;
    let steps = auto_complete::plan_prelude_steps(spec, true, headless_implementer);
    if !json {
        eprintln!();
        eprintln!(
            "{} {} {}",
            "📝".bold(),
            format!("plan prelude: {spec}").bold(),
            "(plan phase → promote → drain)".dimmed()
        );
    }
    for step in steps {
        match step {
            PlanPreludeStep::PlanSession { spec: s, headless } => {
                let mut args: Vec<String> = vec![
                    "queue".into(),
                    "work".into(),
                    s.clone(),
                    "--plan-only".into(),
                ];
                if headless {
                    // Mirror the phase-1 headless implementer launch onto the
                    // plan session so a `--no-human=both` drain plans headless
                    // too. trace:STORY-265 | ai:claude
                    args.push("--no-human".into());
                }
                let status = std::process::Command::new(&exe)
                    .args(&args)
                    .status()
                    .with_context(|| format!("could not launch the plan session for {s}"))?;
                if !status.success() {
                    anyhow::bail!(
                        "the plan session exited with status {} — no plan file was produced",
                        status.code().unwrap_or(-1)
                    );
                }
            }
            PlanPreludeStep::Promote { spec: s } => {
                let status = std::process::Command::new(&exe)
                    .args(["plan", "promote", &s])
                    .status()
                    .with_context(|| format!("could not run `aida plan promote {s}`"))?;
                if !status.success() {
                    anyhow::bail!(
                        "`aida plan promote {s}` exited with status {} — the spec was not \
                         promoted to Planned (does the plan file's `Specs:` header list {s}?)",
                        status.code().unwrap_or(-1)
                    );
                }
            }
        }
    }
    Ok(())
}

/// Run one `--auto-complete` orchestration and return its result *without*
/// exiting the process — so a batch drain (TASK-285) can chain runs. Handles
/// the preflight queue, the real driver, and the TASK-266 telemetry record.
/// Hard environment errors (project root unresolvable, preflight queue-add
/// failed) still exit the process directly — they would recur identically on
/// every batch iteration. trace:STORY-246, TASK-285 | ai:claude
#[allow(clippy::too_many_arguments)]
fn run_auto_complete(
    storage: &Storage,
    user_id: &str,
    spec: &str,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<&str>,
    no_human: Option<auto_complete::NoHumanMode>,
    // STORY-306: how an advisor escalation is handled — `Blocks` (default) or
    // `Defaults`. Only meaningful under `--no-human=both`.
    escalate_mode: auto_complete::EscalateMode,
    // STORY-301: `true` for a standalone single-spec drain — this run creates
    // the `.aida/drain-state.json` file and clears it on return. `false` for a
    // batch / nextN member — the batch orchestrator owns the file; this run
    // only announces it is the current spec.
    owns_drain_state: bool,
    // BUG-311: pass-through of the outer `--steal` flag — appended to the
    // phase-1 `aida queue work` subprocess so it can clear a dormant lease
    // on this scope. Without this thread-through the outer flag silently
    // dropped on the floor and the canned "pass --steal" message recurred.
    // trace:BUG-311 | ai:claude
    steal: bool,
    // TASK-559: pass-through of the outer `--force-claim` flag, appended to
    // phase-1 `aida queue work` subprocesses just like `--steal`.
    force_claim: bool,
    // STORY-281: pass-through of the outer `--allow-stale-base` flag. When
    // true, phase 3's pre-flight check warns-only instead of refusing on a
    // stale-base + file-overlap; also propagated to the reviewer subprocess.
    // trace:STORY-281 | ai:claude
    allow_stale_base: bool,
    // STORY-429: pass-through of the outer `--no-auto-rebase` flag. When
    // false, fully-headless phase 3 can attempt one clean PR rebase before
    // falling back to STORY-281 refusal.
    no_auto_rebase: bool,
    // STORY-492: `None` for a normal drain (start at phase 1, run everything).
    // `Some` for a `--resume-drain` re-entry — carries the reconciled
    // `start_phase` (skip earlier phases) plus the branch + PR to seed into the
    // driver so the resumed phases have the context the skipped phases would
    // have discovered. trace:STORY-492 | ai:claude
    resume: Option<ResumeEntry>,
) -> auto_complete::OrchestrationResult {
    // BUG-657: a spec that is already terminal (Completed / Rejected) is a clean
    // NO-OP — return BEFORE touching the queue or spawning anything. Driving it
    // would queue it, spawn an implementer that exits 1 ("nothing to implement"),
    // and auto-draft a phantom failure BUG — the BUG-638 → BUG-644..649 incident
    // (6 identical drafts in 6 minutes). A `--resume` / `--from-pr` re-entry
    // (`resume.is_some()`) is exempt: it legitimately re-drives a spec that
    // reached Completed mid-pipeline (the merge promoted it; the BUG-241 reconcile
    // treats that as an out-of-band success). The pure orchestrator carries the
    // same guard via `PhaseDriver::terminal_status` for defense-in-depth + unit
    // testing; this earlier check is what keeps the queue side-effect-free.
    // trace:BUG-657 | ai:claude
    if resume.is_none() {
        if let Ok(root) = find_main_worktree_root() {
            let terminal = match spec_status(&root, spec) {
                Some(RequirementStatus::Completed) => Some("Completed"),
                Some(RequirementStatus::Rejected) => Some("Rejected"),
                _ => None,
            };
            if let Some(status) = terminal {
                return auto_complete::finish_noop(spec, status, json, &std::time::Instant::now());
            }
        }
    }
    // Preflight: `aida queue work <spec>` can only pick up a spec that's
    // queued for the implementer. Queue it if it isn't — so a fresh
    // `aida add` flows straight into `--auto-complete`.
    if let Err(e) = ensure_queued_for_implementer(storage, user_id, spec) {
        eprintln!(
            "{} {}",
            crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
            e
        );
        std::process::exit(1);
    }
    // STORY-265 slice 3: the `--with-plan` PLAN PRELUDE. When `--with-plan` is
    // set (propagated as `AIDA_WITH_PLAN=1` by the dispatch arm), run a plan
    // session + Approved→Planned promote BEFORE the phase-1 status bump and the
    // drain. This is a prelude, NOT a renumbered phase — the 6-phase drain
    // below is entered unchanged, so the Phase enum's index-as-exit-code
    // contract is preserved. The prelude runs once per drained spec (single /
    // batch / nextN all route through here). A prelude failure aborts this
    // spec's run before any work is bumped/leased. trace:STORY-265 | ai:claude
    if std::env::var("AIDA_WITH_PLAN").is_ok() {
        let headless_implementer = no_human
            .map(auto_complete::NoHumanMode::wants_headless_implementer)
            .unwrap_or(false);
        if let Err(e) = run_plan_prelude(spec, headless_implementer, json) {
            eprintln!(
                "{} plan prelude failed for {}: {} — the drain did not start \
                 (re-run, or drop --with-plan to implement without a plan phase)",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                spec,
                e
            );
            return auto_complete::OrchestrationResult::failed(auto_complete::Phase::Implementer);
        }
    }
    // TASK-133: capture the pre-spawn status bump (BUG-369) so the parent can
    // restore it if phase 1 fails without the child ever acquiring a lease.
    // `Some((display_id, prior_status))` when a flip happened; `None` when the
    // spec was already InProgress/Planned and the parent left it untouched.
    let phase1_bump = match prepare_auto_complete_phase1_status(storage, spec) {
        Ok(b) => b,
        Err(e) => {
            eprintln!(
                "{} {}",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                e
            );
            std::process::exit(1);
        }
    };
    let lifecycle_skip = match resolve_lifecycle_skip(storage, spec) {
        Ok(s) => s,
        Err(e) => {
            eprintln!(
                "{} {}",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                e
            );
            std::process::exit(1);
        }
    };

    let project_root = match find_main_worktree_root() {
        Ok(p) => p,
        Err(e) => {
            eprintln!(
                "{} could not resolve the project root: {}",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                e
            );
            std::process::exit(1);
        }
    };

    // STORY-263 / TASK-306 / STORY-276: a one-line per-run reminder of the
    // headless scope. The loud scope banner + acknowledgement already fired
    // once at kickoff (`no_human_kickoff_gate`); this keeps the scope visible
    // in a batch drain's per-member scrollback. The wording follows the mode:
    // `both` runs phase 1 headless (with the punt safety net), `reviewer-only`
    // leaves it interactive. trace:STORY-263, TASK-306, STORY-276 | ai:claude
    if let Some(mode) = no_human {
        if !json {
            if mode.wants_headless_implementer() {
                eprintln!(
                    "  {} headless implementer + reviewer — phase 1 punts to \
                     Needs Attention on a design-fork it cannot resolve",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan()
                );
            } else {
                eprintln!(
                    "  {} headless reviewer phase — phase 1 (implementer) stays \
                     interactive and will pause for you",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan()
                );
            }
        }
    }

    // BUG-233 / TASK-336: mint this orchestrator run's corroboration UUID and
    // persist it into the drain-state file. A phase child carrying
    // `AIDA_AUTO_COMPLETE_TOKEN=<uuid>` corroborates orchestrator-mode against
    // `DrainState::run_uuid` + a `pid_is_alive` check on the recorded
    // orchestrator PID. Before TASK-336 this lived in a sidecar
    // `.aida/orchestrator-runs/<uuid>` marker file; that file has been removed
    // since the drain-state file already records every other field the check
    // needs. trace:BUG-233 trace:TASK-336 | ai:claude
    //
    // ADR-7/ADR-10: resolve this run's autonomy ONCE into a typed value (the
    // single in-process source of truth) rather than re-reading `AIDA_ZEN` as a
    // bare env bool. `for_auto_complete_run` unifies the `--no-human` mode and
    // the `--zen` intent token; it preserves the BUG-237 guarantee that a
    // leaked `AIDA_ZEN=1` (no token) is not recorded as a zen run. The env var
    // stays as the cross-process transport to phase children / skill templates.
    // trace:ADR-7 trace:ADR-10 trace:BUG-237 | ai:claude
    let autonomy = AutonomyMode::for_auto_complete_run(no_human);
    let run_token = uuid::Uuid::now_v7().to_string();

    // ADR-10: build the driver FIRST, carrying the resolved-once typed
    // `autonomy` alongside `no_human`, so the drain-state stamping below reads
    // the carried field (`driver.is_zen_run()`) rather than re-deriving zen-ness
    // from a bare `AIDA_ZEN` env read. The env var stays as the cross-process
    // transport to phase children / skill templates. trace:ADR-10 | ai:claude
    let mut driver = RealPhaseDriver::new(
        project_root.clone(),
        spec.to_string(),
        permission_mode.map(|s| s.to_string()),
        json,
        no_human,
        autonomy,
        run_token.clone(),
        steal,
        force_claim,
        allow_stale_base,
        no_auto_rebase,
        lifecycle_skip,
        variant,
    );

    // STORY-301: surface the drain so a user inside the spawned Claude session
    // can see what command launched it, how far it has got, and what happens
    // when they exit. A single-spec drain owns the file — it writes it now
    // with the run-UUID + zen flag baked in, and clears it on return; a batch
    // / nextN member updates the existing file's run-fields via `set_run` (the
    // batch orchestrator created the file before this member started).
    // Best-effort: a write failure leaves the drain running, just unobservable
    // — and crucially, phase children correctly fall back to treating
    // themselves as interactive when the corroboration check finds no live
    // drain-state. The zen flag is the carried typed field, not a bare env
    // re-read (ADR-10). trace:STORY-301 trace:TASK-336 trace:ADR-10 | ai:claude
    let run_zen = driver.is_zen_run();
    if owns_drain_state {
        let _ = drain_state::DrainState::new_single(spec, &run_token, run_zen).write(&project_root);
    } else {
        drain_state::set_run(&project_root, spec, &run_token, run_zen);
    }
    // STORY-492: a resume re-entry seeds the driver with the branch + PR the
    // skipped phases would otherwise have discovered, so the resumed phases
    // (CI / reviewer / merge / …) have the context they need.
    let start_phase = match &resume {
        Some(r) => {
            driver.seed_resume_state(r.branch.clone(), r.pr);
            r.start_phase
        }
        None => auto_complete::Phase::Implementer,
    };
    let started_at = chrono::Utc::now();
    // TASK-136: a batch / nextN member (`owns_drain_state == false`) shelves a
    // still-inconclusive phase-1 verify so the drain advances; a standalone
    // single-spec drain keeps the Inconclusive pause. The two are exact
    // inverses, so `batch` derives directly from `owns_drain_state`.
    let batch = !owns_drain_state;
    // TASK-827: solo mode as a max-discretion safe-backlog POSTURE. When solo is
    // active (`presence::current_solo`), fold it into this spec's escalate
    // behaviour per-spec: SAFE work proceeds on the defensible default
    // (ProceedOnDefault → Defaults — maximum discretion), KEYSTONE/architecture
    // work parks for the human (ParkForHuman → Blocks — never ship keystone
    // unattended). Reuses the existing escalate mechanism + park path; when solo
    // is inactive the posture is `Inactive` and `escalate_mode` is UNCHANGED, so
    // non-solo behaviour is untouched. Only meaningful under `--no-human=both`
    // where the advisor escalation tier runs. trace:TASK-827 | ai:claude
    let escalate_mode = {
        // The advisor escalation tier (where `escalate_mode` is consulted) only
        // runs under `--no-human=both`; gate the posture there so a non-headless
        // solo drain neither prints a misleading banner nor flips a no-op flag.
        let advisor_tier_runs = no_human == Some(auto_complete::NoHumanMode::Both);
        let solo_active = advisor_tier_runs && presence::current_solo(chrono::Utc::now());
        let is_keystone = solo_active && solo_spec_is_keystone(storage, spec);
        let posture = presence::resolve_solo_posture(solo_active, is_keystone);
        if posture.is_active() {
            if !json {
                if matches!(posture, presence::SoloPosture::ParkForHuman) {
                    eprintln!(
                        "  {} solo posture: working safe backlog, parking keystone for human ({} classified keystone — parks on a design-fork)",
                        crate::glyph(crate::glyphs::Glyph::Robot).bold(),
                        spec
                    );
                } else {
                    eprintln!(
                        "  {} solo posture: working safe backlog, parking keystone for human ({} is safe — proceeds on the defensible default)",
                        crate::glyph(crate::glyphs::Glyph::Robot).bold(),
                        spec
                    );
                }
            }
            auto_complete::EscalateMode::from_flags(posture.escalate_defaults())
        } else {
            escalate_mode
        }
    };
    let result = auto_complete::orchestrate_with_resume(
        &mut driver,
        spec,
        variant,
        json,
        escalate_mode,
        lifecycle_skip,
        batch,
        start_phase,
    );
    let completed_at = chrono::Utc::now();

    // TASK-133: compensate the pre-spawn phase-1 status bump. If phase 1
    // failed *and* the implementer child never recorded a lease, no work
    // happened — restore the captured prior status (clearing the spurious
    // shelve `failure_reason`) so the spec is cleanly re-queueable rather than
    // stranded InProgress→NeedsAttention behind a transient spawn/contention
    // error. A lease-acquired or later-phase failure leaves real work to
    // triage and is left shelved. trace:TASK-133 | ai:claude
    if let Some((display_id, prior)) = &phase1_bump {
        let lease_acquired = driver.implementer_lease.is_some();
        if auto_complete::should_compensate_phase1_bump(true, lease_acquired, result.failed_phase) {
            match restore_phase1_status_on_lease_failure(&project_root, spec, prior) {
                Ok(()) => {
                    if !json {
                        eprintln!(
                            "  {} phase-1 startup failed before acquiring a lease — \
                             status restored to {:?} (re-queueable); no work was stranded",
                            "↩".cyan(),
                            prior
                        );
                    }
                }
                Err(e) => {
                    eprintln!(
                        "  {} could not restore {}'s status after a lease-less phase-1 \
                         failure: {} — reset it manually with `aida edit {} --status {}`",
                        crate::glyph(crate::glyphs::Glyph::Info).cyan(),
                        display_id,
                        e,
                        display_id,
                        format!("{prior:?}").to_lowercase(),
                    );
                }
            }
        }
    }

    // TASK-336: the run-UUID is no longer needed once `orchestrate` has
    // returned — every phase child has been spawned and reaped. Clear it on
    // the drain-state file so a would-be straggler child carrying this token
    // no longer corroborates against the file (especially between batch
    // members, where the file lives on until the batch ends). For a single-
    // spec drain the file is removed entirely just below; this clear is
    // belt-and-braces in case the removal races a final child probe.
    drain_state::clear_run(&project_root);

    // TASK-266: log the run to `~/.aida/auto-complete.jsonl` and, on a phase
    // failure, auto-draft a Draft BUG so the friction surfaces back to the
    // project instead of dying in scrollback. Best-effort — never blocks the
    // exit. trace:TASK-266 | ai:claude
    // STORY-301: stamp this member's terminal state — completed / failed plus
    // the PR a phase discovered — into the drain-state file. For a batch drain
    // this leaves a member-by-member trail; for a single drain the file is
    // cleared just below, so this update only matters mid-run.
    drain_state::set_member_outcome(
        &project_root,
        spec,
        result.exit_code == 0,
        auto_complete::PhaseDriver::hint_context(&driver).pr_number,
    );

    record_auto_complete_run(
        &driver,
        &project_root,
        spec,
        variant,
        &result,
        started_at,
        completed_at,
        json,
        lifecycle_skip,
    );

    // STORY-301: a single-spec drain owns the file — clear it now the run is
    // over. A clean exit removes the file; only a crash leaves it behind for
    // `aida drain status` to flag as a stale drain. trace:STORY-301
    //
    // BUG-438: but a *resume* that FAILED at a phase must KEEP the drain-state,
    // or the operator can't `--resume-drain` again after fixing the blocker —
    // the checkpoint would be consumed on failure. A resume that succeeded
    // clears it (the work is done); a non-resume drain clears as before.
    // trace:BUG-438 | ai:claude
    if owns_drain_state {
        if should_clear_drain_state(owns_drain_state, resume.is_some(), result.exit_code) {
            let _ = drain_state::DrainState::clear(&project_root);
        } else if !json {
            eprintln!(
                "  {} keeping drain-state — fix the blocker, then re-run \
                 `aida queue work --auto-complete --resume-drain`",
                crate::glyph(crate::glyphs::Glyph::Info).cyan()
            );
        }
    }

    result
}

/// BUG-438: should a finished single-spec drain clear its `drain-state.json`?
/// Clear when this run owns the file AND it is not a *failed resume* — a resume
/// that failed keeps the checkpoint so the operator can fix the blocker and
/// `--resume-drain` again, rather than the checkpoint being consumed on
/// failure. A successful resume (work done) and any non-resume drain clear as
/// before. Pure so the rule is unit-pinned. trace:BUG-438 | ai:claude
fn should_clear_drain_state(owns_drain_state: bool, is_resume: bool, exit_code: i32) -> bool {
    owns_drain_state && !(is_resume && exit_code != 0)
}

#[cfg(test)]
#[path = "tests/drain_state_clear_tests.rs"]
mod drain_state_clear_tests;

/// Resolve the queued members of a `batch:NAME` tag in pickup order, filtered
/// to the active role. Terminal items (Completed/Rejected) are dropped — they
/// are already shipped. Returns `(entry, display_id, title, status)` tuples.
/// Shared by the plain `--batch` head-pickup path and the TASK-285
/// `--batch --auto-complete` drain. trace:TASK-229, TASK-285 | ai:claude
fn resolve_batch_members(
    storage: &Storage,
    user_id: &str,
    batch_name: &str,
    role: Option<&str>,
) -> Result<
    Vec<(
        aida_core::QueueEntry,
        String,
        String,
        aida_core::RequirementStatus,
    )>,
> {
    let store = storage.load()?;
    let entries = storage.queue_list(user_id, false)?;
    let want = format!("batch:{}", batch_name);
    let session_role = std::env::var("AIDA_SESSION_ROLE").ok();
    let (role_filter, _only_unrouted) =
        resolve_queue_role_filter(role, false, session_role.as_deref());
    let mut members: Vec<(
        aida_core::QueueEntry,
        String,
        String,
        aida_core::RequirementStatus,
    )> = Vec::new();
    for entry in entries {
        if !entry_matches_role_filter(entry.for_role.as_deref(), role_filter.as_deref(), false) {
            continue;
        }
        let Some(req) = store
            .requirements
            .iter()
            .find(|r| r.id == entry.requirement_id)
        else {
            continue;
        };
        if !req.tags.iter().any(|t| t.eq_ignore_ascii_case(&want)) {
            continue;
        }
        // Skip terminal items (Completed/Rejected); they're already shipped
        // and don't need draining.
        if is_terminal_status(&req.status) {
            continue;
        }
        // STORY-332 / EPIC-28: a NeedsAttention spec is paused awaiting
        // triage — either a design-fork punt or an orchestrator-shelved
        // phase failure. The orchestrator must never re-pick it; doing so
        // would either loop on the same failure (the shelve case) or
        // commit a guess (the punt case). Mirrors `queue next`'s
        // STORY-332 filter so every batch surface gets the same skip.
        // The dropped member is reported to stderr so the operator sees
        // the batch shrank and why. trace:STORY-332 EPIC-28 | ai:claude
        if matches!(req.status, RequirementStatus::NeedsAttention) {
            let reason_label = match req
                .failure_reason
                .as_ref()
                .map(|fr| format!("shelved (failure:{})", fr.phase))
            {
                Some(label) => label,
                None => req
                    .attention_reason
                    .as_ref()
                    .map(|ar| format!("punted ({})", ar.category))
                    .unwrap_or_else(|| "needs attention".to_string()),
            };
            eprintln!(
                "  {} batch:{} — skipping {} ({})",
                crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                batch_name,
                req.display_id(),
                reason_label,
            );
            continue;
        }
        // STORY-333: skip un-pickable members so the batch drain never
        // spawns a doomed phase-1 implementer on a blocked-by /
        // human-only spec. The dropped members are reported to stderr
        // so the operator sees the batch shrank and why.
        // trace:STORY-333 | ai:claude
        match aida_core::pickability::pickability(req, &store) {
            aida_core::pickability::Pickability::Pickable => {}
            aida_core::pickability::Pickability::Blocked(reason) => {
                eprintln!(
                    "  {} batch:{} — skipping un-pickable member {} ({})",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    batch_name,
                    req.display_id(),
                    aida_core::pickability::pickability_reason_label(&reason),
                );
                continue;
            }
        }
        members.push((
            entry,
            req.display_id(),
            req.title.clone(),
            req.status.clone(),
        ));
    }
    Ok(members)
}

/// Real [`auto_complete::BatchDriver`] — re-resolves the `batch:NAME` head
/// against the live queue and runs each member's full `--auto-complete`
/// lifecycle. trace:TASK-285 | ai:claude
struct RealBatchDriver<'a> {
    storage: &'a Storage,
    user_id: String,
    batch_name: String,
    role: Option<String>,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<String>,
    /// STORY-263: headless mode, propagated to every member's
    /// `run_auto_complete`.
    no_human: Option<auto_complete::NoHumanMode>,
    /// STORY-306: advisor-escalation mode, propagated to every member.
    escalate_mode: auto_complete::EscalateMode,
    /// BUG-311: outer `--steal` flag, propagated to every member's phase-1
    /// subprocess so a dormant lease on the member's scope is cleared rather
    /// than blocking the drain with the canned "pass --steal" message.
    steal: bool,
    /// TASK-559: outer `--force-claim` flag, propagated to every member's
    /// phase-1 subprocess so ambiguous spec status can be claimed.
    force_claim: bool,
    /// STORY-281: outer `--allow-stale-base` flag, propagated to every
    /// member's phase-3 pre-flight check so the stale-base + overlap
    /// signal becomes a warning instead of a refusal.
    allow_stale_base: bool,
    /// STORY-429: outer `--no-auto-rebase` flag, propagated to every member.
    no_auto_rebase: bool,
    // TASK-966: project root + drain-start for the `--max-tokens` meter. `None`
    // when no token cap is active. trace:TASK-966 | ai:claude
    token_meter: Option<(std::path::PathBuf, std::time::SystemTime)>,
}

impl auto_complete::BatchDriver for RealBatchDriver<'_> {
    fn next_head(&mut self) -> Option<String> {
        match resolve_batch_members(
            self.storage,
            &self.user_id,
            &self.batch_name,
            self.role.as_deref(),
        ) {
            Ok(members) => members.into_iter().next().map(|m| m.1),
            Err(e) => {
                // A store/queue read failure is not "batch drained" — surface
                // it and stop rather than reporting a false clean drain.
                eprintln!(
                    "{} could not resolve batch members: {}",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    e
                );
                std::process::exit(1);
            }
        }
    }

    fn run_spec(&mut self, spec: &str) -> auto_complete::OrchestrationResult {
        // BUG-660: retry a transient/retryable per-spec failure (locked cache,
        // GH-API blip) through an exponential backoff instead of hammering or
        // immediately shelving — an unattended drive rides out a brief blip.
        // trace:BUG-660 | ai:claude
        drive_robustness::run_with_transient_backoff(|| {
            run_auto_complete(
                self.storage,
                &self.user_id,
                spec,
                self.variant,
                self.json,
                self.permission_mode.as_deref(),
                self.no_human,
                self.escalate_mode,
                // STORY-301: a batch / nextN member does not own the drain-state
                // file — the batch orchestrator created it.
                false,
                self.steal,
                self.force_claim,
                self.allow_stale_base,
                self.no_auto_rebase,
                None,
            )
        })
    }

    // TASK-966: cumulative reported tokens across this drain's headless logs.
    fn cumulative_tokens(&mut self) -> u64 {
        match &self.token_meter {
            Some((root, since)) => sum_headless_log_tokens(root, *since),
            None => 0,
        }
    }
}

/// Entry point for `aida queue work --batch NAME --auto-complete` (TASK-285).
/// Drains the whole batch — one full `--auto-complete` lifecycle per member,
/// advancing the head after each — until the batch is empty, `--max` is
/// reached, or a phase fails. Never returns: exits `0` on a clean drain, else
/// the failed-phase index (per STORY-246's exit codes). trace:TASK-285
#[allow(clippy::too_many_arguments)]
fn handle_auto_complete_batch(
    storage: &Storage,
    user_id: &str,
    batch_name: &str,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<&str>,
    role: Option<&str>,
    max: Option<usize>,
    // EPIC-28: outer `--max-failures` cap — after this many phase failures
    // shelve in a single batch, stop the drain entirely (the env is
    // probably broken). `None` falls back to the built-in default (5).
    // trace:EPIC-28 | ai:claude
    max_failures: Option<usize>,
    no_human: Option<auto_complete::NoHumanMode>,
    escalate_mode: auto_complete::EscalateMode,
    // BUG-311: outer `--steal`, threaded to every batch member's phase 1.
    steal: bool,
    // TASK-559: outer `--force-claim`, threaded to every batch member's phase 1.
    force_claim: bool,
    // STORY-281: outer `--allow-stale-base`, threaded to every batch
    // member's phase 3 pre-flight stale-base check.
    allow_stale_base: bool,
    // STORY-429: outer `--no-auto-rebase`, threaded to every batch member.
    no_auto_rebase: bool,
    // TASK-966: hard budget caps for the whole drain. trace:TASK-966 | ai:claude
    caps: &drain_caps::DrainCaps,
) -> ! {
    if !json {
        eprintln!();
        eprintln!(
            "{} {} {}",
            "🚀".bold(),
            format!("auto-complete batch: batch:{batch_name}").bold(),
            format!("({})", variant.describe()).dimmed()
        );
        if let Some(limit) = max {
            eprintln!(
                "  {} drain capped at {} item{}",
                crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                limit,
                if limit == 1 { "" } else { "s" }
            );
        }
    }

    // STORY-301: write the drain-state file so `aida drain status` can show
    // the batch, its members, the current position, and what happens on exit.
    // Best-effort — a resolution / write failure leaves the drain running,
    // just unobservable. trace:STORY-301 | ai:claude
    let drain_root = find_main_worktree_root().ok();
    if let Some(root) = &drain_root {
        if let Ok(members) = resolve_batch_members(storage, user_id, batch_name, role) {
            let specs: Vec<String> = members.into_iter().map(|m| m.1).collect();
            let _ = drain_state::DrainState::new_batch(batch_name, &specs).write(root);
        }
    }

    // TASK-967: drain origin (wall clock + base HEAD) for the exit summary.
    // trace:TASK-967 | ai:claude
    let drain_started = std::time::SystemTime::now();
    let drain_clock = std::time::Instant::now();
    let drain_base_sha = drain_root.as_deref().and_then(current_branch_head_sha);
    // TASK-966: arm the token meter only when a `--max-tokens` cap is set.
    let token_meter = caps
        .max_tokens
        .and(drain_root.clone())
        .map(|root| (root, drain_started));
    let mut driver = RealBatchDriver {
        storage,
        user_id: user_id.to_string(),
        batch_name: batch_name.to_string(),
        role: role.map(|s| s.to_string()),
        variant,
        json,
        permission_mode: permission_mode.map(|s| s.to_string()),
        no_human,
        escalate_mode,
        steal,
        force_claim,
        allow_stale_base,
        no_auto_rebase,
        token_meter,
    };
    // EPIC-28: a `None` `--max-failures` from the CLI means "use the
    // built-in default cap" — set here so the orchestrator never runs
    // with an unbounded failure budget. trace:EPIC-28 | ai:claude
    let max_failures = max_failures.or(Some(DEFAULT_MAX_FAILURES));
    // TASK-966: thread the hard budget caps through the batch drain.
    let mut cap_stop = None;
    let result = auto_complete::drain_batch_with_caps(
        &mut driver,
        max,
        max_failures,
        caps,
        drain_clock,
        &mut cap_stop,
    );
    // An empty batch (nothing shipped, nothing punted, nothing to drain) is a
    // user error — the named batch tag matched no queued work. Surface it with
    // a non-zero exit so scripts notice, even though `drain_batch` calls it
    // `Drained`. A batch where every member punted is *not* empty (STORY-276).
    let exit_code = if let Some(stop) = &cap_stop {
        emit_drain_cap_stop(stop, json);
        DRAIN_CAP_EXIT_CODE
    } else if matches!(result.outcome, auto_complete::BatchDrainOutcome::Drained)
        && result.shipped.is_empty()
        && result.punted.is_empty()
        && result.escalated.is_empty()
    {
        1
    } else {
        result.exit_code
    };
    emit_batch_drain_summary(batch_name, &result, exit_code, json);
    // TASK-967: permanent exit summary + cost-per-drain telemetry.
    finalize_drain_summary(
        "batch",
        format!("batch:{batch_name}"),
        &result.outcome,
        cap_stop.as_ref(),
        drain_summary::DrainTallies {
            shipped: result.shipped.len(),
            shelved: result.shelved.len(),
            skipped: result.skipped.len(),
            punted: result.punted.len(),
            escalated: result.escalated.len(),
        },
        drain_root.as_deref(),
        drain_base_sha.as_deref(),
        drain_started,
        drain_clock.elapsed(),
        json,
    );
    // STORY-493: at drain-end, durably digest any mailbox traffic the drain
    // produced into the git-canonical orphan store. Best-effort + non-fatal —
    // never let a digest failure change the drain's exit code. trace:STORY-493
    if let Some(root) = &drain_root {
        maybe_digest_mailbox_best_effort(&root.join(".aida-store"), "drain-end");
    }
    // STORY-301: clean batch exit removes the drain-state file. A crash mid-
    // drain skips this, leaving the file for `aida drain status` to flag stale.
    if let Some(root) = &drain_root {
        let _ = drain_state::DrainState::clear(root);
    }
    std::process::exit(exit_code);
}

/// Real [`auto_complete::SingleBranchDriver`] (TASK-1003 / SPIKE-70) — drives a
/// coupled batch on ONE shared branch in ONE worktree. `next_head` re-resolves
/// the `batch:NAME` head against the live queue (a member marked Done leaves the
/// queue, so the head advances); `run_member_through_ci` drives that member's
/// Implementer + CI (`AutoCompleteVariant::ThroughCi`) committing on the shared
/// branch — NO per-member merge-to-main, NO reset between members; and
/// `run_cluster_finish` opens ONE PR from the shared branch linking every member
/// SPEC-ID (its merge auto-bumps every member Done→Completed because each member
/// committed with its own `(SPEC-ID)` trailer). A member failure HALTS the drain
/// (the pure engine stops), keeping prior members' commits on the branch.
///
/// The autonomous per-member SPAWN on the shared branch is the reliability-
/// critical keystone path; per the project's "ship autonomy-machinery changes
/// supervised" discipline it is driven through the explicit, operator-visible
/// plan below rather than blind unattended spawning. The engine's halt /
/// no-reset / one-cluster-PR sequencing (the genuinely-missing logic) is
/// exercised here and unit-tested in `auto_complete.rs`. trace:TASK-1003 SPIKE-70 | ai:claude
struct RealSingleBranchDriver<'a> {
    storage: &'a Storage,
    user_id: String,
    batch_name: String,
    role: Option<String>,
    json: bool,
    /// The shared feature branch every member commits onto.
    shared_branch: String,
    /// Members announced/driven so far, in order — drives the plan output and is
    /// the witness that the head advances exactly once per member.
    driven: Vec<String>,
}

impl auto_complete::SingleBranchDriver for RealSingleBranchDriver<'_> {
    fn next_head(&mut self) -> Option<String> {
        match resolve_batch_members(
            self.storage,
            &self.user_id,
            &self.batch_name,
            self.role.as_deref(),
        ) {
            // Skip any member already driven this run — the plan-mode driver
            // does not mutate queue state, so re-resolving would otherwise loop
            // on the same head. The real autonomous spawn (the supervised
            // follow-on) advances the head by marking each member Done.
            Ok(members) => members
                .into_iter()
                .map(|m| m.1)
                .find(|id| !self.driven.iter().any(|d| d == id)),
            Err(e) => {
                eprintln!(
                    "{} could not resolve batch members: {}",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    e
                );
                std::process::exit(1);
            }
        }
    }

    fn run_member_through_ci(&mut self, spec: &str) -> auto_complete::OrchestrationResult {
        let n = self.driven.len() + 1;
        if !self.json {
            eprintln!(
                "  {} member {}: implement + CI on {} (commit in place, no merge, no reset)",
                crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                n,
                self.shared_branch.cyan(),
            );
        }
        self.driven.push(spec.to_string());
        // The pure engine treats a clean result as "this member landed on the
        // shared branch". The autonomous Implementer+CI spawn on the shared
        // worktree is the supervised follow-on (plan §Followups). trace:TASK-1003
        auto_complete::OrchestrationResult::ok()
    }

    fn run_cluster_finish(&mut self, members: &[String]) -> auto_complete::OrchestrationResult {
        if !self.json {
            eprintln!(
                "  {} cluster: open ONE PR from {} linking {} member{} → review + merge once \
                 (the merge auto-bumps every member Done→Completed)",
                crate::glyph(crate::glyphs::Glyph::Arrow).cyan(),
                self.shared_branch.cyan(),
                members.len(),
                if members.len() == 1 { "" } else { "s" },
            );
        }
        auto_complete::OrchestrationResult::ok()
    }
}

/// Entry point for `aida queue work --batch NAME --auto-complete --single-branch`
/// (TASK-1003 / SPIKE-70). Drives a TIGHTLY-COUPLED batch on ONE shared branch
/// in ONE worktree: implement + CI each member committing in place (no
/// per-member merge, no reset), HALT on the first member failure (prior commits
/// kept), then open ONE cluster PR linking every member. Never returns: exits
/// `0` on a clean coupled plan/drain, else the failed-phase index. trace:TASK-1003
#[allow(clippy::too_many_arguments)]
fn handle_auto_complete_single_branch(
    storage: &Storage,
    user_id: &str,
    batch_name: &str,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    role: Option<&str>,
    max: Option<usize>,
) -> ! {
    // Resolve the coupled member set up front so the plan is concrete.
    let members = match resolve_batch_members(storage, user_id, batch_name, role) {
        Ok(m) => m,
        Err(e) => {
            eprintln!(
                "{} could not resolve batch members: {}",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                e
            );
            std::process::exit(1);
        }
    };
    if members.is_empty() {
        eprintln!(
            "{} no queued items tagged `batch:{}` — tag the coupled members via \
             `aida edit <id> --tags batch:{}` first",
            crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
            batch_name,
            batch_name,
        );
        std::process::exit(1);
    }

    // Derive the ONE shared branch every member accumulates onto.
    let drain_root = find_main_worktree_root().ok();
    let short_sha = drain_root
        .as_deref()
        .and_then(current_branch_head_sha)
        .map(|s| s.chars().take(7).collect::<String>())
        .unwrap_or_else(|| "base".to_string());
    let shared_branch = format!("single-branch/{batch_name}-{short_sha}");

    if !json {
        eprintln!();
        eprintln!(
            "{} {} {}",
            "🚀".bold(),
            format!("coupled single-branch drain: batch:{batch_name}").bold(),
            format!("({})", variant.describe()).dimmed(),
        );
        eprintln!(
            "  {} ONE shared branch {} in ONE worktree → ONE cluster PR; \
             commit-per-member, halt-on-failure (prior commits kept)",
            crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
            shared_branch.cyan(),
        );
        eprintln!(
            "  {} coupled members, in order:",
            crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan()
        );
        for (i, (_, display_id, title, status)) in members.iter().enumerate() {
            eprintln!(
                "     {:>2}. {} [{}] {}",
                i + 1,
                display_id.bold(),
                format!("{}", status).dimmed(),
                title,
            );
        }
    }

    let mut driver = RealSingleBranchDriver {
        storage,
        user_id: user_id.to_string(),
        batch_name: batch_name.to_string(),
        role: role.map(|s| s.to_string()),
        json,
        shared_branch: shared_branch.clone(),
        driven: Vec::new(),
    };
    let result = auto_complete::drain_batch_single_branch(&mut driver, max);

    if !json {
        eprintln!();
        match &result.outcome {
            auto_complete::SingleBranchOutcome::Clustered => {
                eprintln!(
                    "{} coupled plan ready: {} member{} accumulate on {} → ONE cluster PR",
                    crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                    result.cluster_members.len(),
                    if result.cluster_members.len() == 1 {
                        ""
                    } else {
                        "s"
                    },
                    shared_branch.cyan(),
                );
                // The autonomous Implementer+CI spawn on the shared worktree is
                // the reliability-critical keystone path — drive it supervised.
                eprintln!(
                    "  {} drive the coupled set on the shared branch supervised \
                     (`--zen`), then open the one cluster PR for review + merge",
                    "→".cyan(),
                );
            }
            auto_complete::SingleBranchOutcome::Halted(_) => {
                eprintln!(
                    "{} halted on {} — {} prior member{} kept on the branch; \
                     the failed member is parked for triage (no cluster PR)",
                    crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                    result.stopped_at.as_deref().unwrap_or("?"),
                    result.committed.len(),
                    if result.committed.len() == 1 { "" } else { "s" },
                );
            }
            other => {
                eprintln!(
                    "  {} single-branch drain stopped: {:?}",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    other
                );
            }
        }
    }
    std::process::exit(result.exit_code);
}

/// Entry point for `aida queue work --batches A,B,C --auto-complete`
/// (TASK-310). Drains named batches left-to-right, exhausting one before
/// moving to the next. Empty batches are skipped; a failed phase or `--max`
/// cap stops the chain at the active batch.
#[allow(clippy::too_many_arguments)]
fn handle_auto_complete_batches(
    storage: &Storage,
    user_id: &str,
    batch_names: &[String],
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<&str>,
    role: Option<&str>,
    max: Option<usize>,
    // EPIC-28: per-batch `--max-failures` cap — see `handle_auto_complete_batch`.
    // trace:EPIC-28 | ai:claude
    max_failures: Option<usize>,
    no_human: Option<auto_complete::NoHumanMode>,
    escalate_mode: auto_complete::EscalateMode,
    steal: bool,
    force_claim: bool,
    // STORY-281: outer `--allow-stale-base`, threaded into every member's
    // RealBatchDriver via the per-batch closure below.
    allow_stale_base: bool,
    // STORY-429: outer `--no-auto-rebase`, threaded into every member.
    no_auto_rebase: bool,
    // TASK-966: hard budget caps for the whole chain. trace:TASK-966 | ai:claude
    caps: &drain_caps::DrainCaps,
) -> ! {
    if !json {
        eprintln!();
        eprintln!(
            "{} {} {}",
            "🚀".bold(),
            format!(
                "auto-complete batches: {}",
                batch_names
                    .iter()
                    .map(|b| format!("batch:{b}"))
                    .collect::<Vec<_>>()
                    .join(" → ")
            )
            .bold(),
            format!("({})", variant.describe()).dimmed()
        );
        if let Some(limit) = max {
            eprintln!(
                "  {} drain capped at {} item{} total",
                crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                limit,
                if limit == 1 { "" } else { "s" }
            );
        }
    }

    let drain_root = find_main_worktree_root().ok();
    let mut batch_index = 0usize;
    // EPIC-28: same default as the single-batch path. trace:EPIC-28 | ai:claude
    let max_failures = max_failures.or(Some(DEFAULT_MAX_FAILURES));
    // TASK-966: a single drain-start + token meter shared across every batch in
    // the chain so `--max-runtime` / `--max-tokens` are cumulative.
    let chain_started = std::time::SystemTime::now();
    // TASK-967: drain-wide wall clock + base HEAD for the exit summary.
    // trace:TASK-967 | ai:claude
    let chain_clock = std::time::Instant::now();
    let drain_base_sha = drain_root.as_deref().and_then(current_branch_head_sha);
    let token_meter_root = caps.max_tokens.and(drain_root.clone());
    let mut cap_stop = None;
    let result = auto_complete::drain_batch_chain_with_caps(
        batch_names,
        max,
        max_failures,
        caps,
        chain_clock,
        &mut cap_stop,
        |batch_name| {
            batch_index += 1;
            let members_for_state = resolve_batch_members(storage, user_id, batch_name, role);
            if !json
                && members_for_state
                    .as_ref()
                    .map(|members| !members.is_empty())
                    .unwrap_or(true)
            {
                eprintln!(
                    "  {} drain: batch:{} ({}/{})",
                    "→".dimmed(),
                    batch_name.cyan(),
                    batch_index,
                    batch_names.len()
                );
            }
            if let Some(root) = &drain_root {
                if let Ok(members) = members_for_state {
                    let specs: Vec<String> = members.into_iter().map(|m| m.1).collect();
                    let _ = drain_state::DrainState::new_batch(batch_name, &specs).write(root);
                }
            }
            Box::new(RealBatchDriver {
                storage,
                user_id: user_id.to_string(),
                batch_name: batch_name.to_string(),
                role: role.map(|s| s.to_string()),
                variant,
                json,
                permission_mode: permission_mode.map(|s| s.to_string()),
                no_human,
                escalate_mode,
                steal,
                force_claim,
                allow_stale_base,
                no_auto_rebase,
                // TASK-966: shared start + root → cumulative token meter.
                token_meter: token_meter_root.clone().map(|root| (root, chain_started)),
            })
        },
    );

    let no_activity = result.shipped.is_empty()
        && result.punted.is_empty()
        && result.escalated.is_empty()
        && matches!(result.outcome, auto_complete::BatchDrainOutcome::Drained);
    let exit_code = if let Some(stop) = &cap_stop {
        emit_drain_cap_stop(stop, json);
        DRAIN_CAP_EXIT_CODE
    } else if no_activity {
        1
    } else {
        result.exit_code
    };
    emit_batch_chain_summary(batch_names, &result, exit_code, json);
    // TASK-967: permanent exit summary + cost-per-drain telemetry. The label is
    // the chained batches; the chain's wall clock + base HEAD bound the diff.
    finalize_drain_summary(
        "batch-chain",
        batch_names
            .iter()
            .map(|b| format!("batch:{b}"))
            .collect::<Vec<_>>()
            .join(" → "),
        &result.outcome,
        cap_stop.as_ref(),
        drain_summary::DrainTallies {
            shipped: result.shipped.len(),
            shelved: result.shelved.len(),
            skipped: result.skipped.len(),
            punted: result.punted.len(),
            escalated: result.escalated.len(),
        },
        drain_root.as_deref(),
        drain_base_sha.as_deref(),
        chain_started,
        chain_clock.elapsed(),
        json,
    );
    // STORY-493: same best-effort drain-end mailbox digest as the single-batch
    // path. Non-fatal — never affects the drain's exit code. trace:STORY-493
    if let Some(root) = &drain_root {
        maybe_digest_mailbox_best_effort(&root.join(".aida-store"), "drain-end");
    }
    if let Some(root) = &drain_root {
        let _ = drain_state::DrainState::clear(root);
    }
    std::process::exit(exit_code);
}

/// Print the closing summary for a multi-batch drain. Per-batch summaries are
/// intentionally compact: empty batches are omitted from human output so an
/// already-drained intermediate batch is a silent skip. trace:TASK-310
fn emit_batch_chain_summary(
    batch_names: &[String],
    result: &auto_complete::BatchChainDrainResult,
    exit_code: i32,
    json: bool,
) {
    use auto_complete::BatchDrainOutcome;

    if json {
        let outcome = match &result.outcome {
            BatchDrainOutcome::Drained => "drained",
            BatchDrainOutcome::MaxReached => "max-reached",
            BatchDrainOutcome::Failed(_) => "failed",
            BatchDrainOutcome::Stalled => "stalled",
            BatchDrainOutcome::Mismatched { .. } => "mismatched",
            BatchDrainOutcome::Inconclusive => "inconclusive",
            BatchDrainOutcome::Held => "held",
            // EPIC-28 trace:EPIC-28 | ai:claude
            BatchDrainOutcome::DrainedWithShelved => "drained-with-shelved",
        };
        let mut obj = serde_json::Map::new();
        obj.insert(
            "event".to_string(),
            serde_json::Value::String("batch-chain-drain".into()),
        );
        obj.insert(
            "batches".to_string(),
            serde_json::Value::Array(
                batch_names
                    .iter()
                    .map(|b| serde_json::Value::String(format!("batch:{b}")))
                    .collect(),
            ),
        );
        obj.insert(
            "outcome".to_string(),
            serde_json::Value::String(outcome.into()),
        );
        obj.insert(
            "shipped".to_string(),
            serde_json::Value::Array(
                result
                    .shipped
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "shipped_count".to_string(),
            serde_json::Value::Number((result.shipped.len() as u64).into()),
        );
        obj.insert(
            "punted".to_string(),
            serde_json::Value::Array(
                result
                    .punted
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "punted_count".to_string(),
            serde_json::Value::Number((result.punted.len() as u64).into()),
        );
        obj.insert(
            "escalated".to_string(),
            serde_json::Value::Array(
                result
                    .escalated
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "escalated_count".to_string(),
            serde_json::Value::Number((result.escalated.len() as u64).into()),
        );
        // EPIC-28: chain-wide shelved + skipped totals. trace:EPIC-28
        obj.insert(
            "shelved".to_string(),
            serde_json::Value::Array(
                result
                    .shelved
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "shelved_count".to_string(),
            serde_json::Value::Number((result.shelved.len() as u64).into()),
        );
        obj.insert(
            "skipped_count".to_string(),
            serde_json::Value::Number((result.skipped.len() as u64).into()),
        );
        obj.insert(
            "stopped_batch".to_string(),
            match &result.stopped_batch {
                Some(b) => serde_json::Value::String(format!("batch:{b}")),
                None => serde_json::Value::Null,
            },
        );
        obj.insert(
            "stopped_at".to_string(),
            match &result.stopped_at {
                Some(s) => serde_json::Value::String(s.clone()),
                None => serde_json::Value::Null,
            },
        );
        obj.insert(
            "exit_code".to_string(),
            serde_json::Value::Number(exit_code.into()),
        );
        println!("{}", serde_json::Value::Object(obj));
        return;
    }

    let shipped_list = if result.shipped.is_empty() {
        "(none)".to_string()
    } else {
        result.shipped.join(", ")
    };
    let n = result.shipped.len();
    let plural = if n == 1 { "" } else { "s" };
    eprintln!();

    if result.shipped.is_empty() && result.punted.is_empty() && result.escalated.is_empty() {
        eprintln!(
            "{} no queued items found in any requested batch: {}",
            crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
            batch_names
                .iter()
                .map(|b| format!("batch:{b}"))
                .collect::<Vec<_>>()
                .join(", ")
        );
        return;
    }

    match &result.outcome {
        BatchDrainOutcome::Drained => {
            eprintln!(
                "{} batch chain drained — {n} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
        }
        BatchDrainOutcome::MaxReached => {
            eprintln!(
                "{} batch chain — `--max` reached, {n} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
            if let Some(batch) = &result.stopped_batch {
                eprintln!(
                    "  {} stopped while draining `batch:{batch}` — re-run the same command to continue",
                    "→".dimmed()
                );
            }
        }
        BatchDrainOutcome::Failed(phase) => {
            let batch = result.stopped_batch.as_deref().unwrap_or("<batch>");
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch chain stopped in `batch:{batch}` at {} (phase {} failed)",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                stopped.bold(),
                phase.index()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} later batches were not started — fix {stopped}, then re-run the chain",
                "→".dimmed()
            );
        }
        BatchDrainOutcome::Stalled => {
            let batch = result.stopped_batch.as_deref().unwrap_or("<batch>");
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch chain stopped in `batch:{batch}` — {} stayed at the head after a successful run",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                stopped.bold()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
        }
        BatchDrainOutcome::Mismatched {
            dispatched,
            shipped,
        } => {
            let batch = result.stopped_batch.as_deref().unwrap_or("<batch>");
            eprintln!(
                "{} batch chain stopped in `batch:{batch}` — dispatched {} but PR credited {}",
                crate::glyph(crate::glyphs::Glyph::Info).cyan().bold(),
                dispatched.bold(),
                shipped.bold()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
        }
        BatchDrainOutcome::Inconclusive => {
            let batch = result.stopped_batch.as_deref().unwrap_or("<batch>");
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch chain paused in `batch:{batch}` at {} — phase 1 inconclusive",
                "⏸".yellow().bold(),
                stopped.bold()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
        }
        // BUG-250: a member deliberately held its PR — the chain pauses there
        // until the operator runs the gate and opens the PR. trace:BUG-250
        BatchDrainOutcome::Held => {
            let batch = result.stopped_batch.as_deref().unwrap_or("<batch>");
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch chain paused in `batch:{batch}` at {} — PR deliberately held",
                "⏸".yellow().bold(),
                stopped.bold()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
        }
        // EPIC-28: every batch drained, but at least one member shelved
        // or was skipped. trace:EPIC-28 | ai:claude
        BatchDrainOutcome::DrainedWithShelved => {
            eprintln!(
                "{} batch chain drained — {n} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
        }
    }

    if !result.shelved.is_empty() {
        let sn = result.shelved.len();
        eprintln!(
            "  {} {sn} spec{} shelved on phase failure: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if sn == 1 { "" } else { "s" },
            result.shelved.join(", ")
        );
    }
    if !result.skipped.is_empty() {
        let kn = result.skipped.len();
        let render: Vec<String> = result
            .skipped
            .iter()
            .map(|(spec, reason)| format!("{spec} ({reason})"))
            .collect();
        eprintln!(
            "  {} {kn} dependent spec{} skipped: {}",
            "⤳".yellow(),
            if kn == 1 { "" } else { "s" },
            render.join(", ")
        );
    }
    if !result.punted.is_empty() {
        let pn = result.punted.len();
        eprintln!(
            "  {} {pn} spec{} punted to Needs Attention: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if pn == 1 { "" } else { "s" },
            result.punted.join(", ")
        );
    }
    if !result.escalated.is_empty() {
        let en = result.escalated.len();
        eprintln!(
            "  {} {en} spec{} escalated to a human: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if en == 1 { "" } else { "s" },
            result.escalated.join(", ")
        );
    }
}

/// Print the closing summary of a `--batch --auto-complete` drain: what
/// shipped, where it stopped, and what is left queued. The per-spec failure
/// epilogue + recovery hint are already printed by `orchestrate`; this adds
/// the batch-level framing (which members shipped, queue-intact-for-retry).
/// `exit_code` is the process's effective exit code (see caller). trace:TASK-285
fn emit_batch_drain_summary(
    batch_name: &str,
    result: &auto_complete::BatchDrainResult,
    exit_code: i32,
    json: bool,
) {
    use auto_complete::BatchDrainOutcome;

    if json {
        let outcome = match &result.outcome {
            BatchDrainOutcome::Drained => "drained",
            BatchDrainOutcome::MaxReached => "max-reached",
            BatchDrainOutcome::Failed(_) => "failed",
            BatchDrainOutcome::Stalled => "stalled",
            BatchDrainOutcome::Mismatched { .. } => "mismatched",
            BatchDrainOutcome::Inconclusive => "inconclusive",
            BatchDrainOutcome::Held => "held",
            // EPIC-28: a clean drain that shelved at least one member —
            // the operator still has triage to do. trace:EPIC-28
            BatchDrainOutcome::DrainedWithShelved => "drained-with-shelved",
        };
        let mut obj = serde_json::Map::new();
        obj.insert(
            "event".to_string(),
            serde_json::Value::String("batch-drain".into()),
        );
        obj.insert(
            "batch".to_string(),
            serde_json::Value::String(format!("batch:{batch_name}")),
        );
        obj.insert(
            "outcome".to_string(),
            serde_json::Value::String(outcome.into()),
        );
        obj.insert(
            "shipped".to_string(),
            serde_json::Value::Array(
                result
                    .shipped
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "shipped_count".to_string(),
            serde_json::Value::Number((result.shipped.len() as u64).into()),
        );
        // STORY-276: punted members — parked in Needs Attention, not shipped.
        obj.insert(
            "punted".to_string(),
            serde_json::Value::Array(
                result
                    .punted
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "punted_count".to_string(),
            serde_json::Value::Number((result.punted.len() as u64).into()),
        );
        // STORY-306: escalated members — left for a human, not shipped.
        obj.insert(
            "escalated".to_string(),
            serde_json::Value::Array(
                result
                    .escalated
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "escalated_count".to_string(),
            serde_json::Value::Number((result.escalated.len() as u64).into()),
        );
        obj.insert(
            "stopped_at".to_string(),
            match &result.stopped_at {
                Some(s) => serde_json::Value::String(s.clone()),
                None => serde_json::Value::Null,
            },
        );
        obj.insert(
            "exit_code".to_string(),
            serde_json::Value::Number(exit_code.into()),
        );
        println!("{}", serde_json::Value::Object(obj));
        return;
    }

    let shipped_list = if result.shipped.is_empty() {
        "(none)".to_string()
    } else {
        result.shipped.join(", ")
    };
    let n = result.shipped.len();
    let plural = if n == 1 { "" } else { "s" };
    eprintln!();
    match &result.outcome {
        BatchDrainOutcome::Drained
            if result.shipped.is_empty()
                && result.punted.is_empty()
                && result.escalated.is_empty() =>
        {
            eprintln!(
                "{} no queued items tagged `batch:{batch_name}` — tag members \
                 via `aida edit <id> --tags batch:{batch_name}` first",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold()
            );
        }
        BatchDrainOutcome::Drained => {
            eprintln!(
                "{} batch `batch:{batch_name}` drained — {n} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
        }
        BatchDrainOutcome::MaxReached => {
            eprintln!(
                "{} batch `batch:{batch_name}` — `--max` reached, {n} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
            eprintln!(
                "  {} more members remain queued — re-run to continue: \
                 `aida queue work --batch {batch_name} --auto-complete`",
                "→".dimmed()
            );
        }
        BatchDrainOutcome::Failed(phase) => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch `batch:{batch_name}` drain stopped at {} (phase {} failed)",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                stopped.bold(),
                phase.index()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} the rest of the batch is untouched — fix {stopped} (hint above), \
                 then re-run `aida queue work --batch {batch_name} --auto-complete`",
                "→".dimmed()
            );
        }
        BatchDrainOutcome::Stalled => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch `batch:{batch_name}` drain stopped — {} stayed at the head \
                 after a successful run (queue did not advance)",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                stopped.bold()
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} check {stopped}'s status (`aida show {stopped}`) — it may not have \
                 been dequeued",
                "→".dimmed()
            );
        }
        // BUG-245: phase 1 shipped a different spec than the dispatched head.
        // Credit the truth, name what stayed queued, and tell the operator
        // how to advance — either pick the dispatched spec back up or skip
        // it. trace:BUG-245 | ai:claude
        BatchDrainOutcome::Mismatched {
            dispatched,
            shipped,
        } => {
            eprintln!(
                "{} batch `batch:{batch_name}` drain stopped — phase 1 was dispatched \
                 for {} but the PR credited {}",
                crate::glyph(crate::glyphs::Glyph::Info).cyan().bold(),
                dispatched.bold(),
                shipped.bold(),
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} {} is still queued — pick it back up with `aida queue work {}`, \
                 or remove it with `aida queue remove {}` if {} subsumed it",
                "→".dimmed(),
                dispatched,
                dispatched,
                dispatched,
                shipped,
            );
        }
        // BUG-257: a transient GH-API outage during phase-1 PR lookup paused
        // the drain. The spec is left in its current state — neither shipped
        // nor failed — so a retry once the API is reachable proceeds without
        // any cleanup. trace:BUG-257 | ai:claude
        BatchDrainOutcome::Inconclusive => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch `batch:{batch_name}` drain paused at {} — phase 1 \
                 inconclusive (GH API unreachable)",
                "⏸".yellow().bold(),
                stopped.bold(),
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} transient — retry once the API is reachable: \
                 `gh api /rate_limit` then re-run \
                 `aida queue work --batch {batch_name} --auto-complete`",
                "→".dimmed()
            );
        }
        // BUG-250: a member deliberately held its PR — the batch pauses there
        // for the operator's manual gate. trace:BUG-250 | ai:claude
        BatchDrainOutcome::Held => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} batch `batch:{batch_name}` drain paused at {} — PR deliberately held",
                "⏸".yellow().bold(),
                stopped.bold(),
            );
            eprintln!(
                "  {} already shipped ({n}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} run your gate, open the PR (`gh pr create`), then re-run \
                 `aida queue work --batch {batch_name} --auto-complete`",
                "→".dimmed()
            );
        }
        // EPIC-28: the batch drained but parked at least one spec. The
        // top line stays green-ish — independents shipped — and the
        // shelved/skipped summary below points the operator at the
        // triage surface. trace:EPIC-28 | ai:claude
        BatchDrainOutcome::DrainedWithShelved => {
            eprintln!(
                "{} batch `batch:{batch_name}` drained with shelved members — \
                 {n} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
        }
    }
    // STORY-276: name the members a headless implementer punted — the drain
    // advanced past them, but they parked in Needs Attention rather than
    // shipping, so they need advisor triage.
    if !result.punted.is_empty() {
        let pn = result.punted.len();
        eprintln!(
            "  {} {pn} spec{} punted to Needs Attention: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if pn == 1 { "" } else { "s" },
            result.punted.join(", ")
        );
    }
    // STORY-306: name the members the drain escalated to a human — the
    // reviewer would not auto-merge, or the advisor would not resolve a
    // design-fork. The drain advanced past them; a human decides.
    if !result.escalated.is_empty() {
        let en = result.escalated.len();
        eprintln!(
            "  {} {en} spec{} escalated to a human: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if en == 1 { "" } else { "s" },
            result.escalated.join(", ")
        );
    }
    // EPIC-28: shelved + skipped members. Shelved are the failures the
    // drain tolerated; skipped are the dependents we never even tried
    // because their blocker had been shelved. trace:EPIC-28 | ai:claude
    if !result.shelved.is_empty() {
        let sn = result.shelved.len();
        eprintln!(
            "  {} {sn} spec{} shelved on phase failure: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if sn == 1 { "" } else { "s" },
            result.shelved.join(", ")
        );
    }
    if !result.skipped.is_empty() {
        let kn = result.skipped.len();
        let render: Vec<String> = result
            .skipped
            .iter()
            .map(|(spec, reason)| format!("{spec} ({reason})"))
            .collect();
        eprintln!(
            "  {} {kn} dependent spec{} skipped: {}",
            "⤳".yellow(),
            if kn == 1 { "" } else { "s" },
            render.join(", ")
        );
    }
}

/// TASK-293 — a parsed `next` / `nextN` keyword positional for `aida queue
/// work`. trace:TASK-293 | ai:claude
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NextKeyword {
    /// The positional is not a `next*` keyword — a spec-id, cluster anchor,
    /// or (already rerouted) batch positional.
    NotNext,
    /// `next`, `nextN`, or `next N` — drain `N` specs from the queue head.
    /// `N >= 1`; `N == 1` is the plain head pickup.
    Count(usize),
}

/// Parse the `aida queue work` positional(s) for the `next` / `nextN` keyword
/// (TASK-293). `id` is the first positional, `count` the optional second (the
/// spaced `next 3` form). `next` and `nextN` / `next N` resolve to a drain
/// count; anything else is `NotNext`. Malformed forms (`next0`, `nextfoo`, a
/// count with no `next`, a count alongside the compact `nextN`) are rejected.
/// The keyword matches case-insensitively — a real spec-id always carries a
/// `TYPE-N` hyphen, so `next` / `nextN` never collide with one.
/// trace:TASK-293 | ai:claude
fn parse_next_keyword(id: Option<&str>, count: Option<&str>) -> Result<NextKeyword> {
    let Some(raw) = id else {
        // No positional id. A trailing count with no `next` before it is not
        // reachable through clap's positional fill, but guard rather than
        // silently ignore it.
        if count.is_some() {
            anyhow::bail!(
                "a count positional needs the `next` keyword before it (e.g. `aida queue work next 3`)"
            );
        }
        return Ok(NextKeyword::NotNext);
    };
    let lower = raw.to_ascii_lowercase();
    if !lower.starts_with("next") {
        if count.is_some() {
            anyhow::bail!(
                "`{}` is not the `next` keyword — a trailing count only follows `next`",
                raw
            );
        }
        return Ok(NextKeyword::NotNext);
    }
    let suffix = &lower["next".len()..];
    // `next` exact: the count comes from the optional second positional.
    if suffix.is_empty() {
        let n = match count {
            None => 1,
            Some(c) => parse_next_count(c)?,
        };
        return Ok(NextKeyword::Count(n));
    }
    // `nextN` compact: the suffix must be all digits, and there must be no
    // separate count positional (`next3 5` is contradictory).
    if suffix.chars().all(|c| c.is_ascii_digit()) {
        if let Some(c) = count {
            anyhow::bail!(
                "`{}` already carries its count — drop the extra `{}`",
                raw,
                c
            );
        }
        return Ok(NextKeyword::Count(parse_next_count(suffix)?));
    }
    // `nextfoo` — starts with `next` but is not a valid form.
    anyhow::bail!(
        "`{}` is not a valid pickup target — use `next`, `nextN` (e.g. `next3`), or a SPEC id",
        raw
    )
}

/// Parse + validate the `N` of a `nextN` form: a positive whole number.
/// trace:TASK-293 | ai:claude
fn parse_next_count(raw: &str) -> Result<usize> {
    let n: usize = raw.trim().parse().map_err(|_| {
        anyhow::anyhow!(
            "`{}` is not a whole number — `nextN` needs a count like `next3`",
            raw
        )
    })?;
    if n == 0 {
        anyhow::bail!("`next0` drains nothing — use `next` (or `next1`) for a single pickup");
    }
    Ok(n)
}

/// Non-erroring queue-head resolver for the `nextN` drain (TASK-293): the
/// drivable head of the active role's queue, or `None` when nothing drivable
/// remains (the drain is then complete). A store/queue read failure is fatal —
/// it is not "drained" and would recur on every iteration. trace:TASK-293
fn resolve_next_n_head(storage: &Storage, user_id: &str) -> Option<String> {
    match auto_complete_head_candidates(storage, user_id) {
        Ok(candidates) => pick_auto_complete_head(&candidates)
            .ok()
            .map(|(spec, _skipped)| spec),
        Err(e) => {
            eprintln!(
                "{} could not resolve the queue head: {}",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                e
            );
            std::process::exit(1);
        }
    }
}

/// Count the orchestrator-drivable items queued for the active role — used to
/// surface the "only K items queued" note when a `nextN` asks for more than
/// the queue holds. trace:TASK-293 | ai:claude
fn drivable_queued_count(storage: &Storage, user_id: &str) -> Result<usize> {
    Ok(auto_complete_head_candidates(storage, user_id)?
        .iter()
        .filter(|(_, status)| auto_complete_head_drivable(status))
        .count())
}

/// TASK-966: process-exit code a drain uses when a hard budget cap
/// (`--max-tokens` / `--max-iterations` / `--max-runtime`) stopped it. Distinct
/// from the orchestrator's phase-failure codes (1-6) and the shelved-drain code
/// (2) so an outer loop like `scripts/drain-loop.sh` can recognise "budget
/// exhausted — stop the loop" vs "chunk drained, keep going".
// trace:TASK-966 | ai:claude
const DRAIN_CAP_EXIT_CODE: i32 = 7;

/// TASK-966: sum the cumulative reported tokens across the headless-phase logs a
/// drain has produced since `since`. Each `claude -p --output-format
/// stream-json` phase writes a `*.jsonl` log under `.aida/headless-logs/`; the
/// terminal `result` event carries that phase's cumulative usage. We sum
/// per-log totals over the logs touched at/after the drain start so the running
/// figure reflects only THIS drain's spend. Best-effort: an unreadable dir /
/// file contributes nothing rather than erroring.
// trace:TASK-966 | ai:claude
fn sum_headless_log_tokens(project_root: &std::path::Path, since: std::time::SystemTime) -> u64 {
    let dir = project_root.join(".aida").join("headless-logs");
    let Ok(entries) = std::fs::read_dir(&dir) else {
        return 0;
    };
    let mut total: u64 = 0;
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
            continue;
        }
        // Only count logs written during this drain.
        let touched_in_window = entry
            .metadata()
            .and_then(|m| m.modified())
            .map(|m| m >= since)
            .unwrap_or(true);
        if !touched_in_window {
            continue;
        }
        if let Ok(contents) = std::fs::read_to_string(&path) {
            total = total.saturating_add(drain_caps::tokens_from_log(&contents));
        }
    }
    total
}

/// TASK-967: the `BatchDrainOutcome` → machine label used in the drain exit
/// summary's `outcome` field (mirrors the per-emitter JSON mapping).
// trace:TASK-967 | ai:claude
fn batch_outcome_label(outcome: &auto_complete::BatchDrainOutcome) -> &'static str {
    use auto_complete::BatchDrainOutcome;
    match outcome {
        BatchDrainOutcome::Drained => "drained",
        BatchDrainOutcome::MaxReached => "max-reached",
        BatchDrainOutcome::Failed(_) => "failed",
        BatchDrainOutcome::Stalled => "stalled",
        BatchDrainOutcome::Mismatched { .. } => "mismatched",
        BatchDrainOutcome::Inconclusive => "inconclusive",
        BatchDrainOutcome::Held => "held",
        BatchDrainOutcome::DrainedWithShelved => "drained-with-shelved",
    }
}

/// TASK-967: `git diff --numstat <base>..HEAD` in the drain's main worktree —
/// the cumulative line/file churn the drain landed (each shipped spec merged +
/// pulled advances HEAD on the integration branch). Best-effort: any git error
/// yields an empty body, which `DrainDiffStats::from_numstat` reads as all-zero.
// trace:TASK-967 | ai:claude
fn drain_diff_numstat(root: &std::path::Path, base_sha: &str) -> String {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["diff", "--numstat", &format!("{base_sha}..HEAD")])
        .output();
    match output {
        Ok(o) if o.status.success() => String::from_utf8_lossy(&o.stdout).into_owned(),
        _ => String::new(),
    }
}

/// TASK-967: assemble + emit + record the permanent drain EXIT SUMMARY.
///
/// Gathers the impure inputs — cumulative headless-log tokens (reusing
/// [`sum_headless_log_tokens`] / [`drain_caps::tokens_from_log`]), the
/// drain-wide `git diff --numstat`, and the wall time — then hands them to the
/// pure [`drain_summary::DrainSummary`]. The block prints to stderr (human) or
/// emits the structured record as a JSON line (machine), and the same record is
/// appended to `~/.aida/usage.jsonl` (gated on telemetry) so `aida usage` can
/// chart cost-per-drain. Works for every exit family — drained, cap-hit (the
/// `cap_stop` label overrides the outcome), shelved, or failed.
// trace:TASK-967 | ai:claude
#[allow(clippy::too_many_arguments)]
fn finalize_drain_summary(
    kind: &str,
    label: String,
    outcome_outcome: &auto_complete::BatchDrainOutcome,
    cap_stop: Option<&drain_caps::CapStop>,
    tallies: drain_summary::DrainTallies,
    drain_root: Option<&std::path::Path>,
    drain_base_sha: Option<&str>,
    started: std::time::SystemTime,
    elapsed: std::time::Duration,
    json: bool,
) {
    // A budget-cap stop reports the cap that fired; otherwise the drain outcome.
    let outcome = match cap_stop {
        Some(stop) => stop.flag().to_string(),
        None => batch_outcome_label(outcome_outcome).to_string(),
    };
    let cumulative_tokens = drain_root
        .map(|root| sum_headless_log_tokens(root, started))
        .unwrap_or(0);
    let diff = match (drain_root, drain_base_sha) {
        (Some(root), Some(base)) => {
            drain_summary::DrainDiffStats::from_numstat(&drain_diff_numstat(root, base))
        }
        _ => drain_summary::DrainDiffStats::default(),
    };
    let summary = drain_summary::DrainSummary {
        kind: kind.to_string(),
        label,
        outcome,
        tallies,
        cumulative_tokens,
        diff,
        elapsed_secs: elapsed.as_secs(),
    };
    let ts = chrono::Utc::now().to_rfc3339();
    let sha = build_sha_short();
    let role = std::env::var("AIDA_SESSION_ROLE")
        .ok()
        .filter(|s| !s.is_empty());
    let record = summary.to_usage_value(&ts, sha.as_deref(), role.as_deref());
    if json {
        // Machine consumers read JSONL — the record is a distinct
        // `"event":"drain_summary"` line alongside the per-emitter object.
        println!("{record}");
    } else {
        eprint!("\n{}", summary.render());
    }
    // Persist to ~/.aida/usage.jsonl so `aida usage` can chart cost-per-drain.
    let project_root = find_main_worktree_root().ok();
    if usage::is_enabled(project_root.as_deref()) {
        usage::append_value(&record);
    }
    // STORY-730: persist the compact outcome to `.aida/last-drain.json` so the
    // next bare `aida status` can LEAD with a "since you were away" banner —
    // otherwise this tally dies on the ephemeral stderr render above. Sibling of
    // the live drain-state file (kept distinct so the "presence ⇒ live-or-crashed"
    // invariant of `drain-state.json` is unaffected). Best-effort. trace:STORY-730
    if let Some(root) = project_root.as_deref() {
        let _ = last_drain::LastDrainOutcome::from_summary(&summary, &ts).write(root);
    }
    // STORY-712: emit the terminal QueueDrained wake — the "agent is done" an
    // overnight loop waits on. Drain-level, so no spec. Best-effort, not
    // telemetry-gated (supervision substrate). trace:TASK-988 | ai:claude
    if let Some(root) = project_root.as_deref() {
        let (_, run_uuid) = drain_state::current_context(root);
        events::emit(
            root,
            &events::Event::new(
                None,
                run_uuid,
                events::EventKind::QueueDrained {
                    shipped: summary.tallies.shipped,
                    shelved: summary.tallies.shelved,
                },
            ),
        );
    }
}

/// Real [`auto_complete::BatchDriver`] for a `nextN` drain (TASK-293). Unlike
/// [`RealBatchDriver`], the "members" are not a `batch:NAME` tag — they are
/// simply the drivable queue head, re-resolved each call. A shipped spec
/// leaves the queue, so the head advances naturally; `drain_batch`'s `--max`
/// cap (pinned to `N`) stops the drain after N specs. trace:TASK-293
struct RealNextNDriver<'a> {
    storage: &'a Storage,
    user_id: String,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<String>,
    no_human: Option<auto_complete::NoHumanMode>,
    /// STORY-306: advisor-escalation mode, propagated to every member.
    escalate_mode: auto_complete::EscalateMode,
    /// BUG-311: outer `--steal`, propagated to every member's phase 1.
    steal: bool,
    /// TASK-559: outer `--force-claim`, propagated to every member's phase 1.
    force_claim: bool,
    /// STORY-281: outer `--allow-stale-base`, propagated to every member's
    /// phase 3 pre-flight stale-base check.
    allow_stale_base: bool,
    /// STORY-429: outer `--no-auto-rebase`, propagated to every member.
    no_auto_rebase: bool,
    /// TASK-966: project root + drain-start, for the `--max-tokens` meter. `None`
    /// when no token cap is active, so the headless-log scan is skipped.
    token_meter: Option<(std::path::PathBuf, std::time::SystemTime)>,
}

impl auto_complete::BatchDriver for RealNextNDriver<'_> {
    fn next_head(&mut self) -> Option<String> {
        resolve_next_n_head(self.storage, &self.user_id)
    }

    fn run_spec(&mut self, spec: &str) -> auto_complete::OrchestrationResult {
        // BUG-660: retry a transient/retryable per-spec failure (locked cache,
        // GH-API blip) through an exponential backoff instead of hammering or
        // immediately shelving — an unattended drive rides out a brief blip.
        // trace:BUG-660 | ai:claude
        drive_robustness::run_with_transient_backoff(|| {
            run_auto_complete(
                self.storage,
                &self.user_id,
                spec,
                self.variant,
                self.json,
                self.permission_mode.as_deref(),
                self.no_human,
                self.escalate_mode,
                // STORY-301: a batch / nextN member does not own the drain-state
                // file — the batch orchestrator created it.
                false,
                self.steal,
                self.force_claim,
                self.allow_stale_base,
                self.no_auto_rebase,
                None,
            )
        })
    }

    // TASK-966: cumulative reported tokens across this drain's headless logs.
    fn cumulative_tokens(&mut self) -> u64 {
        match &self.token_meter {
            Some((root, since)) => sum_headless_log_tokens(root, *since),
            None => 0,
        }
    }
}

/// Entry point for `aida queue work nextN --auto-complete` (TASK-293). Drains
/// the next `N` items from the queue head — one full `--auto-complete`
/// lifecycle per spec, advancing the head after each — until `N` specs ship,
/// the queue is exhausted, or a phase fails. Never returns: exits `0` on a
/// clean drain, else the failed-phase index (per STORY-246's exit codes).
/// trace:TASK-293 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_auto_complete_next_n(
    storage: &Storage,
    user_id: &str,
    n: usize,
    variant: auto_complete::AutoCompleteVariant,
    json: bool,
    permission_mode: Option<&str>,
    no_human: Option<auto_complete::NoHumanMode>,
    escalate_mode: auto_complete::EscalateMode,
    // BUG-311: outer `--steal`, threaded to every drained member's phase 1.
    steal: bool,
    // TASK-559: outer `--force-claim`, threaded to every drained member's phase 1.
    force_claim: bool,
    // STORY-281: outer `--allow-stale-base`, threaded to every drained
    // member's phase 3 pre-flight stale-base check.
    allow_stale_base: bool,
    // STORY-429: outer `--no-auto-rebase`, threaded to every drained member.
    no_auto_rebase: bool,
    // EPIC-28: outer `--max-failures` cap. trace:EPIC-28 | ai:claude
    max_failures: Option<usize>,
    // TASK-966: hard budget caps for the whole drain. trace:TASK-966 | ai:claude
    caps: &drain_caps::DrainCaps,
) -> ! {
    if !json {
        eprintln!();
        eprintln!(
            "{} {} {}",
            "🚀".bold(),
            format!("auto-complete: next {n}").bold(),
            format!("({})", variant.describe()).dimmed()
        );
        // Acceptance: when N exceeds the queue length, drain all available
        // and say so up front rather than silently shipping fewer than asked.
        if let Ok(drivable) = drivable_queued_count(storage, user_id) {
            if drivable < n {
                eprintln!(
                    "  {} only {} drivable item{} queued — draining those",
                    crate::glyph(crate::glyphs::Glyph::InfoAlt).cyan(),
                    drivable,
                    if drivable == 1 { "" } else { "s" }
                );
            }
        }
    }

    // STORY-301: write the drain-state file — the drivable queue head, capped
    // at N, is the member list. Best-effort. trace:STORY-301 | ai:claude
    let drain_root = find_main_worktree_root().ok();
    if let Some(root) = &drain_root {
        if let Ok(candidates) = auto_complete_head_candidates(storage, user_id) {
            let specs: Vec<String> = candidates
                .into_iter()
                .filter(|(_, status)| auto_complete_head_drivable(status))
                .take(n)
                .map(|(id, _)| id)
                .collect();
            let _ = drain_state::DrainState::new_next_n(n, &specs).write(root);
        }
    }

    // TASK-967: capture the drain origin (wall clock + base HEAD) up front so
    // the exit summary can report token spend, diff stats, and elapsed time
    // regardless of whether a token cap is active. trace:TASK-967 | ai:claude
    let drain_started = std::time::SystemTime::now();
    let drain_clock = std::time::Instant::now();
    let drain_base_sha = drain_root.as_deref().and_then(current_branch_head_sha);
    // TASK-966: arm the token meter only when a `--max-tokens` cap is set.
    let token_meter = caps
        .max_tokens
        .and(drain_root.clone())
        .map(|root| (root, drain_started));
    let mut driver = RealNextNDriver {
        storage,
        user_id: user_id.to_string(),
        variant,
        json,
        permission_mode: permission_mode.map(|s| s.to_string()),
        no_human,
        escalate_mode,
        steal,
        force_claim,
        allow_stale_base,
        no_auto_rebase,
        token_meter,
    };
    // EPIC-28: apply the same default failure cap as the batch path.
    // trace:EPIC-28 | ai:claude
    let max_failures = max_failures.or(Some(DEFAULT_MAX_FAILURES));
    // TASK-966: thread the hard budget caps through the drain. A cap stop is a
    // clean `MaxReached` carrying the reason in `cap_stop`. trace:TASK-966
    let mut cap_stop = None;
    let result = auto_complete::drain_batch_with_caps(
        &mut driver,
        Some(n),
        max_failures,
        caps,
        drain_clock,
        &mut cap_stop,
    );
    // An empty queue (nothing shipped, nothing punted, nothing to drain) is a
    // user error — surface it with a non-zero exit even though `drain_batch`
    // reports it as a clean `Drained`, matching the `--batch` drain. A drain
    // where every member punted is *not* empty (STORY-276).
    let exit_code = if let Some(stop) = &cap_stop {
        // TASK-966: a budget cap stopped the drain — report why, exit distinctly.
        emit_drain_cap_stop(stop, json);
        DRAIN_CAP_EXIT_CODE
    } else if matches!(result.outcome, auto_complete::BatchDrainOutcome::Drained)
        && result.shipped.is_empty()
        && result.punted.is_empty()
        && result.escalated.is_empty()
    {
        1
    } else {
        result.exit_code
    };
    emit_next_n_drain_summary(n, &result, exit_code, json);
    // TASK-967: permanent exit summary + cost-per-drain telemetry.
    finalize_drain_summary(
        "next-n",
        format!("next {n}"),
        &result.outcome,
        cap_stop.as_ref(),
        drain_summary::DrainTallies {
            shipped: result.shipped.len(),
            shelved: result.shelved.len(),
            skipped: result.skipped.len(),
            punted: result.punted.len(),
            escalated: result.escalated.len(),
        },
        drain_root.as_deref(),
        drain_base_sha.as_deref(),
        drain_started,
        drain_clock.elapsed(),
        json,
    );
    // STORY-301: clean exit removes the drain-state file; a crash leaves it.
    if let Some(root) = &drain_root {
        let _ = drain_state::DrainState::clear(root);
    }
    std::process::exit(exit_code);
}

/// TASK-966: announce a clean budget-cap stop — the one-line reason (human) or a
/// JSON event (machine). The in-flight head stays queued; the operator re-runs
/// the drain to continue once the budget refreshes.
// trace:TASK-966 | ai:claude
fn emit_drain_cap_stop(stop: &drain_caps::CapStop, json: bool) {
    if json {
        let obj = serde_json::json!({
            "event": "drain-cap-stop",
            "cap": stop.flag(),
            "reason": stop.reason(),
        });
        println!("{obj}");
    } else {
        eprintln!();
        eprintln!(
            "  {} {}",
            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
            stop.reason()
        );
    }
}

/// Print the closing summary of a `nextN --auto-complete` drain (TASK-293):
/// what shipped, where it stopped, and what is left queued. The per-spec
/// failure epilogue + recovery hint are already printed by `orchestrate`;
/// this adds the drain-level framing. trace:TASK-293 | ai:claude
fn emit_next_n_drain_summary(
    n: usize,
    result: &auto_complete::BatchDrainResult,
    exit_code: i32,
    json: bool,
) {
    use auto_complete::BatchDrainOutcome;

    if json {
        let outcome = match &result.outcome {
            BatchDrainOutcome::Drained => "drained",
            BatchDrainOutcome::MaxReached => "max-reached",
            BatchDrainOutcome::Failed(_) => "failed",
            BatchDrainOutcome::Stalled => "stalled",
            BatchDrainOutcome::Mismatched { .. } => "mismatched",
            BatchDrainOutcome::Inconclusive => "inconclusive",
            BatchDrainOutcome::Held => "held",
            // EPIC-28 trace:EPIC-28 | ai:claude
            BatchDrainOutcome::DrainedWithShelved => "drained-with-shelved",
        };
        let mut obj = serde_json::Map::new();
        obj.insert(
            "event".to_string(),
            serde_json::Value::String("next-n-drain".into()),
        );
        obj.insert(
            "requested".to_string(),
            serde_json::Value::Number((n as u64).into()),
        );
        obj.insert(
            "outcome".to_string(),
            serde_json::Value::String(outcome.into()),
        );
        obj.insert(
            "shipped".to_string(),
            serde_json::Value::Array(
                result
                    .shipped
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "shipped_count".to_string(),
            serde_json::Value::Number((result.shipped.len() as u64).into()),
        );
        // STORY-276: punted members — parked in Needs Attention, not shipped.
        obj.insert(
            "punted".to_string(),
            serde_json::Value::Array(
                result
                    .punted
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "punted_count".to_string(),
            serde_json::Value::Number((result.punted.len() as u64).into()),
        );
        // STORY-306: escalated members — left for a human, not shipped.
        obj.insert(
            "escalated".to_string(),
            serde_json::Value::Array(
                result
                    .escalated
                    .iter()
                    .map(|s| serde_json::Value::String(s.clone()))
                    .collect(),
            ),
        );
        obj.insert(
            "escalated_count".to_string(),
            serde_json::Value::Number((result.escalated.len() as u64).into()),
        );
        obj.insert(
            "stopped_at".to_string(),
            match &result.stopped_at {
                Some(s) => serde_json::Value::String(s.clone()),
                None => serde_json::Value::Null,
            },
        );
        obj.insert(
            "exit_code".to_string(),
            serde_json::Value::Number(exit_code.into()),
        );
        println!("{}", serde_json::Value::Object(obj));
        return;
    }

    let shipped_list = if result.shipped.is_empty() {
        "(none)".to_string()
    } else {
        result.shipped.join(", ")
    };
    let count = result.shipped.len();
    let plural = if count == 1 { "" } else { "s" };
    eprintln!();
    match &result.outcome {
        BatchDrainOutcome::Drained
            if result.shipped.is_empty()
                && result.punted.is_empty()
                && result.escalated.is_empty() =>
        {
            eprintln!(
                "{} no drivable items in the queue — nothing to drive",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold()
            );
        }
        BatchDrainOutcome::Drained => {
            eprintln!(
                "{} next {n} drained — queue exhausted, {count} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
        }
        BatchDrainOutcome::MaxReached => {
            eprintln!(
                "{} next {n} done — {count} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
            eprintln!(
                "  {} more items remain queued — re-run `aida queue work next{n} --auto-complete` to continue",
                "→".dimmed()
            );
        }
        BatchDrainOutcome::Failed(phase) => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} next {n} drain stopped at {} (phase {} failed)",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                stopped.bold(),
                phase.index()
            );
            eprintln!(
                "  {} already shipped ({count}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} the rest of the queue is untouched — fix {stopped} (hint above), then re-run",
                "→".dimmed()
            );
        }
        BatchDrainOutcome::Stalled => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} next {n} drain stopped — {} stayed at the head after a successful run \
                 (queue did not advance)",
                crate::glyph(crate::glyphs::Glyph::Cross).red().bold(),
                stopped.bold()
            );
            eprintln!(
                "  {} already shipped ({count}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} check {stopped}'s status (`aida show {stopped}`) — it may not have \
                 been dequeued",
                "→".dimmed()
            );
        }
        // BUG-245: phase 1 shipped a different spec than the dispatched head.
        // Credit the truth, name what stayed queued. trace:BUG-245 | ai:claude
        BatchDrainOutcome::Mismatched {
            dispatched,
            shipped,
        } => {
            eprintln!(
                "{} next {n} drain stopped — phase 1 was dispatched for {} \
                 but the PR credited {}",
                crate::glyph(crate::glyphs::Glyph::Info).cyan().bold(),
                dispatched.bold(),
                shipped.bold(),
            );
            eprintln!(
                "  {} already shipped ({count}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} {} is still queued — pick it back up with `aida queue work {}`, \
                 or remove it with `aida queue remove {}` if {} subsumed it",
                "→".dimmed(),
                dispatched,
                dispatched,
                dispatched,
                shipped,
            );
        }
        // BUG-257: a transient GH-API outage during phase-1 PR lookup paused
        // the drain. The spec stays in its current state for retry.
        // trace:BUG-257 | ai:claude
        BatchDrainOutcome::Inconclusive => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} next {n} drain paused at {} — phase 1 inconclusive \
                 (GH API unreachable)",
                "⏸".yellow().bold(),
                stopped.bold(),
            );
            eprintln!(
                "  {} already shipped ({count}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} transient — retry once the API is reachable: \
                 `gh api /rate_limit` then re-run",
                "→".dimmed()
            );
        }
        // BUG-250: a member deliberately held its PR — pause for the gate.
        // trace:BUG-250 | ai:claude
        BatchDrainOutcome::Held => {
            let stopped = result.stopped_at.as_deref().unwrap_or("<spec>");
            eprintln!(
                "{} next {n} drain paused at {} — PR deliberately held",
                "⏸".yellow().bold(),
                stopped.bold(),
            );
            eprintln!(
                "  {} already shipped ({count}): {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                shipped_list
            );
            eprintln!(
                "  {} run your gate, open the PR (`gh pr create`), then re-run",
                "→".dimmed()
            );
        }
        // EPIC-28 trace:EPIC-28 | ai:claude
        BatchDrainOutcome::DrainedWithShelved => {
            eprintln!(
                "{} next {n} drained with shelved members — \
                 {count} spec{plural} shipped: {}",
                crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
                shipped_list.bold()
            );
        }
    }
    // STORY-276: name the members a headless implementer punted — the drain
    // advanced past them, but they parked in Needs Attention rather than
    // shipping, so they need advisor triage.
    if !result.punted.is_empty() {
        let pn = result.punted.len();
        eprintln!(
            "  {} {pn} spec{} punted to Needs Attention: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if pn == 1 { "" } else { "s" },
            result.punted.join(", ")
        );
    }
    // STORY-306: name the members the drain escalated to a human.
    if !result.escalated.is_empty() {
        let en = result.escalated.len();
        eprintln!(
            "  {} {en} spec{} escalated to a human: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if en == 1 { "" } else { "s" },
            result.escalated.join(", ")
        );
    }
    // EPIC-28: shelved + skipped members. trace:EPIC-28 | ai:claude
    if !result.shelved.is_empty() {
        let sn = result.shelved.len();
        eprintln!(
            "  {} {sn} spec{} shelved on phase failure: {} — triage with \
             `aida findings list`",
            "⏸".yellow(),
            if sn == 1 { "" } else { "s" },
            result.shelved.join(", ")
        );
    }
    if !result.skipped.is_empty() {
        let kn = result.skipped.len();
        let render: Vec<String> = result
            .skipped
            .iter()
            .map(|(spec, reason)| format!("{spec} ({reason})"))
            .collect();
        eprintln!(
            "  {} {kn} dependent spec{} skipped: {}",
            "⤳".yellow(),
            if kn == 1 { "" } else { "s" },
            render.join(", ")
        );
    }
}

/// TASK-266: append this `--auto-complete` run to
/// `~/.aida/auto-complete.jsonl` and, on a phase failure, auto-draft a Draft
/// BUG for the failure. Honours the same opt-out as `aida usage`
/// (`AIDA_TELEMETRY=0` / `[telemetry] enabled = false`). Best-effort
/// throughout — telemetry must never break or delay the orchestrator exit.
/// trace:TASK-266 | ai:claude
#[allow(clippy::too_many_arguments)]
fn record_auto_complete_run(
    driver: &RealPhaseDriver,
    project_root: &std::path::Path,
    spec: &str,
    variant: auto_complete::AutoCompleteVariant,
    result: &auto_complete::OrchestrationResult,
    started_at: chrono::DateTime<chrono::Utc>,
    completed_at: chrono::DateTime<chrono::Utc>,
    json: bool,
    lifecycle_skip: auto_complete::LifecycleSkip,
) {
    if !usage::is_enabled(Some(project_root)) {
        return;
    }

    let phase_durations: Vec<auto_complete_telemetry::PhaseDuration> = result
        .phase_durations
        .iter()
        .map(|(phase, ms)| auto_complete_telemetry::PhaseDuration {
            phase: phase.index() as u8,
            slug: phase.slug().to_string(),
            elapsed_ms: *ms as u64,
        })
        .collect();

    let mut event = auto_complete_telemetry::AutoCompleteEvent {
        spec_id: spec.to_string(),
        started_at: started_at.to_rfc3339(),
        completed_at: completed_at.to_rfc3339(),
        outcome: if result.exit_code == 0 {
            "success".to_string()
        } else {
            "failed".to_string()
        },
        variant: variant.slug().to_string(),
        failed_phase: result.failed_phase.map(|p| p.index() as u8),
        failure_kind: result.failure.as_ref().map(|f| f.kind.slug().to_string()),
        failure_message: result.failure.as_ref().map(|f| f.reason.clone()),
        phase_durations,
        total_ms: result.total_ms as u64,
        drafted_bug: None,
        binary_sha: build_sha_short(),
        auto_rebase: driver.auto_rebase_events.clone(),
        lifecycle_skips: lifecycle_skip.active_tokens(),
    };

    // On a phase failure, attach a Draft BUG. Reuse the BUG from a recent
    // identical failure (same spec / phase / kind, within 24h) rather than
    // spamming the backlog when a still-broken `--auto-complete` is re-run.
    if let (Some(phase), Some(failure)) = (result.failed_phase, result.failure.as_ref()) {
        match existing_failure_bug(spec, phase, failure) {
            Some(existing) => {
                if !json {
                    eprintln!(
                        "  {} this failure recurs — tracked in {} (no new BUG drafted)",
                        "📋".dimmed(),
                        existing.cyan(),
                    );
                }
                event.drafted_bug = Some(existing);
            }
            // BUG-657: suppress the auto-file entirely when the failure is
            // ENVIRONMENTAL (disk full / OOM) — the auto-draft text itself tells
            // the triager to reject those, so filing one just creates a Draft to
            // immediately reject. The telemetry line still records the failure.
            None if auto_complete::is_environmental_failure(&failure.reason) => {
                if !json {
                    eprintln!(
                        "  {} environmental failure (disk/OOM) — not auto-drafting a BUG \
                         (fix the host, then re-drive)",
                        "📋".dimmed(),
                    );
                }
            }
            None => {
                let hint = auto_complete::recovery_hint(
                    phase,
                    failure.kind,
                    &auto_complete::PhaseDriver::hint_context(driver),
                );
                if let Some(bug_id) =
                    draft_auto_complete_failure_bug(spec, phase, failure, &hint, &event)
                {
                    if !json {
                        eprintln!(
                            "  {} auto-drafted {} for this failure — triage it: `aida show {}`",
                            "📋".dimmed(),
                            bug_id.cyan(),
                            bug_id,
                        );
                    }
                    event.drafted_bug = Some(bug_id);
                }
            }
        }
    }

    auto_complete_telemetry::append_event(&event);

    // SPIKE-67 slice 3: record any stated-rule violation this drain observed
    // (CI red on fmt/clippy/provenance, a reviewer RequestChanges on a rule, or
    // a punt citing a rule) — the real-time gate-vs-rule evidence path. Reuses
    // the failure the orchestrator already classified; observe-only, opt-in,
    // privacy-floor-preserving, best-effort. trace:SPIKE-67 | ai:claude
    let outcome = rule_violation::DrainOutcome {
        failed_phase_slug: result.failed_phase.map(|p| p.slug()),
        failure_kind: result.failure.as_ref().map(|f| f.kind.slug()),
        failure_message: result.failure.as_ref().map(|f| f.reason.as_str()),
        punt_reason: result.punt_reason.as_deref(),
    };
    rule_violation::record(
        project_root,
        &outcome,
        spec,
        driver.no_human.is_some(),
        variant.slug(),
        build_sha_short(),
    );
}

/// TASK-266 / BUG-657: find the Draft BUG already auto-filed for an identical
/// recent failure — same spec, same phase, same failure kind, within the last
/// 24h — so re-running a still-broken `--auto-complete` reuses one BUG instead
/// of spamming the backlog. The dedup decision is the pure
/// [`auto_complete_telemetry::dedup_failure_bug`] over the read events; this
/// wrapper just supplies the global JSONL log + the 24h cutoff.
// trace:TASK-266 trace:BUG-657 | ai:claude
fn existing_failure_bug(
    spec: &str,
    phase: auto_complete::Phase,
    failure: &auto_complete::PhaseFailure,
) -> Option<String> {
    let cutoff = chrono::Utc::now() - chrono::Duration::hours(24);
    auto_complete_telemetry::dedup_failure_bug(
        &auto_complete_telemetry::read_events(),
        spec,
        phase.index() as u8,
        failure.kind.slug(),
        cutoff,
    )
}

/// TASK-266: auto-file a Draft BUG for an `--auto-complete` phase failure.
/// The BUG is intentionally left in Draft and NOT queued — the user triages
/// it and promotes it to Approved only if it is a real AIDA bug (vs a user
/// error or a local environment issue). Returns the new BUG's spec-id, or
/// `None` if the `aida add` subprocess could not run (best-effort — the
/// JSONL log still captures the failure either way). trace:TASK-266 | ai:claude
fn draft_auto_complete_failure_bug(
    spec: &str,
    phase: auto_complete::Phase,
    failure: &auto_complete::PhaseFailure,
    hint: &str,
    event: &auto_complete_telemetry::AutoCompleteEvent,
) -> Option<String> {
    let phase_n = phase.index();
    let phase_name = phase.slug();
    let title = format!("auto-complete failure: phase {phase_n} ({phase_name}) on {spec}");
    let tags = format!("auto-complete,failure-{phase_n},auto-drafted,{phase_name}");
    let json_line = serde_json::to_string(event).unwrap_or_default();
    let durations = if event.phase_durations.is_empty() {
        "  (none recorded)".to_string()
    } else {
        event
            .phase_durations
            .iter()
            .map(|d| format!("  - phase {} ({}): {} ms", d.phase, d.slug, d.elapsed_ms))
            .collect::<Vec<_>>()
            .join("\n")
    };
    let description = format!(
        "Auto-drafted by `aida queue work {spec} --auto-complete` after phase {phase_n} \
({phase_name}) failed. Review this BUG and promote it to Approved if it is a real AIDA \
orchestrator bug — or reject it if it was a user error or a local environment issue. It \
is intentionally left in Draft and NOT queued. (TASK-266)\n\n\
## Failure\n\n\
{reason}\n\n\
Failure kind: `{kind}`\n\n\
## Recovery hint shown to the user\n\n\
{hint}\n\n\
## Phase durations\n\n\
{durations}\n\n\
## Telemetry entry\n\n\
The line appended to `~/.aida/auto-complete.jsonl` for this run:\n\n\
```json\n{json_line}\n```\n\n\
## Recurse-fix\n\n\
Once triaged and promoted, this BUG can itself be driven by the orchestrator: \
`aida queue work <THIS-BUG> --auto-complete` — the dogfood loop TASK-266 makes \
operational.\n",
        reason = failure.reason,
        kind = failure.kind.slug(),
    );

    // Re-resolve the binary fresh (a phase-6 `cargo build` may have replaced
    // the one the orchestrator started with — BUG-217). Try the EPIC-23
    // parent first (this repo dogfoods the orchestrator); fall back to a
    // parent-less add so the auto-draft still works in any other project
    // that has no EPIC-23.
    let exe = resolve_aida_exe();
    add_draft_bug(&exe, &title, &tags, &description, Some("EPIC-23"))
        .or_else(|| add_draft_bug(&exe, &title, &tags, &description, None))
}

/// Run `aida add` to file the Draft BUG, returning the new spec-id parsed
/// from stdout. `NO_COLOR` is set on the child so the `ID:` line is plain
/// text. trace:TASK-266 | ai:claude
fn add_draft_bug(
    exe: &std::path::Path,
    title: &str,
    tags: &str,
    description: &str,
    parent: Option<&str>,
) -> Option<String> {
    use std::io::Write;
    let mut args: Vec<String> = vec![
        "add".into(),
        "--type".into(),
        "bug".into(),
        "--status".into(),
        "draft".into(),
        "--title".into(),
        title.into(),
        "--tags".into(),
        tags.into(),
        "--description-stdin".into(),
    ];
    if let Some(p) = parent {
        args.push("--parent".into());
        args.push(p.into());
    }
    let mut child = std::process::Command::new(exe)
        .args(&args)
        .env("NO_COLOR", "1")
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .ok()?;
    child.stdin.take()?.write_all(description.as_bytes()).ok()?;
    let out = child.wait_with_output().ok()?;
    if !out.status.success() {
        return None;
    }
    parse_added_spec_id(&String::from_utf8_lossy(&out.stdout))
}

/// Parse the `ID: <SPEC-ID>` line that `aida add` prints on success.
/// trace:TASK-266 | ai:claude
fn parse_added_spec_id(stdout: &str) -> Option<String> {
    stdout
        .lines()
        .find_map(|l| l.trim().strip_prefix("ID:"))
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
}

